export interface UpdateLeadRequest {
    name?: string;
    email?: string;
    phone?: string;
    company?: string;
    source?: string;
    stage?: Lead['stage'];
    priority?: Lead['priority'];
    estimatedValue?: number;
    currency?: string;
    notes?: string;
    tags?: string[];
    documents?: LeadDocumentPayload[];
    links?: LeadLinkPayload[];
    assignedTo?: string | null;
    partnerId?: string | null;
