    type: 'internal' | 'external';
    title: string;
    notes?: string;
    date?: string;
}

// ============================================
// PROPOSAL API TYPES
// ============================================
export interface CreateProposalRequest {
    title: string;
    leadId: string;
    clientId?: string;
    validUntil?: string;
    scope?: string;
    items: {
        description: string;
        quantity: number;
        unitPrice: number;
        total?: number;
    }[];
    tax?: number;
    currency?: string;
    notes?: string;
}

