            invalidatesTags: ['BankTransactions', 'FinanceDashboard'],
        }),

        updateOtherBankAccount: builder.mutation<{ data: BankAccountDetail }, { id: string } & Partial<OtherBankAccountRequest>>({
            query: ({ id, ...body }) => ({
                url: `/finance/bank-accounts/other/${id}`,
                method: 'PUT',
                body,
            }),
            invalidatesTags: ['BankTransactions', 'FinanceDashboard'],
        }),

