            query: (body) => ({
                url: '/admin/users',
                method: 'POST',
                body,
            }),
            invalidatesTags: ['AdminUsers'],
        }),

        updateAdminUser: builder.mutation<
            ApiResponse<AdminUser>,
            { id: string; data: UpdateUserPayload }
        >({
            query: ({ id, data }) => ({
