                body: data,
            }),
            invalidatesTags: ['Roles'],
        }),

        deleteAdminRole: builder.mutation<ApiResponse, string>({
            query: (id) => ({
                url: `/admin/roles/${id}`,
                method: 'DELETE',
            }),
            invalidatesTags: ['Roles'],
        }),

