import { useState, useEffect } from 'react';
import { X, Shield, Eye, Users, Check, ChevronRight, Loader2, Code, TerminalSquare, Lock, FileText } from 'lucide-react';
import {
    useGetCredentialsQuery,
    useShareCredentialsMutation,
    useGetCredentialAdminsQuery,
    useUpdateCredentialAdminsMutation,
} from '@/features/project';
import type { Project, Credential } from '@/features/project';
import useBodyScrollLock from '@/hooks/useBodyScrollLock';

// ─── Types ───────────────────────────────────────────────────────────────────
interface CredentialShareModalProps {
    project: Project;
    projectId: string;
    onClose: () => void;
}

type ModalTab = 'edit' | 'view';

type CredentialCategory = 'env' | 'ssh-key' | 'test-user' | 'account' | 'other';

const CATEGORIES: { id: CredentialCategory; label: string; icon: any }[] = [
    { id: 'env', label: 'Env Variables', icon: Code },
    { id: 'ssh-key', label: 'SSH Keys', icon: TerminalSquare },
    { id: 'test-user', label: 'Testing', icon: Lock },
    { id: 'account', label: 'Accounts', icon: Users },
    { id: 'other', label: 'Other', icon: FileText },
];

// ─── Helpers ─────────────────────────────────────────────────────────────────
function getProjectMembers(project: Project): { userId: string; name: string; email: string }[] {
    const seen = new Set<string>();
    const members: { userId: string; name: string; email: string }[] = [];

    project.assignees?.forEach((a: any) => {
        // Extract User ID - try multiple sources in order of preference:
        // 1. Direct userId field (if it's a string, it's the User ID)
        // 2. Populated userId object's _id
        // 3. Populated employeeId.userId._id (for CU employees)
        // Note: Partner employees don't have User records, so we skip them for admin assignment
        let userId: string | undefined;

        if (typeof a.userId === 'string' && a.userId) {
            userId = a.userId.trim();
        } else if (a.userId && typeof a.userId === 'object' && a.userId._id) {
            const id = typeof a.userId._id === 'string' ? a.userId._id : a.userId._id?.toString?.();
            userId = id?.trim();
        } else if (a.employeeId?.userId?._id) {
            const id = typeof a.employeeId.userId._id === 'string'
                ? a.employeeId.userId._id
                : a.employeeId.userId._id?.toString?.();
            userId = id?.trim();
        }

        // Only include members with valid User IDs (skip partner employees without User records)
        if (userId && !seen.has(userId)) {
            seen.add(userId);
            members.push({
                userId,
                name: a.displayName ?? a.employeeId?.userId?.name ?? 'Team Member',
                email: a.displayEmail ?? a.employeeId?.userId?.email ?? '',
            });
        }
    });

    return members;
}

// ─── Sub-components ───────────────────────────────────────────────────────────

function MemberCheckbox({
    member,
    selected,
    onChange,
}: {
    member: { userId: string; name: string; email: string };
    selected: boolean;
    onChange: (id: string) => void;
}) {
    return (
        <button
            type="button"
            onClick={() => onChange(member.userId)}
            className="flex items-center gap-3 w-full px-3 py-2.5 rounded-lg border text-left transition-colors"
            style={{
                borderColor: selected ? 'var(--color-success)' : 'var(--color-border-default)',
                backgroundColor: selected ? 'var(--color-success-soft)' : 'var(--color-bg-surface)',
            }}
        >
            <div
                className="w-4 h-4 rounded border flex items-center justify-center shrink-0 transition-colors"
                style={{
                    borderColor: selected ? 'var(--color-success)' : 'var(--color-border-default)',
                    backgroundColor: selected ? 'var(--color-success)' : 'transparent',
                }}
            >
                {selected && <Check size={10} className="text-white" />}
            </div>
            <div className="min-w-0">
                <p className="text-sm font-medium truncate" style={{ color: 'var(--color-text-primary)' }}>
                    {member.name}
                </p>
                {member.email && (
                    <p className="text-xs truncate" style={{ color: 'var(--color-text-muted)' }}>
                        {member.email}
                    </p>
                )}
            </div>
        </button>
    );
}

function CredentialCheckbox({
    credential,
    selected,
    onChange,
}: {
    credential: Credential;
    selected: boolean;
    onChange: (id: string) => void;
}) {
    return (
        <button
            type="button"
            onClick={() => onChange(credential._id)}
            className="flex items-center gap-3 w-full px-3 py-2.5 rounded-lg border text-left transition-colors"
            style={{
                borderColor: selected ? 'var(--color-success)' : 'var(--color-border-default)',
                backgroundColor: selected ? 'var(--color-success-soft)' : 'var(--color-bg-surface)',
            }}
        >
            <div
                className="w-4 h-4 rounded border flex items-center justify-center shrink-0 transition-colors"
                style={{
                    borderColor: selected ? 'var(--color-success)' : 'var(--color-border-default)',
                    backgroundColor: selected ? 'var(--color-success)' : 'transparent',
                }}
            >
                {selected && <Check size={10} className="text-white" />}
            </div>
            <div className="min-w-0">
                <p className="text-sm font-medium truncate" style={{ color: 'var(--color-text-primary)' }}>
                    {credential.name}
                </p>
                {credential.description && (
                    <p className="text-xs truncate" style={{ color: 'var(--color-text-muted)' }}>
                        {credential.description}
                    </p>
                )}
            </div>
        </button>
    );
}

// ─── Edit Access Tab ──────────────────────────────────────────────────────────
function EditAccessTab({ project, projectId }: { project: Project; projectId: string }) {
    const { data: adminsData, isLoading: adminsLoading } = useGetCredentialAdminsQuery({ projectId });
    const [updateAdmins, { isLoading: isSaving }] = useUpdateCredentialAdminsMutation();

    const members = getProjectMembers(project);

    const [selectedAdminIds, setSelectedAdminIds] = useState<string[]>([]);
    const [saved, setSaved] = useState(false);

    // Extract admin IDs from the backend response, ensuring they're trimmed strings
    const extractAdminIds = (data: any[] | undefined): string[] => {
        return (data ?? []).map((a: any) => {
            const id = typeof a === 'string' ? a : a._id;
            return typeof id === 'string' ? id.trim() : '';
        }).filter(Boolean);
    };

    // Sync selectedAdminIds once the admins data has loaded
    useEffect(() => {
        if (!adminsLoading && adminsData?.data) {
            setSelectedAdminIds(extractAdminIds(adminsData.data));
        }
    }, [adminsLoading, adminsData]);

    const toggleAdmin = (uid: string) => {
        const trimmedUid = uid.trim();
        setSelectedAdminIds((prev) =>
            prev.includes(trimmedUid) ? prev.filter((id) => id !== trimmedUid) : [...prev, trimmedUid]
        );
        setSaved(false);
    };

    const handleSave = async () => {
        try {
            await updateAdmins({ projectId, data: { userIds: selectedAdminIds } }).unwrap();
            setSaved(true);
            setTimeout(() => setSaved(false), 2000);
        } catch (e) {
            console.error(e);
        }
    };

    return (
        <div className="space-y-4">
            <p className="text-sm" style={{ color: 'var(--color-text-secondary)' }}>
                Credential Admins can <strong>view, add, edit, and delete</strong> all credentials, and can also manage who has view access.
            </p>

            {adminsLoading ? (
                <div className="flex justify-center py-6">
                    <Loader2 size={20} className="animate-spin" style={{ color: 'var(--color-text-muted)' }} />
                </div>
            ) : members.length === 0 ? (
                <p className="text-sm py-4 text-center" style={{ color: 'var(--color-text-muted)' }}>
                    No team members assigned to this project yet.
                </p>
            ) : (
                <div className="space-y-2">
                    {members.map((m) => (
                        <MemberCheckbox
                            key={m.userId}
                            member={m}
                            selected={selectedAdminIds.includes(m.userId)}
                            onChange={toggleAdmin}
                        />
                    ))}
                </div>
            )}

            <div className="flex justify-end pt-2 border-t" style={{ borderColor: 'var(--color-border-default)' }}>
                <button
                    type="button"
                    onClick={handleSave}
                    disabled={isSaving}
                    className="flex items-center gap-2 px-5 py-2 text-sm font-semibold text-white rounded-lg disabled:opacity-50 transition-colors"
                    style={{ backgroundColor: saved ? 'var(--color-success-dark, #16a34a)' : 'var(--color-success)' }}
                >
                    {isSaving ? (
                        <Loader2 size={14} className="animate-spin" />
                    ) : saved ? (
                        <Check size={14} />
                    ) : (
                        <Shield size={14} />
                    )}
                    {isSaving ? 'Saving…' : saved ? 'Saved!' : 'Save Edit Access'}
                </button>
            </div>
        </div>
    );
}

// ─── View Access Tab ──────────────────────────────────────────────────────────
function ViewAccessTab({ project, projectId }: { project: Project; projectId: string }) {
    const [category, setCategory] = useState<CredentialCategory>('env');
    const [step, setStep] = useState<1 | 2>(1);
    const [selectedCredIds, setSelectedCredIds] = useState<string[]>([]);
    const [selectedUserIds, setSelectedUserIds] = useState<string[]>([]);
    const [shareCredentials, { isLoading: isSharing }] = useShareCredentialsMutation();
    const [sharedSuccessfully, setSharedSuccessfully] = useState(false);

    const { data, isLoading: credsLoading } = useGetCredentialsQuery({ projectId, type: category });
    const credentials: Credential[] = data?.data ?? [];
    const members = getProjectMembers(project);

    const toggleCred = (id: string) => {
        setSelectedCredIds((prev) =>
            prev.includes(id) ? prev.filter((c) => c !== id) : [...prev, id]
        );
    };

    const toggleUser = (id: string) => {
        setSelectedUserIds((prev) =>
            prev.includes(id) ? prev.filter((u) => u !== id) : [...prev, id]
        );
    };

    const handleShare = async () => {
        if (!selectedCredIds.length || !selectedUserIds.length) return;
        try {
            await shareCredentials({
                projectId,
                data: { credentialIds: selectedCredIds, userIds: selectedUserIds },
            }).unwrap();
            setSharedSuccessfully(true);
            setSelectedCredIds([]);
            setSelectedUserIds([]);
            setStep(1);
            setTimeout(() => setSharedSuccessfully(false), 3000);
        } catch (e) {
            console.error(e);
        }
    };

    return (
        <div className="space-y-4">
            <p className="text-sm" style={{ color: 'var(--color-text-secondary)' }}>
                Select specific credentials to share, then choose which team members can view them.
            </p>

            {sharedSuccessfully && (
                <div
                    className="flex items-center gap-2 px-3 py-2.5 rounded-lg text-sm font-medium"
                    style={{ backgroundColor: 'var(--color-success-soft)', color: 'var(--color-success)' }}
                >
                    <Check size={14} /> Credentials shared successfully.
                </div>
            )}

            {/* Step Indicator */}
            <div className="flex items-center gap-2 text-xs font-semibold">
                <span
                    className="px-3 py-1 rounded-full"
                    style={{
                        backgroundColor: step === 1 ? 'var(--color-success)' : 'var(--color-bg-subtle)',
                        color: step === 1 ? 'white' : 'var(--color-text-secondary)',
                    }}
                >
                    1. Select Credentials
                </span>
                <ChevronRight size={14} style={{ color: 'var(--color-text-muted)' }} />
                <span
                    className="px-3 py-1 rounded-full"
                    style={{
                        backgroundColor: step === 2 ? 'var(--color-success)' : 'var(--color-bg-subtle)',
                        color: step === 2 ? 'white' : 'var(--color-text-secondary)',
                    }}
                >
                    2. Choose Team Members
                </span>
            </div>

            {/* ── STEP 1: Category + Credential selection ── */}
            {step === 1 && (
                <div className="space-y-3">
                    {/* Category sub-tabs */}
                    <div className="flex flex-wrap gap-1">
                        {CATEGORIES.map((cat) => {
                            const Icon = cat.icon;
                            const isActive = category === cat.id;
                            return (
                                <button
                                    key={cat.id}
                                    type="button"
                                    onClick={() => setCategory(cat.id)}
                                    className="flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-medium transition-colors"
                                    style={{
                                        backgroundColor: isActive ? 'var(--color-success-soft)' : 'var(--color-bg-subtle)',
                                        color: isActive ? 'var(--color-success)' : 'var(--color-text-secondary)',
                                        border: `1px solid ${isActive ? 'var(--color-success)' : 'var(--color-border-default)'}`,
                                    }}
                                >
                                    <Icon size={12} />
                                    {cat.label}
                                </button>
                            );
                        })}
                    </div>

                    {/* Credential list */}
                    <div
                        className="rounded-lg border overflow-hidden"
                        style={{ borderColor: 'var(--color-border-default)', maxHeight: '260px', overflowY: 'auto' }}
                    >
                        {credsLoading ? (
                            <div className="flex justify-center py-6">
                                <Loader2 size={18} className="animate-spin" style={{ color: 'var(--color-text-muted)' }} />
                            </div>
                        ) : credentials.length === 0 ? (
                            <p className="text-sm py-6 text-center" style={{ color: 'var(--color-text-muted)' }}>
                                No credentials in this category yet.
                            </p>
                        ) : (
                            <div className="p-2 space-y-1.5">
                                {credentials.map((cred) => (
                                    <CredentialCheckbox
                                        key={cred._id}
                                        credential={cred}
                                        selected={selectedCredIds.includes(cred._id)}
                                        onChange={toggleCred}
                                    />
                                ))}
                            </div>
                        )}
                    </div>

                    {selectedCredIds.length > 0 && (
                        <p className="text-xs" style={{ color: 'var(--color-text-muted)' }}>
                            {selectedCredIds.length} credential{selectedCredIds.length > 1 ? 's' : ''} selected (you can switch categories to select more)
                        </p>
                    )}

                    <div className="flex justify-end pt-1">
                        <button
                            type="button"
                            onClick={() => setStep(2)}
                            disabled={selectedCredIds.length === 0}
                            className="flex items-center gap-2 px-5 py-2 text-sm font-semibold text-white rounded-lg disabled:opacity-40 transition-colors"
                            style={{ backgroundColor: 'var(--color-success)' }}
                        >
                            Next: Choose Members <ChevronRight size={14} />
                        </button>
                    </div>
                </div>
            )}

            {/* ── STEP 2: Team member selection ── */}
            {step === 2 && (
                <div className="space-y-3">
                    <div className="flex items-center justify-between">
                        <p className="text-xs font-semibold uppercase tracking-wider" style={{ color: 'var(--color-text-secondary)' }}>
                            Team Members
                        </p>
                        <button
                            type="button"
                            onClick={() => setStep(1)}
                            className="text-xs underline"
                            style={{ color: 'var(--color-text-muted)' }}
                        >
                            ← Back to credentials
                        </button>
                    </div>

                    {members.length === 0 ? (
                        <p className="text-sm py-4 text-center" style={{ color: 'var(--color-text-muted)' }}>
                            No team members assigned to this project.
                        </p>
                    ) : (
                        <div
                            className="space-y-1.5 overflow-y-auto"
                            style={{ maxHeight: '260px' }}
                        >
                            {members.map((m) => (
                                <MemberCheckbox
                                    key={m.userId}
                                    member={m}
                                    selected={selectedUserIds.includes(m.userId)}
                                    onChange={toggleUser}
                                />
                            ))}
                        </div>
                    )}

                    <div className="flex justify-end gap-3 pt-2 border-t" style={{ borderColor: 'var(--color-border-default)' }}>
                        <p className="text-xs self-center" style={{ color: 'var(--color-text-muted)' }}>
                            {selectedCredIds.length} credential{selectedCredIds.length !== 1 ? 's' : ''} · {selectedUserIds.length} member{selectedUserIds.length !== 1 ? 's' : ''} selected
                        </p>
                        <button
                            type="button"
                            onClick={handleShare}
                            disabled={isSharing || selectedUserIds.length === 0 || selectedCredIds.length === 0}
                            className="flex items-center gap-2 px-5 py-2 text-sm font-semibold text-white rounded-lg disabled:opacity-40 transition-colors"
                            style={{ backgroundColor: 'var(--color-success)' }}
                        >
                            {isSharing ? <Loader2 size={14} className="animate-spin" /> : <Eye size={14} />}
                            {isSharing ? 'Sharing…' : 'Share Access'}
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
}

// ─── Main Modal ───────────────────────────────────────────────────────────────
export default function CredentialShareModal({ project, projectId, onClose }: CredentialShareModalProps) {
    const [activeTab, setActiveTab] = useState<ModalTab>('edit');

    useBodyScrollLock(true);

    return (
        <>
            {/* Dim backdrop — click to close */}
            <div
                className="fixed inset-0 z-[200]"
                style={{ backgroundColor: 'rgba(0,0,0,0.22)' }}
                onClick={onClose}
            />

            {/* Right side panel */}
            <div
                className="fixed top-0 right-0 h-full z-[201] flex flex-col"
                style={{
                    width: 'min(520px, 100vw)',
                    backgroundColor: 'var(--color-bg-surface)',
                    borderLeft: '1px solid var(--color-border-default)',
                    boxShadow: '-16px 0 48px rgba(0,0,0,0.13)',
                    animation: 'slideInRight 0.28s cubic-bezier(0.22, 1, 0.36, 1) both',
                }}
            >
                {/* Header */}
                <div
                    className="flex items-center justify-between px-5 py-4 border-b shrink-0"
                    style={{ borderColor: 'var(--color-border-default)' }}
                >
                    <div className="flex items-center gap-2">
                        <Shield size={18} style={{ color: 'var(--color-success)' }} />
                        <h2 className="text-base font-semibold" style={{ color: 'var(--color-text-primary)' }}>
                            Manage Credential Access
                        </h2>
                    </div>
                    <button
                        onClick={onClose}
                        className="p-1.5 rounded transition-colors hover:bg-black/5"
                        style={{ color: 'var(--color-text-muted)' }}
                    >
                        <X size={16} />
                    </button>
                </div>

                {/* Tab Bar */}
                <div
                    className="flex border-b shrink-0"
                    style={{ borderColor: 'var(--color-border-default)' }}
                >
                    {[
                        { id: 'edit' as ModalTab, label: 'Edit Access', icon: Shield, desc: 'Full control' },
                        { id: 'view' as ModalTab, label: 'View Access', icon: Eye, desc: 'Per credential' },
                    ].map((tab) => {
                        const Icon = tab.icon;
                        const isActive = activeTab === tab.id;
                        return (
                            <button
                                key={tab.id}
                                type="button"
                                onClick={() => setActiveTab(tab.id)}
                                className="flex items-center gap-2 px-5 py-3 text-sm font-medium border-b-2 transition-colors flex-1 justify-center"
                                style={{
                                    color: isActive ? 'var(--color-success)' : 'var(--color-text-secondary)',
                                    borderColor: isActive ? 'var(--color-success)' : 'transparent',
                                    backgroundColor: isActive ? 'var(--color-success-soft)' : 'transparent',
                                }}
                            >
                                <Icon size={15} />
                                <span>{tab.label}</span>
                                <span
                                    className="text-xs px-1.5 py-0.5 rounded-full"
                                    style={{
                                        backgroundColor: isActive ? 'var(--color-success)' : 'var(--color-bg-subtle)',
                                        color: isActive ? 'white' : 'var(--color-text-muted)',
                                    }}
                                >
                                    {tab.desc}
                                </span>
                            </button>
                        );
                    })}
                </div>

                {/* Body — scrollable */}
                <div className="p-5 overflow-y-auto flex-1">
                    {activeTab === 'edit' ? (
                        <EditAccessTab project={project} projectId={projectId} />
                    ) : (
                        <ViewAccessTab project={project} projectId={projectId} />
                    )}
                </div>
            </div>
        </>
    );
}

import { api } from '@/services/api';
import toast from 'react-hot-toast';
import type {
    Project,
    Task,
    TimeLog,
    Meeting,
    Credential,
    DocFolder,
    DocItem,
    DocAdminUser,
    Note,
} from './types/types';
import type {
    CreateProjectRequest,
    UpdateProjectRequest,
    AddAssigneeRequest,
    CreateTaskRequest,
    UpdateTaskRequest,
    CreateTimeLogRequest,
    UpdateTimeLogRequest,
    CreateMeetingRequest,
    UpdateMeetingRequest,
    CreateCredentialRequest,
    UpdateCredentialRequest,
    ShareCredentialsRequest,
    RevokeCredentialAccessRequest,
    UpdateCredentialAdminsRequest,
    CreateNoteRequest,
    UpdateNoteRequest,
    ApiResponse,
    UpdateAssigneePermissionsRequest,
} from './types/apiTypes';

export const projectApi = api.injectEndpoints({
    endpoints: (builder) => ({
        // ============================================
        // PROJECT ENDPOINTS
        // ============================================
        getProjects: builder.query<ApiResponse<Project[]>, { status?: string; clientId?: string; priority?: string; partnerId?: string }>({
            query: (params) => ({
                url: '/projects',
                params,
            }),
            providesTags: ['Projects'],
        }),

        getProjectById: builder.query<ApiResponse<Project>, string>({
            query: (id) => `/projects/${id}`,
            providesTags: (_result, _error, id) => [{ type: 'Projects', id }],
        }),

        createProject: builder.mutation<ApiResponse<Project>, CreateProjectRequest>({
            query: (data) => ({
                url: '/projects',
                method: 'POST',
                body: data,
            }),
            invalidatesTags: ['Projects'],
        }),

        updateProject: builder.mutation<ApiResponse<Project>, { id: string; data: UpdateProjectRequest }>({
            query: ({ id, data }) => ({
                url: `/projects/${id}`,
                method: 'PATCH',
                body: data,
            }),
            invalidatesTags: (_result, _error, { id }) => [{ type: 'Projects', id }, 'Projects'],
        }),

        deleteProject: builder.mutation<ApiResponse<Project>, string>({
            query: (id) => ({
                url: `/projects/${id}`,
                method: 'DELETE',
            }),
            async onQueryStarted(id, { dispatch, queryFulfilled }) {
                toast.promise(queryFulfilled, {
                    loading: 'Deleting project...',
                    success: 'Project deleted successfully',
                    error: 'Failed to delete project',
                });
                const patchResult = dispatch(
                    api.util.updateQueryData('getProjects' as never, undefined as never, (draft: any) => {
                       if (draft?.data) {
                           draft.data = draft.data.filter((p: any) => p._id !== id);
                       }
                    })
                );
                try {
                    await queryFulfilled;
                } catch {
                    patchResult.undo();
                }
            },
            invalidatesTags: ['Projects'],
        }),

        addAssignee: builder.mutation<ApiResponse<Project>, { projectId: string; data: AddAssigneeRequest }>({
            query: ({ projectId, data }) => ({
                url: `/projects/${projectId}/assignees`,
                method: 'POST',
                body: data,
            }),
            invalidatesTags: (_result, _error, { projectId }) => [{ type: 'Projects', id: projectId }, 'Projects', 'User'],
        }),

        removeAssignee: builder.mutation<ApiResponse<Project>, { projectId: string; memberId: string }>({
            query: ({ projectId, memberId }) => ({
                url: `/projects/${projectId}/assignees/${memberId}`,
                method: 'DELETE',
            }),
            invalidatesTags: (_result, _error, { projectId }) => [{ type: 'Projects', id: projectId }, 'Projects', 'User'],
        }),

        updateAssigneePermissions: builder.mutation<ApiResponse<void>, { projectId: string; memberId: string; data: UpdateAssigneePermissionsRequest }>({
            query: ({ projectId, memberId, data }) => ({
                url: `/projects/${projectId}/assignees/${memberId}/permissions`,
                method: 'PATCH',
                body: data,
            }),
            invalidatesTags: (_result, _error, { projectId }) => [{ type: 'Projects', id: projectId }, 'Projects', 'User'],
        }),

        getAssigneePermissions: builder.query<ApiResponse<any>, { projectId: string; memberId: string }>({
            query: ({ projectId, memberId }) => `/projects/${projectId}/assignees/${memberId}/permissions`,
            providesTags: (_result, _error, { projectId }) => [{ type: 'Projects', id: projectId }],
        }),

        uploadDocument: builder.mutation<ApiResponse<Project>, { projectId: string; file: File; name: string; type: string }>({
            query: ({ projectId, file, name, type }) => {
                const formData = new FormData();
                formData.append('file', file);
                formData.append('name', name);
                formData.append('type', type);

                return {
                    url: `/projects/${projectId}/documents`,
                    method: 'POST',
                    body: formData,
                };
            },
            invalidatesTags: (_result, _error, { projectId }) => [{ type: 'Projects', id: projectId }],
        }),

        getDocumentUrl: builder.query<ApiResponse<{ url: string }>, { projectId: string; docId: string }>({
            query: ({ projectId, docId }) => `/projects/${projectId}/documents/${docId}`,
        }),

        deleteDocument: builder.mutation<ApiResponse<Project>, { projectId: string; docId: string }>({
            query: ({ projectId, docId }) => ({
                url: `/projects/${projectId}/documents/${docId}`,
                method: 'DELETE',
            }),
            invalidatesTags: (_result, _error, { projectId }) => [{ type: 'Projects', id: projectId }],
        }),

        // ============================================
        // TASK ENDPOINTS
        // ============================================
        getTasks: builder.query<ApiResponse<Task[]>, { projectId: string; status?: string; assignee?: string; includeSubtasks?: boolean }>({
            query: ({ projectId, ...params }) => ({
                url: `/projects/${projectId}/tasks`,
                params,
            }),
            providesTags: (_result, _error, { projectId }) => [{ type: 'Tasks', id: projectId }],
        }),

        getTaskById: builder.query<ApiResponse<Task>, { projectId: string; taskId: string }>({
            query: ({ projectId, taskId }) => `/projects/${projectId}/tasks/${taskId}`,
            providesTags: (_result, _error, { taskId }) => [{ type: 'Tasks', id: taskId }],
        }),

        createTask: builder.mutation<ApiResponse<Task>, { projectId: string; data: CreateTaskRequest }>({
            query: ({ projectId, data }) => ({
                url: `/projects/${projectId}/tasks`,
                method: 'POST',
                body: data,
            }),
            invalidatesTags: (_result, _error, { projectId }) => [{ type: 'Tasks', id: projectId }],
        }),

        updateTask: builder.mutation<ApiResponse<Task>, { projectId: string; taskId: string; data: UpdateTaskRequest }>({
            query: ({ projectId, taskId, data }) => ({
                url: `/projects/${projectId}/tasks/${taskId}`,
                method: 'PATCH',
                body: data,
            }),
            invalidatesTags: (_result, _error, { projectId, taskId }) => [
                { type: 'Tasks', id: projectId },
                { type: 'Tasks', id: taskId },
                // When a status change creates a TimeLog (pause/complete), invalidate time-log caches
                'TimeLogs',
            ],
        }),

        deleteTask: builder.mutation<ApiResponse, { projectId: string; taskId: string }>({
            query: ({ projectId, taskId }) => ({
                url: `/projects/${projectId}/tasks/${taskId}`,
                method: 'DELETE',
            }),
            async onQueryStarted({ projectId, taskId }, { dispatch, queryFulfilled }) {
                toast.promise(queryFulfilled, {
                    loading: 'Deleting task...',
                    success: 'Task deleted successfully',
                    error: 'Failed to delete task',
                });
                const patchResult = dispatch(
                    api.util.updateQueryData('getTasks' as never, { projectId } as never, (draft: any) => {
                       if (draft?.data) {
                           draft.data = draft.data.filter((t: any) => t._id !== taskId);
                       }
                    })
                );
                try {
                    await queryFulfilled;
                } catch {
                    patchResult.undo();
                }
            },
            invalidatesTags: (_result, _error, { projectId }) => [{ type: 'Tasks', id: projectId }],
        }),

        getSubtasks: builder.query<ApiResponse<Task[]>, { projectId: string; taskId: string }>({
            query: ({ projectId, taskId }) => `/projects/${projectId}/tasks/${taskId}/subtasks`,
            providesTags: (_result, _error, { projectId, taskId }) => [
                { type: 'Tasks', id: `subtasks-${taskId}` },
                // Also tagged with projectId so when any task in this project mutates,
                // this subtask list automatically re-fetches (catches status changes)
                { type: 'Tasks', id: projectId },
            ],
        }),

        createSubtask: builder.mutation<ApiResponse<Task>, { projectId: string; taskId: string; data: CreateTaskRequest }>({
            query: ({ projectId, taskId, data }) => ({
                url: `/projects/${projectId}/tasks/${taskId}/subtasks`,
                method: 'POST',
                body: data,
            }),
            invalidatesTags: (_result, _error, { projectId, taskId }) => [
                { type: 'Tasks', id: `subtasks-${taskId}` },
                { type: 'Tasks', id: projectId }, // refreshes board view (includeSubtasks query)
            ],
        }),

        // ============================================
        // TIME LOG ENDPOINTS
        // ============================================
        createTimeLog: builder.mutation<ApiResponse<TimeLog>, { projectId: string; taskId: string; data: CreateTimeLogRequest }>({
            query: ({ projectId, taskId, data }) => ({
                url: `/projects/${projectId}/tasks/${taskId}/timelogs`,
                method: 'POST',
                body: data,
            }),
            invalidatesTags: ['TimeLogs'],
        }),

        getProjectTimeLogs: builder.query<ApiResponse<TimeLog[]>, { projectId: string; userId?: string; startDate?: string; endDate?: string; billable?: string }>({
            query: ({ projectId, ...params }) => ({
                url: `/projects/${projectId}/timelogs`,
                params,
            }),
            providesTags: ['TimeLogs'],
        }),

        getTaskTimeLogs: builder.query<ApiResponse<TimeLog[]>, { projectId: string; taskId: string }>({
            query: ({ projectId, taskId }) => `/projects/${projectId}/tasks/${taskId}/timelogs`,
            providesTags: ['TimeLogs'],
        }),

        getMyTimeLogs: builder.query<ApiResponse<TimeLog[]>, { startDate?: string; endDate?: string; projectId?: string }>({
            query: (params) => ({
                url: '/projects/timelogs/my',
                params,
            }),
            providesTags: ['TimeLogs'],
        }),

        updateTimeLog: builder.mutation<ApiResponse<TimeLog>, { id: string; data: UpdateTimeLogRequest }>({
            query: ({ id, data }) => ({
                url: `/projects/timelogs/${id}`,
                method: 'PATCH',
                body: data,
            }),
            invalidatesTags: ['TimeLogs'],
        }),

        deleteTimeLog: builder.mutation<ApiResponse, string>({
            query: (id) => ({
                url: `/projects/timelogs/${id}`,
                method: 'DELETE',
            }),
            invalidatesTags: ['TimeLogs'],
        }),

        // ============================================
        // MEETING ENDPOINTS
        // ============================================
        createMeeting: builder.mutation<ApiResponse<Meeting>, { projectId: string; data: CreateMeetingRequest }>({
            query: ({ projectId, data }) => ({
                url: `/projects/${projectId}/meetings`,
                method: 'POST',
                body: data,
            }),
            invalidatesTags: ['Meetings'],
        }),

        getMeetings: builder.query<ApiResponse<Meeting[]>, { projectId: string; type?: string; startDate?: string; endDate?: string }>({
            query: ({ projectId, ...params }) => ({
                url: `/projects/${projectId}/meetings`,
                params,
            }),
            providesTags: ['Meetings'],
        }),

        getMeetingById: builder.query<ApiResponse<Meeting>, { projectId: string; id: string }>({
            query: ({ projectId, id }) => `/projects/${projectId}/meetings/${id}`,
            providesTags: (_result, _error, { id }) => [{ type: 'Meetings', id }],
        }),

        updateMeeting: builder.mutation<ApiResponse<Meeting>, { projectId: string; id: string; data: UpdateMeetingRequest }>({
            query: ({ projectId, id, data }) => ({
                url: `/projects/${projectId}/meetings/${id}`,
                method: 'PATCH',
                body: data,
            }),
            invalidatesTags: (_result, _error, { id }) => [{ type: 'Meetings', id }, 'Meetings'],
        }),

        deleteMeeting: builder.mutation<ApiResponse, { projectId: string; id: string }>({
            query: ({ projectId, id }) => ({
                url: `/projects/${projectId}/meetings/${id}`,
                method: 'DELETE',
            }),
            invalidatesTags: ['Meetings'],
        }),

        // ============================================
        // CREDENTIAL ENDPOINTS
        // ============================================
        createCredential: builder.mutation<ApiResponse<Credential>, { projectId: string; data: CreateCredentialRequest }>({
            query: ({ projectId, data }) => ({
                url: `/projects/${projectId}/credentials`,
                method: 'POST',
                body: data,
            }),
            invalidatesTags: ['Credentials'],
        }),

        getCredentials: builder.query<ApiResponse<Credential[]>, { projectId: string; type?: string }>({
            query: ({ projectId, ...params }) => ({
                url: `/projects/${projectId}/credentials`,
                params,
            }),
            providesTags: ['Credentials'],
        }),

        getCredentialById: builder.query<ApiResponse<Credential>, { projectId: string; id: string }>({
            query: ({ projectId, id }) => `/projects/${projectId}/credentials/${id}`,
            providesTags: (_result, _error, { id }) => [{ type: 'Credentials', id }],
        }),

        updateCredential: builder.mutation<ApiResponse<Credential>, { projectId: string; id: string; data: UpdateCredentialRequest }>({
            query: ({ projectId, id, data }) => ({
                url: `/projects/${projectId}/credentials/${id}`,
                method: 'PATCH',
                body: data,
            }),
            invalidatesTags: (_result, _error, { id }) => [{ type: 'Credentials', id }, 'Credentials'],
        }),

        deleteCredential: builder.mutation<ApiResponse, { projectId: string; id: string }>({
            query: ({ projectId, id }) => ({
                url: `/projects/${projectId}/credentials/${id}`,
                method: 'DELETE',
            }),
            invalidatesTags: ['Credentials'],
        }),

        shareCredentials: builder.mutation<ApiResponse<void>, { projectId: string; data: ShareCredentialsRequest }>({
            query: ({ projectId, data }) => ({
                url: `/projects/${projectId}/credentials/share`,
                method: 'POST',
                body: data,
            }),
            invalidatesTags: ['Credentials'],
        }),

        revokeCredentialAccess: builder.mutation<ApiResponse<void>, { projectId: string; data: RevokeCredentialAccessRequest }>({
            query: ({ projectId, data }) => ({
                url: `/projects/${projectId}/credentials/share`,
                method: 'DELETE',
                body: data,
            }),
            invalidatesTags: ['Credentials'],
        }),

        getCredentialAdmins: builder.query<ApiResponse<any[]>, { projectId: string }>({
            query: ({ projectId }) => `/projects/${projectId}/credential-admins`,
            providesTags: (_result, _error, { projectId }) => [{ type: 'Projects', id: projectId }],
        }),

        updateCredentialAdmins: builder.mutation<ApiResponse<void>, { projectId: string; data: UpdateCredentialAdminsRequest }>({
            query: ({ projectId, data }) => ({
                url: `/projects/${projectId}/credential-admins`,
                method: 'PATCH',
                body: data,
            }),
            invalidatesTags: (_result, _error, { projectId }) => [{ type: 'Projects', id: projectId }, 'Projects'],
        }),

        // ============================================
        // DOC FOLDER ENDPOINTS
        // ============================================

        getDocFolders: builder.query<ApiResponse<DocFolder[]>, { projectId: string; parentId?: string | null }>({
            query: ({ projectId, parentId }) => ({
                url: `/projects/${projectId}/doc-folders`,
                params: parentId ? { parentId } : {},
            }),
            providesTags: (_result, _error, { projectId }) => [{ type: 'Documents', id: projectId }],
        }),

        createDocFolder: builder.mutation<ApiResponse<DocFolder>, { projectId: string; name: string; parentId?: string | null }>({
            query: ({ projectId, ...body }) => ({
                url: `/projects/${projectId}/doc-folders`,
                method: 'POST',
                body,
            }),
            invalidatesTags: (_result, _error, { projectId }) => [{ type: 'Documents', id: projectId }],
        }),

        renameDocFolder: builder.mutation<ApiResponse<DocFolder>, { projectId: string; folderId: string; name: string }>({
            query: ({ projectId, folderId, name }) => ({
                url: `/projects/${projectId}/doc-folders/${folderId}`,
                method: 'PATCH',
                body: { name },
            }),
            invalidatesTags: (_result, _error, { projectId }) => [{ type: 'Documents', id: projectId }],
        }),

        deleteDocFolder: builder.mutation<ApiResponse<void>, { projectId: string; folderId: string }>({
            query: ({ projectId, folderId }) => ({
                url: `/projects/${projectId}/doc-folders/${folderId}`,
                method: 'DELETE',
            }),
            invalidatesTags: (_result, _error, { projectId }) => [{ type: 'Documents', id: projectId }],
        }),

        updateDocFolderAccess: builder.mutation<ApiResponse<DocFolder>, { projectId: string; folderId: string; viewAccess: string[] }>({
            query: ({ projectId, folderId, viewAccess }) => ({
                url: `/projects/${projectId}/doc-folders/${folderId}/access`,
                method: 'PATCH',
                body: { viewAccess },
            }),
            invalidatesTags: (_result, _error, { projectId }) => [{ type: 'Documents', id: projectId }],
        }),

        // ============================================
        // DOC ITEM ENDPOINTS
        // ============================================

        getDocItems: builder.query<ApiResponse<DocItem[]>, { projectId: string; folderId?: string | null }>({
            query: ({ projectId, folderId }) => ({
                url: `/projects/${projectId}/doc-items`,
                params: folderId ? { folderId } : {},
            }),
            providesTags: (_result, _error, { projectId }) => [{ type: 'Documents', id: `${projectId}-items` }],
        }),

        uploadDocItem: builder.mutation<ApiResponse<DocItem>, { projectId: string; formData: FormData }>({
            query: ({ projectId, formData }) => ({
                url: `/projects/${projectId}/doc-items/upload`,
                method: 'POST',
                body: formData,
            }),
            invalidatesTags: (_result, _error, { projectId }) => [
                { type: 'Documents', id: projectId },
                { type: 'Documents', id: `${projectId}-items` },
            ],
        }),

        getDocItemUrl: builder.query<ApiResponse<{ url: string }>, { projectId: string; itemId: string }>({
            query: ({ projectId, itemId }) => `/projects/${projectId}/doc-items/${itemId}/url`,
        }),

        renameDocItem: builder.mutation<ApiResponse<DocItem>, { projectId: string; itemId: string; name: string }>({
            query: ({ projectId, itemId, name }) => ({
                url: `/projects/${projectId}/doc-items/${itemId}`,
                method: 'PATCH',
                body: { name },
            }),
            invalidatesTags: (_result, _error, { projectId }) => [{ type: 'Documents', id: `${projectId}-items` }],
        }),

        deleteDocItem: builder.mutation<ApiResponse<void>, { projectId: string; itemId: string }>({
            query: ({ projectId, itemId }) => ({
                url: `/projects/${projectId}/doc-items/${itemId}`,
                method: 'DELETE',
            }),
            invalidatesTags: (_result, _error, { projectId }) => [{ type: 'Documents', id: `${projectId}-items` }],
        }),

        updateDocItemAccess: builder.mutation<ApiResponse<DocItem>, { projectId: string; itemId: string; viewAccess: string[] }>({
            query: ({ projectId, itemId, viewAccess }) => ({
                url: `/projects/${projectId}/doc-items/${itemId}/access`,
                method: 'PATCH',
                body: { viewAccess },
            }),
            invalidatesTags: (_result, _error, { projectId }) => [{ type: 'Documents', id: `${projectId}-items` }],
        }),

        // ============================================
        // DOC ADMIN ENDPOINTS
        // ============================================

        getDocAdmins: builder.query<ApiResponse<DocAdminUser[]>, { projectId: string }>({
            query: ({ projectId }) => `/projects/${projectId}/doc-admins`,
            providesTags: (_result, _error, { projectId }) => [{ type: 'Documents', id: `${projectId}-admins` }],
        }),

        updateDocAdmins: builder.mutation<ApiResponse<void>, { projectId: string; userIds: string[] }>({
            query: ({ projectId, userIds }) => ({
                url: `/projects/${projectId}/doc-admins`,
                method: 'PATCH',
                body: { userIds },
            }),
            invalidatesTags: (_result, _error, { projectId }) => [
                { type: 'Documents', id: `${projectId}-admins` },
                { type: 'Projects', id: projectId },
            ],
        }),

        // ============================================
        // NOTE ENDPOINTS
        // ============================================

        getNotes: builder.query<ApiResponse<Note[]>, string>({
            query: (projectId) => `/projects/${projectId}/notes`,
            providesTags: (_result, _error, projectId) => [{ type: 'Notes' as const, id: projectId }],
        }),

        createNote: builder.mutation<ApiResponse<Note>, { projectId: string; data: CreateNoteRequest }>({
            query: ({ projectId, data }) => ({
                url: `/projects/${projectId}/notes`,
                method: 'POST',
                body: data,
            }),
            invalidatesTags: (_result, _error, { projectId }) => [{ type: 'Notes' as const, id: projectId }],
        }),

        updateNote: builder.mutation<ApiResponse<Note>, { projectId: string; noteId: string; data: UpdateNoteRequest }>({
            query: ({ projectId, noteId, data }) => ({
                url: `/projects/${projectId}/notes/${noteId}`,
                method: 'PATCH',
                body: data,
            }),
            invalidatesTags: (_result, _error, { projectId }) => [{ type: 'Notes' as const, id: projectId }],
        }),

        deleteNote: builder.mutation<ApiResponse<void>, { projectId: string; noteId: string }>({
            query: ({ projectId, noteId }) => ({
                url: `/projects/${projectId}/notes/${noteId}`,
                method: 'DELETE',
            }),
            invalidatesTags: (_result, _error, { projectId }) => [{ type: 'Notes' as const, id: projectId }],
        }),

        uploadNoteImage: builder.mutation<ApiResponse<{ cloudinaryId: string; url: string }>, { projectId: string; file: File }>({
            query: ({ projectId, file }) => {
                const formData = new FormData();
                formData.append('image', file);
                return {
                    url: `/projects/${projectId}/notes/upload-image`,
                    method: 'POST',
                    body: formData,
                };
            },
        }),

        // ============================================
        // PHASE PAYMENT ENDPOINTS
        // ============================================

        getProjectPaymentSummary: builder.query<ApiResponse<{
            totalExpectedPayment: number;
            totalReceivedPayment: number;
            totalPendingPayment: number;
            phasesWithPayment: number;
            phasesPaymentReceived: number;
            phaseDetails: Array<{
                phaseId: string;
                phaseName: string;
                expectedAmount: number;
                receivedAmount: number;
                pendingAmount: number;
                status: string;
                dueDate: string | undefined;
            }>;
        }>, string>({
            query: (projectId) => `/projects/${projectId}/payment-summary`,
            providesTags: (_result, _error, projectId) => [{ type: 'Projects', id: projectId }],
        }),

        markPhasePaymentReceived: builder.mutation<ApiResponse<{
            project: Project;
            revenue: any;
            bankTransaction: any;
        }>, {
            projectId: string;
            phaseId: string;
            receivedAmount: number;
            bankAccountKey: 'hdfc_gst' | 'sbi_non_gst' | 'cash';
            receivedDate?: string;
            notes?: string;
        }>({
            query: ({ projectId, phaseId, ...data }) => ({
                url: `/projects/${projectId}/phases/${phaseId}/mark-payment-received`,
                method: 'POST',
                body: data,
            }),
            invalidatesTags: (_result, _error, { projectId }) => [
                { type: 'Projects', id: projectId },
                'Projects',
                'Revenues',
                'BankTransactions',
            ],
        }),
    }),
    overrideExisting: false,
});

