// API Request/Response types
import type {
    Project,
    Task,
    TimeLog,
    Meeting,
    Credential,
    InvoiceDetails,
    MeetingParticipant,
    MeetingActionItem,
    CredentialData,
    ProjectPhase,
} from './types';

// ============================================
// PROJECT API TYPES
// ============================================

export interface CreateProjectRequest {
