// ─── Page ─────────────────────────────────────────────────────────────────────

export default function AdminPermissionsPage() {
    const [search, setSearch] = useState('');
    const [selectedUser, setSelectedUser] = useState<any>(null);
    const [perms, setPerms] = useState<ModulePermissions>(defaultPermissions());
    const [saving, setSaving] = useState(false);
    const [saved, setSaved] = useState(false);

    const { data } = useGetAdminUsersQuery({ search, limit: 100 });
    const [updateUser] = useUpdateAdminUserMutation();
    const getRoleName = (role: any) => role ? (typeof role === 'object' ? role.name : role) : '—';
    const isPartnerUser = (user: any) => getRoleName(user?.role).toLowerCase() === 'partner' || !!user?.isPartnerEmployee;
    const users = (data?.data?.users || []).filter((user: any) => {
        const rName = getRoleName(user.role).toLowerCase();
        return rName !== 'super-admin' && rName !== 'superadmin' && !isPartnerUser(user);
    });

    const handleSelect = (user: any) => {
        setSelectedUser(user);
        setSaved(false);
        setPerms(loadPermissions(user));
    };

    const handleSave = async () => {
        if (!selectedUser) return;
        setSaving(true);
        try {
            const nextPerms = { ...perms, accessControlVersion: 2 };
            await updateUser({ id: selectedUser._id, data: { modulePermissions: nextPerms as any } }).unwrap();
            setSelectedUser({ ...selectedUser, modulePermissions: nextPerms });
            setSaved(true);
            setTimeout(() => setSaved(false), 2500);
        } catch (err: any) { alert(err?.data?.message || 'Failed to save'); }
        finally { setSaving(false); }
    };

    const countEnabled = (user: any) => {
        const isJobManager = !!user?.derivedAccess?.hiringJobManager;
        return (['projectManagement', 'finance', 'crm', 'hrms', 'overallAdmin', 'partners', 'hiring'] as ModuleKey[])
            .filter((key) => hasModuleViewAccess(user, key, { isJobManager }))
            .length;
    };
    const inputSty = { borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-surface)' };

    return (
        <div className="p-8 mx-auto" style={{ maxWidth: '1200px' }}>
            <div className="flex items-center gap-3 mb-8">
                <div className="w-10 h-10 rounded-lg flex items-center justify-center" style={{ backgroundColor: '#F0FDF4', color: '#16A34A' }}>
                    <ShieldCheck size={22} />
                </div>
                <div>
                    <h1 className="text-2xl font-bold" style={{ color: 'var(--color-text-primary)' }}>Module Permissions</h1>
                    <p className="text-sm" style={{ color: 'var(--color-text-secondary)' }}>Select a user and configure which modules and sub-sections they can access</p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 items-start">
                {/* Left — User list */}
                <div className="lg:col-span-1 sticky top-6">
                    <div className="rounded-[1rem] shadow-premium overflow-hidden border-0" style={{ backgroundColor: 'var(--color-bg-surface)' }}>
                        <div className="p-4 border-b" style={{ borderColor: 'var(--color-border-default)' }}>
                            <p className="text-sm font-semibold mb-3" style={{ color: 'var(--color-text-primary)' }}>Select User</p>
                            <div className="relative">
                                <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2" style={{ color: 'var(--color-text-muted)' }} />
                                <input type="text" placeholder="Search…" value={search} onChange={e => setSearch(e.target.value)}
                                    className="w-full pl-8 pr-3 py-2 rounded-lg border text-sm outline-none" style={inputSty} />
                            </div>
                        </div>
                        <div className="overflow-y-auto" style={{ maxHeight: '520px' }}>
                            {users.length === 0
                                ? <div className="p-6 text-center text-sm" style={{ color: 'var(--color-text-muted)' }}>No users found</div>
                                : users.map((user: any) => {
                                    const isSel = selectedUser?._id === user._id;
                                    const n = countEnabled(user);
                                    return (
                                        <button key={user._id} onClick={() => handleSelect(user)}
                                            className="w-full flex items-center gap-3 px-4 py-3 text-left transition-colors border-b last:border-b-0"
                                            style={{ borderColor: 'var(--color-border-default)', backgroundColor: isSel ? 'var(--color-primary-soft)' : 'transparent' }}
                                            onMouseEnter={e => { if (!isSel) e.currentTarget.style.backgroundColor = 'var(--color-bg-subtle)'; }}
                                            onMouseLeave={e => { if (!isSel) e.currentTarget.style.backgroundColor = 'transparent'; }}>
                                            <div className="w-9 h-9 rounded-full flex items-center justify-center text-white text-sm font-semibold flex-shrink-0"
                                                style={{ backgroundColor: isSel ? 'var(--color-primary)' : '#94A3B8' }}>
                                                {user.name?.charAt(0)?.toUpperCase()}
                                            </div>
                                            <div className="min-w-0 flex-1">
                                                <div className="text-sm font-medium truncate" style={{ color: isSel ? 'var(--color-primary-dark)' : 'var(--color-text-primary)' }}>{user.name}</div>
                                                <div className="text-xs truncate" style={{ color: 'var(--color-text-muted)' }}>{getRoleName(user.role)} · {n} module{n !== 1 ? 's' : ''}</div>
                                            </div>
                                            {isSel && <ChevronRight size={16} style={{ color: 'var(--color-primary)' }} />}
                                        </button>
                                    );
                                })}
                        </div>
                    </div>
                </div>

                {/* Right — Permissions */}
                <div className="lg:col-span-2">
                    {!selectedUser ? (
                        <div className="rounded-[1rem] shadow-premium border-0 flex flex-col items-center justify-center py-20"
                            style={{ backgroundColor: 'var(--color-bg-surface)' }}>
                            <div className="w-14 h-14 rounded-full flex items-center justify-center mb-4" style={{ backgroundColor: 'var(--color-bg-subtle)' }}>
                                <User size={26} style={{ color: 'var(--color-text-muted)' }} />
                            </div>
                            <p className="text-base font-medium" style={{ color: 'var(--color-text-primary)' }}>No user selected</p>
                            <p className="text-sm mt-1" style={{ color: 'var(--color-text-muted)' }}>Pick a user from the list to configure their access</p>
                        </div>
                    ) : (
                        <div>
                            <div className="flex items-center justify-between mb-5 p-4 rounded-[1rem] shadow-premium border-0"
                                style={{ backgroundColor: 'var(--color-bg-surface)' }}>
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 rounded-full flex items-center justify-center text-white font-semibold" style={{ backgroundColor: 'var(--color-primary)' }}>
                                        {selectedUser.name?.charAt(0)?.toUpperCase()}
                                    </div>
                                    <div>
                                        <div className="text-sm font-semibold" style={{ color: 'var(--color-text-primary)' }}>{selectedUser.name}</div>
                                        <div className="text-xs" style={{ color: 'var(--color-text-muted)' }}>{selectedUser.email} · {getRoleName(selectedUser.role)}</div>
                                    </div>
                                </div>
                                <button onClick={handleSave} disabled={saving}
                                    className="flex items-center gap-2 px-5 py-2.5 text-sm font-semibold rounded-lg text-white disabled:opacity-60 transition-all btn-premium"
                                    style={{ backgroundColor: saved ? '#16A34A' : 'var(--color-primary)' }}>
                                    {saved ? <><Check size={16} /> Saved!</> : saving ? 'Saving…' : <><Save size={16} /> Save Permissions</>}
                                </button>
                            </div>
                            <PermissionsPanel perms={perms} onChange={setPerms} hiringViewDerived={!!selectedUser?.derivedAccess?.hiringJobManager} />
                            <div className="mt-4 flex justify-end">
                                <button onClick={handleSave} disabled={saving}
                                    className="flex items-center gap-2 px-6 py-3 text-sm font-semibold rounded-lg text-white disabled:opacity-60 btn-premium"
                                    style={{ backgroundColor: saved ? '#16A34A' : 'var(--color-primary)' }}>
                                    {saved ? <><Check size={16} /> Saved!</> : saving ? 'Saving…' : <><Save size={16} /> Save Permissions</>}
                                </button>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

import { useState } from 'react';
import {
    Shield,
    Plus,
    X,
    Trash2,
    Copy,
    ChevronDown,
    ChevronRight,
} from 'lucide-react';
import {
    useGetAdminRolesQuery,
    useCreateAdminRoleMutation,
    useUpdateAdminRoleMutation,
    useDeleteAdminRoleMutation,
    useCloneAdminRoleMutation,
    useGetAdminPermissionsQuery,
} from '@/features/overall-admin/api/adminApi';
import ModalPortal from '@/components/ui/ModalPortal';

interface RoleFormData {
    name: string;
    description: string;
    level: number;
    permissions: string[];
}

const initialFormData: RoleFormData = {
    name: '',
    description: '',
    level: 5,
    permissions: [],
};

export default function AdminRolesPage() {
    const [showModal, setShowModal] = useState(false);
    const [editingRole, setEditingRole] = useState<any>(null);
    const [formData, setFormData] = useState<RoleFormData>(initialFormData);
    const [expandedRole, setExpandedRole] = useState<string | null>(null);
    const [cloneName, setCloneName] = useState('');
    const [cloningRoleId, setCloningRoleId] = useState<string | null>(null);
    const [error, setError] = useState('');

    const { data: rolesData, isLoading } = useGetAdminRolesQuery();
    const { data: permsData } = useGetAdminPermissionsQuery();
    const [createRole] = useCreateAdminRoleMutation();
    const [updateRole] = useUpdateAdminRoleMutation();
    const [deleteRole] = useDeleteAdminRoleMutation();
    const [cloneRole] = useCloneAdminRoleMutation();

    const roles = rolesData?.data || [];
    const groupedPermissions = permsData?.data?.grouped || {};

    const openCreateModal = () => {
        setEditingRole(null);
        setFormData(initialFormData);
        setError('');
        setShowModal(true);
    };

    const openEditModal = (role: any) => {
        setEditingRole(role);
        setFormData({
            name: role.name,
            description: role.description,
            level: role.level,
            permissions: role.permissions.map((p: any) =>
                typeof p === 'object' ? p._id : p
            ),
        });
        setError('');
        setShowModal(true);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

        try {
            if (editingRole) {
                await updateRole({ id: editingRole._id, data: formData }).unwrap();
            } else {
                await createRole(formData).unwrap();
            }
            setShowModal(false);
        } catch (err: any) {
            setError(err?.data?.message || 'Operation failed');
        }
    };

    const handleDelete = async (roleId: string, roleName: string) => {
        if (!confirm(`Delete role "${roleName}"? This cannot be undone.`)) return;
        try {
            await deleteRole(roleId).unwrap();
        } catch (err: any) {
            alert(err?.data?.message || 'Failed to delete role');
        }
    };

    const handleClone = async () => {
        if (!cloningRoleId || !cloneName.trim()) return;
        try {
            await cloneRole({ id: cloningRoleId, name: cloneName.trim() }).unwrap();
            setCloningRoleId(null);
            setCloneName('');
        } catch (err: any) {
            alert(err?.data?.message || 'Failed to clone role');
        }
    };

    const togglePermission = (permId: string) => {
        setFormData((prev) => ({
            ...prev,
            permissions: prev.permissions.includes(permId)
                ? prev.permissions.filter((id) => id !== permId)
                : [...prev.permissions, permId],
        }));
    };

    const toggleResourcePermissions = (resource: string) => {
        const resourcePerms = groupedPermissions[resource] || [];
        const resourcePermIds = resourcePerms.map((p: any) => p._id);
        const allSelected = resourcePermIds.every((id: string) =>
            formData.permissions.includes(id)
        );

        if (allSelected) {
            setFormData((prev) => ({
                ...prev,
                permissions: prev.permissions.filter(
                    (id) => !resourcePermIds.includes(id)
                ),
            }));
        } else {
            setFormData((prev) => ({
                ...prev,
                permissions: [
                    ...prev.permissions.filter((id) => !resourcePermIds.includes(id)),
                    ...resourcePermIds,
                ],
            }));
        }
    };

    const protectedRoles = ['super-admin', 'admin', 'employee'];

    return (
        <div className="p-8 mx-auto" style={{ maxWidth: '1200px' }}>
            {/* Header */}
            <div className="flex items-center justify-between mb-6">
                <div className="flex items-center gap-3">
                    <div
                        className="w-10 h-10 rounded-lg flex items-center justify-center"
                        style={{ backgroundColor: '#F5F3FF', color: '#7C3AED' }}
                    >
                        <Shield size={22} />
                    </div>
                    <div>
                        <h1
                            className="text-2xl font-bold"
                            style={{ color: 'var(--color-text-primary)' }}
                        >
                            Roles & Permissions
                        </h1>
                        <p
                            className="text-sm"
                            style={{ color: 'var(--color-text-secondary)' }}
                        >
                            {roles.length} roles configured
                        </p>
                    </div>
                </div>
                <button
                    onClick={openCreateModal}
                    className="flex items-center gap-2 px-4 py-2.5 rounded-lg text-white font-medium text-sm"
                    style={{ backgroundColor: 'var(--color-primary)' }}
                >
                    <Plus size={18} />
                    Create Role
                </button>
            </div>

            {/* Roles List */}
            {isLoading ? (
                <div className="text-center py-12" style={{ color: 'var(--color-text-muted)' }}>
                    Loading roles...
                </div>
            ) : (
                <div className="space-y-3">
                    {roles.map((role: any) => {
                        const isExpanded = expandedRole === role._id;
                        const permsList = (role.permissions || []).filter(
                            (p: any) => typeof p === 'object'
                        );

                        return (
                            <div
                                key={role._id}
                                className="rounded-[1rem] shadow-premium overflow-hidden border-0 transition-shadow"
                                style={{
                                    backgroundColor: 'var(--color-bg-surface)',
                                }}
                            >
                                {/* Role Header */}
                                <div
                                    className="flex items-center gap-4 px-5 py-4 cursor-pointer"
                                    onClick={() =>
                                        setExpandedRole(isExpanded ? null : role._id)
                                    }
                                >
                                    <div className="flex-shrink-0">
                                        {isExpanded ? (
                                            <ChevronDown size={18} style={{ color: 'var(--color-text-muted)' }} />
                                        ) : (
                                            <ChevronRight size={18} style={{ color: 'var(--color-text-muted)' }} />
                                        )}
                                    </div>
                                    <div
                                        className="w-10 h-10 rounded-lg flex items-center justify-center flex-shrink-0"
                                        style={{
                                            backgroundColor: '#F5F3FF',
                                            color: '#7C3AED',
                                        }}
                                    >
                                        <Shield size={18} />
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-2">
                                            <span
                                                className="text-sm font-semibold capitalize"
                                                style={{ color: 'var(--color-text-primary)' }}
                                            >
                                                {role.name}
                                            </span>
                                            <span
                                                className="text-xs px-2 py-0.5 rounded-full"
                                                style={{
                                                    backgroundColor: '#EFF6FF',
                                                    color: '#3B82F6',
                                                }}
                                            >
                                                Level {role.level}
                                            </span>
                                        </div>
                                        <div
                                            className="text-xs mt-0.5"
                                            style={{ color: 'var(--color-text-muted)' }}
                                        >
                                            {role.description} • {permsList.length} permissions
                                        </div>
                                    </div>
                                    <div
                                        className="flex items-center gap-1"
                                        onClick={(e) => e.stopPropagation()}
                                    >
                                        <button
                                            onClick={() => openEditModal(role)}
                                            className="p-2 rounded-lg hover:bg-gray-100 transition-colors text-sm"
                                            style={{ color: 'var(--color-primary)' }}
                                        >
                                            Edit
                                        </button>
                                        <button
                                            onClick={() => {
                                                setCloningRoleId(role._id);
                                                setCloneName('');
                                            }}
                                            className="p-2 rounded-lg hover:bg-gray-100 transition-colors"
                                            title="Clone role"
                                        >
                                            <Copy size={16} style={{ color: 'var(--color-text-muted)' }} />
                                        </button>
                                        {!protectedRoles.includes(role.name) && (
                                            <button
                                                onClick={() => handleDelete(role._id, role.name)}
                                                className="p-2 rounded-lg hover:bg-red-50 transition-colors"
                                                title="Delete role"
                                            >
                                                <Trash2 size={16} style={{ color: '#EF4444' }} />
                                            </button>
                                        )}
                                    </div>
                                </div>

                                {/* Expanded Permissions */}
                                {isExpanded && permsList.length > 0 && (
                                    <div
                                        className="px-5 pb-4 border-t"
                                        style={{ borderColor: 'var(--color-border-default)' }}
                                    >
                                        <div className="mt-3">
                                            <div className="text-xs font-semibold uppercase tracking-wider mb-3" style={{ color: 'var(--color-text-muted)' }}>
                                                Assigned Permissions
                                            </div>
                                            <div className="flex flex-wrap gap-2">
                                                {permsList.map((perm: any) => (
                                                    <span
                                                        key={perm._id}
                                                        className="text-xs px-2.5 py-1 rounded-full font-medium"
                                                        style={{
                                                            backgroundColor: '#F0FDF4',
                                                            color: '#15803D',
                                                        }}
                                                    >
                                                        {perm.resource}:{perm.action}
                                                    </span>
                                                ))}
                                            </div>
                                        </div>
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            )}

            {/* Clone Modal */}
            {cloningRoleId && (
                <ModalPortal>

                    <div
                        className="w-full max-w-sm rounded-[1rem] p-6 m-4 shadow-premium"
                        style={{ backgroundColor: 'var(--color-bg-surface)' }}
                    >
                        <div className="flex items-center justify-between mb-4">
                            <h3 className="text-lg font-semibold" style={{ color: 'var(--color-text-primary)' }}>
                                Clone Role
                            </h3>
                            <button onClick={() => setCloningRoleId(null)} className="p-1 rounded hover:bg-gray-100">
                                <X size={18} />
                            </button>
                        </div>
                        <div className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>New Role Name</label>
                                <input
                                    type="text"
                                    value={cloneName}
                                    onChange={(e) => setCloneName(e.target.value)}
                                    className="w-full px-3 py-2 rounded-lg border text-sm"
                                    style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-subtle)' }}
                                    placeholder="e.g. marketing-lead"
                                />
                            </div>
                            <div className="flex justify-end gap-3">
                                <button
                                    onClick={() => setCloningRoleId(null)}
                                    className="px-4 py-2 text-sm rounded-lg border"
                                    style={{ borderColor: 'var(--color-border-default)' }}
                                >
                                    Cancel
                                </button>
                                <button
                                    onClick={handleClone}
                                    disabled={!cloneName.trim()}
                                    className="px-4 py-2 text-sm font-medium rounded-lg text-white disabled:opacity-50"
                                    style={{ backgroundColor: 'var(--color-primary)' }}
                                >
                                    Clone
                                </button>
                            </div>
                        </div>
                    </div>
                </ModalPortal>
            )}

            {/* Create/Edit Role Modal */}
            {showModal && (
                <ModalPortal>

                    <div
                        className="w-full max-w-2xl rounded-[1rem] shadow-premium p-6 m-4 max-h-[85vh] overflow-y-auto"
                        style={{ backgroundColor: 'var(--color-bg-surface)' }}
                    >
                        <div className="flex items-center justify-between mb-5">
                            <h3 className="text-lg font-semibold" style={{ color: 'var(--color-text-primary)' }}>
                                {editingRole ? 'Edit Role' : 'Create Role'}
                            </h3>
                            <button onClick={() => setShowModal(false)} className="p-1 rounded hover:bg-gray-100">
                                <X size={18} />
                            </button>
                        </div>

                        {error && (
                            <div className="mb-4 p-3 rounded-lg text-sm text-red-700 bg-red-50 border border-red-200">{error}</div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-5">
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>Role Name</label>
                                    <input
                                        required
                                        type="text"
                                        value={formData.name}
                                        onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                        className="w-full px-3 py-2 rounded-lg border text-sm"
                                        style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-subtle)' }}
                                        placeholder="e.g. team-lead"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>Level (1-10)</label>
                                    <input
                                        required
                                        type="number"
                                        min={1}
                                        max={10}
                                        value={formData.level}
                                        onChange={(e) => setFormData({ ...formData, level: parseInt(e.target.value) || 5 })}
                                        className="w-full px-3 py-2 rounded-lg border text-sm"
                                        style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-subtle)' }}
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>Description</label>
                                <input
                                    required
                                    type="text"
                                    value={formData.description}
                                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                                    className="w-full px-3 py-2 rounded-lg border text-sm"
                                    style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-subtle)' }}
                                    placeholder="Brief description of this role"
                                />
                            </div>

                            {/* Permission Matrix */}
                            <div>
                                <label className="block text-sm font-medium mb-2" style={{ color: 'var(--color-text-primary)' }}>
                                    Permissions ({formData.permissions.length} selected)
                                </label>
                                <div
                                    className="rounded-lg border p-4 space-y-4 max-h-64 overflow-y-auto"
                                    style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-subtle)' }}
                                >
                                    {Object.entries(groupedPermissions).map(
                                        ([resource, perms]: [string, any]) => {
                                            const permIds = perms.map((p: any) => p._id);
                                            const allChecked = permIds.every((id: string) =>
                                                formData.permissions.includes(id)
                                            );
                                            return (
                                                <div key={resource}>
                                                    <div className="flex items-center gap-2 mb-2">
                                                        <input
                                                            type="checkbox"
                                                            checked={allChecked}
                                                            onChange={() => toggleResourcePermissions(resource)}
                                                            className="rounded"
                                                        />
                                                        <span
                                                            className="text-xs font-semibold uppercase tracking-wider capitalize"
                                                            style={{ color: 'var(--color-text-primary)' }}
                                                        >
                                                            {resource}
                                                        </span>
                                                    </div>
                                                    <div className="flex flex-wrap gap-2 ml-6">
                                                        {perms.map((perm: any) => (
                                                            <label
                                                                key={perm._id}
                                                                className="flex items-center gap-1.5 text-xs cursor-pointer"
                                                            >
                                                                <input
                                                                    type="checkbox"
                                                                    checked={formData.permissions.includes(perm._id)}
                                                                    onChange={() => togglePermission(perm._id)}
                                                                    className="rounded"
                                                                />
                                                                <span style={{ color: 'var(--color-text-secondary)' }}>
                                                                    {perm.action}
                                                                </span>
                                                            </label>
                                                        ))}
                                                    </div>
                                                </div>
                                            );
                                        }
                                    )}
                                    {Object.keys(groupedPermissions).length === 0 && (
                                        <p className="text-sm" style={{ color: 'var(--color-text-muted)' }}>No permissions available</p>
                                    )}
                                </div>
                            </div>

                            <div className="flex justify-end gap-3 pt-2">
                                <button
                                    type="button"
                                    onClick={() => setShowModal(false)}
                                    className="px-4 py-2 text-sm rounded-lg border"
                                    style={{ borderColor: 'var(--color-border-default)' }}
                                >
                                    Cancel
                                </button>
                                <button
                                    type="submit"
                                    className="px-4 py-2 text-sm font-medium rounded-lg text-white"
                                    style={{ backgroundColor: 'var(--color-primary)' }}
                                >
                                    {editingRole ? 'Save Changes' : 'Create Role'}
                                </button>
                            </div>
                        </form>
                    </div>
                </ModalPortal>
            )}
        </div>
    );
}

import { useState, useEffect, type KeyboardEvent } from 'react';
import { Settings, Save, Building2 } from 'lucide-react';
import {
    useGetOrgSettingsQuery,
    useUpdateOrgSettingsMutation,
} from '@/features/overall-admin/api/adminApi';
import { dedupeDepartments } from '@/utils/department';

const DEFAULT_ABOUT_COMPANY_TEXT =
    'Creative Upaay is a tech and design partner that works closely with Startups and Enterprises to build AI based digital products and systems. Our work goes beyond just design or development, we focus on creating practical, scalable solutions that teams actually use. We work across 10+ Industries, for their Custom web solution development, automation workflows, and AI based tools. A lot of our projects involve understanding messy real-world processes and turning them into structured digital experiences.\n\nSo far, we have worked with 85+ brands globally and delivered 350+ projects.\n\nWe look for people who take ownership, think in systems, and care about solving real problems, not just completing tasks. Our Team culture is simple: low ego, high responsibility, honest communication, and a strong focus on doing quality work that actually makes an impact.';

export default function AdminSettingsPage() {
    const { data, isLoading } = useGetOrgSettingsQuery();
    const [updateSettings] = useUpdateOrgSettingsMutation();
    const [saving, setSaving] = useState('');
    const [success, setSuccess] = useState('');

    const settings = data?.data;

    // Local state for each section
    const [company, setCompany] = useState({
        companyName: '',
        companyEmail: '',
        companyPhone: '',
    });
    const [address, setAddress] = useState({
        street: '',
        city: '',
        state: '',
        country: '',
        zipCode: '',
    });
    const [departments, setDepartments] = useState<string[]>([]);
    const [departmentInput, setDepartmentInput] = useState('');
    const [hiringContent, setHiringContent] = useState({
        showAboutCompany: true,
        aboutCompanyText: DEFAULT_ABOUT_COMPANY_TEXT,
    });

    useEffect(() => {
        if (settings) {
            setCompany({
                companyName: settings.companyName || '',
                companyEmail: settings.companyEmail || '',
                companyPhone: settings.companyPhone || '',
            });
            const addr = settings.address || {};
            setAddress({ street: addr.street || '', city: addr.city || '', state: addr.state || '', country: addr.country || '', zipCode: addr.zipCode || '' });
            setDepartments(dedupeDepartments(Array.isArray(settings.departments) ? settings.departments : []));
            setHiringContent({
                showAboutCompany:
                    settings.hiring?.publicJobPage?.showAboutCompany ?? true,
                aboutCompanyText:
                    settings.hiring?.publicJobPage?.aboutCompanyText || DEFAULT_ABOUT_COMPANY_TEXT,
            });
        }
    }, [settings]);

    const handleSaveSection = async (section: string, data: any) => {
        setSaving(section);
        setSuccess('');
        try {
            await updateSettings(data).unwrap();
            setSuccess(section);
            setTimeout(() => setSuccess(''), 2000);
        } catch (err: any) {
            alert(err?.data?.message || 'Failed to save settings');
        } finally {
            setSaving('');
        }
    };

    const addDepartment = () => {
        const nextDepartment = departmentInput.trim();
        if (!nextDepartment) return;

        const exists = departments.some(
            (department) => department.toLowerCase() === nextDepartment.toLowerCase()
        );
        if (exists) {
            setDepartmentInput('');
            return;
        }

        setDepartments((prev) => dedupeDepartments([...prev, nextDepartment]));
        setDepartmentInput('');
    };

    const removeDepartment = (departmentToRemove: string) => {
        if (!window.confirm(`Are you sure you want to remove the department "${departmentToRemove}"?`)) return;
        setDepartments((prev) =>
            prev.filter((department) => department !== departmentToRemove)
        );
    };

    const handleBoldShortcut = (e: KeyboardEvent<HTMLTextAreaElement>) => {
        if (!(e.metaKey || e.ctrlKey) || e.key.toLowerCase() !== 'b') return;
        e.preventDefault();

        const textarea = e.currentTarget;

        const currentValue = textarea.value;
        const start = textarea.selectionStart ?? currentValue.length;
        const end = textarea.selectionEnd ?? currentValue.length;
        const selectedText = currentValue.slice(start, end);
        const wrappedText = selectedText ? `**${selectedText}**` : '****';
        const nextValue = `${currentValue.slice(0, start)}${wrappedText}${currentValue.slice(end)}`;

        setHiringContent((prev) => ({ ...prev, aboutCompanyText: nextValue }));

        window.requestAnimationFrame(() => {
            const nextStart = start + 2;
            const nextEnd = selectedText ? end + 2 : start + 2;
            textarea.focus();
            textarea.setSelectionRange(nextStart, nextEnd);
        });
    };

    const SectionHeader = ({ icon, title }: { icon: React.ReactNode; title: string }) => (
        <div className="flex items-center gap-2 mb-4">
            <span style={{ color: 'var(--color-primary)' }}>{icon}</span>
            <h2 className="text-lg font-semibold" style={{ color: 'var(--color-text-primary)' }}>{title}</h2>
        </div>
    );

    const SaveButton = ({ section, onClick }: { section: string; onClick: () => void }) => (
        <button
            onClick={onClick}
            disabled={saving === section}
            className="flex items-center gap-2 px-4 py-2 text-sm font-medium rounded-lg text-white mt-4 disabled:opacity-50"
            style={{ backgroundColor: success === section ? '#10B981' : 'var(--color-primary)' }}
        >
            <Save size={16} />
            {saving === section ? 'Saving...' : success === section ? 'Saved!' : 'Save'}
        </button>
    );

    if (isLoading) {
        return (
            <div className="p-8 mx-auto" style={{ maxWidth: '1200px' }}>
                <div className="animate-pulse space-y-6">
                    <div className="h-8 bg-gray-200 rounded w-48" />
                    <div className="h-64 bg-gray-200 rounded-xl" />
                </div>
            </div>
        );
    }

    return (
        <div className="p-8 mx-auto" style={{ maxWidth: '1200px' }}>
            {/* Header */}
            <div className="flex items-center gap-3 mb-8">
                <div className="w-10 h-10 rounded-lg flex items-center justify-center" style={{ backgroundColor: '#FEF3C7', color: '#D97706' }}>
                    <Settings size={22} />
                </div>
                <div>
                    <h1 className="text-2xl font-bold" style={{ color: 'var(--color-text-primary)' }}>Organization Settings</h1>
                    <p className="text-sm" style={{ color: 'var(--color-text-secondary)' }}>Configure your organization details and policies</p>
                </div>
            </div>

            <div className="space-y-6">
                {/* Company Info */}
                <div className="rounded-xl border p-6" style={{ backgroundColor: 'var(--color-bg-surface)', borderColor: 'var(--color-border-default)' }}>
                    <SectionHeader icon={<Building2 size={20} />} title="Company Information" />
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>Company Name</label>
                            <input type="text" value={company.companyName} onChange={(e) => setCompany({ ...company, companyName: e.target.value })} className="w-full px-3 py-2 rounded-lg border text-sm" style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-subtle)' }} />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>Email</label>
                            <input type="email" value={company.companyEmail} onChange={(e) => setCompany({ ...company, companyEmail: e.target.value })} className="w-full px-3 py-2 rounded-lg border text-sm" style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-subtle)' }} />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>Phone</label>
                            <input type="text" value={company.companyPhone} onChange={(e) => setCompany({ ...company, companyPhone: e.target.value })} className="w-full px-3 py-2 rounded-lg border text-sm" style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-subtle)' }} />
                        </div>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mt-4">
                        <div>
                            <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>City</label>
                            <input type="text" value={address.city} onChange={(e) => setAddress({ ...address, city: e.target.value })} className="w-full px-3 py-2 rounded-lg border text-sm" style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-subtle)' }} />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>State</label>
                            <input type="text" value={address.state} onChange={(e) => setAddress({ ...address, state: e.target.value })} className="w-full px-3 py-2 rounded-lg border text-sm" style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-subtle)' }} />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>Country</label>
                            <input type="text" value={address.country} onChange={(e) => setAddress({ ...address, country: e.target.value })} className="w-full px-3 py-2 rounded-lg border text-sm" style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-subtle)' }} />
                        </div>
                    </div>
                    <SaveButton section="company" onClick={() => handleSaveSection('company', { ...company, address })} />
                </div>

                <div className="rounded-xl border p-6" style={{ backgroundColor: 'var(--color-bg-surface)', borderColor: 'var(--color-border-default)' }}>
                    <SectionHeader icon={<Building2 size={20} />} title="Departments" />
                    <p className="text-sm mb-4" style={{ color: 'var(--color-text-secondary)' }}>
                        These departments are reused across admin users, HRMS, and hiring job postings.
                    </p>
                    <div className="flex flex-wrap gap-2 mb-4">
                        {departments.map((department) => (
                            <span
                                key={department}
                                className="inline-flex items-center gap-2 px-3 py-1.5 rounded-full text-sm border"
                                style={{
                                    backgroundColor: 'var(--color-bg-subtle)',
                                    borderColor: 'var(--color-border-default)',
                                    color: 'var(--color-text-primary)',
                                }}
                            >
                                {department}
                                <button
                                    type="button"
                                    onClick={() => removeDepartment(department)}
                                    className="text-xs"
                                    style={{ color: 'var(--color-text-muted)' }}
                                >
                                    Remove
                                </button>
                            </span>
                        ))}
                        {departments.length === 0 && (
                            <p className="text-sm" style={{ color: 'var(--color-text-muted)' }}>
                                No departments added yet.
                            </p>
                        )}
                    </div>
                    <div className="flex gap-3">
                        <input
                            type="text"
                            value={departmentInput}
                            onChange={(e) => setDepartmentInput(e.target.value)}
                            onKeyDown={(e) => {
                                if (e.key === 'Enter') {
                                    e.preventDefault();
                                    addDepartment();
                                }
                            }}
                            placeholder="Add department name"
                            className="w-full px-3 py-2 rounded-lg border text-sm"
                            style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-subtle)' }}
                        />
                        <button
                            type="button"
                            onClick={addDepartment}
                            className="px-4 py-2 rounded-lg text-sm font-medium text-white"
                            style={{ backgroundColor: 'var(--color-primary)' }}
                        >
                            Add
                        </button>
                    </div>
                    <SaveButton section="departments" onClick={() => handleSaveSection('departments', { departments: dedupeDepartments(departments) })} />
                </div>

                <div className="rounded-xl border p-6" style={{ backgroundColor: 'var(--color-bg-surface)', borderColor: 'var(--color-border-default)' }}>
                    <SectionHeader icon={<Building2 size={20} />} title="Hiring Page Content" />
                    <p className="text-sm mb-4" style={{ color: 'var(--color-text-secondary)' }}>
                        About the Company is centrally controlled here and auto-applies to all public job pages.
                    </p>
                    <label className="flex items-center gap-3 mb-4 text-sm cursor-pointer" style={{ color: 'var(--color-text-primary)' }}>
                        <input
                            type="checkbox"
                            checked={hiringContent.showAboutCompany}
                            onChange={(e) =>
                                setHiringContent((prev) => ({
                                    ...prev,
                                    showAboutCompany: e.target.checked,
                                }))
                            }
                            className="rounded"
                        />
                        Show About the Company section on public job pages
                    </label>

                    <div>
                        <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>
                            About the Company Text
                        </label>
                        <textarea
                            value={hiringContent.aboutCompanyText}
                            onChange={(e) =>
                                setHiringContent((prev) => ({
                                    ...prev,
                                    aboutCompanyText: e.target.value,
                                }))
                            }
                            onKeyDown={handleBoldShortcut}
                            rows={8}
                            className="w-full px-3 py-2 rounded-lg border text-sm"
                            style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-subtle)' }}
                        />
                    </div>

                    <SaveButton
                        section="hiringContent"
                        onClick={() =>
                            handleSaveSection('hiringContent', {
                                hiring: {
                                    publicJobPage: {
                                        showAboutCompany: hiringContent.showAboutCompany,
                                        aboutCompanyText: hiringContent.aboutCompanyText,
                                    },
                                },
                            })
                        }
                    />
                </div>

            </div>
        </div>
    );
}

import { useState } from 'react';
import { Users, Plus, Search, X, ToggleLeft, ToggleRight, KeyRound, Trash2, Pencil, Eye, EyeOff } from 'lucide-react';
import {
    useGetAdminUsersQuery,
    useCreateAdminUserMutation,
    useUpdateAdminUserMutation,
    useDeactivateUserMutation,
    useActivateUserMutation,
    useResetUserPasswordMutation,
    useDeleteAdminUserMutation,
    useGetAdminRolesQuery,
    useGetOrgSettingsQuery,
} from '@/features/overall-admin/api/adminApi';
import ModalPortal from '@/components/ui/ModalPortal';
import { dedupeDepartments, DEFAULT_DEPARTMENTS } from '@/utils/department';

// ─── Form data ────────────────────────────────────────────────────────────────

interface UserFormData {
    name: string;
    email: string;
    password: string;
    role: string;
    department: string;
}

const initialForm: UserFormData = { name: '', email: '', password: '', role: '', department: '' };

// ─── Edit User Details Modal ──────────────────────────────────────────────────

function EditCredentialsModal({ user, roles, departmentOptions, onClose, onSave, isSaving }: {
    user: any;
    roles: any[];
    departmentOptions: string[];
    onClose: () => void;
    onSave: (data: { name: string; email: string; role: string; department: string }) => void;
    isSaving?: boolean;
}) {
    const [name, setName] = useState(user.name || '');
    const [email, setEmail] = useState(user.email || '');
    const [role, setRole] = useState(typeof user.role === 'object' ? user.role?._id || '' : '');
    const [department, setDepartment] = useState(user.department || '');
    const inputSty = { borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-subtle)' };
    const inputCls = 'w-full px-3 py-2 rounded-lg border text-sm outline-none';

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
            <div className="w-full max-w-lg rounded-[1rem] shadow-premium m-4" style={{ backgroundColor: 'var(--color-bg-surface)' }}>
                <div className="flex items-center justify-between px-5 py-4 border-b" style={{ borderColor: 'var(--color-border-default)' }}>
                    <h3 className="text-base font-semibold" style={{ color: 'var(--color-text-primary)' }}>Edit User Details</h3>
                    <button onClick={onClose} className="p-1 rounded hover:bg-gray-100"><X size={18} /></button>
                </div>
                <div className="px-5 py-4 space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>Full Name</label>
                            <input type="text" value={name} onChange={e => setName(e.target.value)}
                                className={inputCls} style={inputSty} />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>Email</label>
                            <input type="email" value={email} onChange={e => setEmail(e.target.value)}
                                autoComplete="off"
                                className={inputCls} style={inputSty} />
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>Role / Designation</label>
                            <select value={role} onChange={e => setRole(e.target.value)}
                                className={inputCls} style={inputSty}>
                                <option value="" disabled>Select a role</option>
                                {roles.map((r: any) => (
                                    <option key={r._id} value={r._id}>{r.name}</option>
                                ))}
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>Department</label>
                            <select value={department} onChange={e => setDepartment(e.target.value)}
                                className={inputCls} style={inputSty}>
                                <option value="">No Department</option>
                                {departmentOptions.map((d) => <option key={d} value={d}>{d}</option>)}
                            </select>
                        </div>
                    </div>
                    <div className="text-xs" style={{ color: 'var(--color-text-muted)' }}>
                        Use the Reset Password action to change this user&apos;s password.
                    </div>
                </div>
                <div className="flex justify-end gap-3 px-5 py-4 border-t" style={{ borderColor: 'var(--color-border-default)' }}>
                    <button onClick={onClose} disabled={isSaving} className="px-4 py-2 text-sm rounded-lg border disabled:opacity-50" style={{ borderColor: 'var(--color-border-default)' }}>Cancel</button>
                    <button
                        onClick={() => onSave({ name: name.trim(), email: email.trim(), role, department })}
                        disabled={isSaving || !name.trim() || !email.trim() || !role}
                        className="px-4 py-2 text-sm font-semibold rounded-lg text-white disabled:opacity-50"
                        style={{ backgroundColor: 'var(--color-primary)' }}
                    >
                        {isSaving ? 'Saving...' : 'Save Changes'}
                    </button>
                </div>
            </div>
        </div>
    );
}

// ─── AdminUsersPage ───────────────────────────────────────────────────────────

export default function AdminUsersPage() {
    const [search, setSearch] = useState('');
    const [filterStatus, setFilterStatus] = useState('');
    const [page, setPage] = useState(1);
    const [showCreate, setShowCreate] = useState(false);
    const [formData, setFormData] = useState<UserFormData>(initialForm);
    const [editCreds, setEditCreds] = useState<any>(null);
    const [deleteConfirm, setDeleteConfirm] = useState<{ id: string; name: string } | null>(null);
    const [resetPwdUser, setResetPwdUser] = useState<string | null>(null);
    const [newPassword, setNewPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [error, setError] = useState('');

    const { data, isLoading } = useGetAdminUsersQuery({ search, isActive: filterStatus, page, limit: 15 });
    const { data: rolesData } = useGetAdminRolesQuery();
    const { data: orgSettingsData } = useGetOrgSettingsQuery();
    const [createUser, { isLoading: isCreating }] = useCreateAdminUserMutation();
    const [updateUser, { isLoading: isUpdating }] = useUpdateAdminUserMutation();
    const [deactivateUser] = useDeactivateUserMutation();
    const [activateUser] = useActivateUserMutation();
    const [resetPassword, { isLoading: isResetting }] = useResetUserPasswordMutation();
    const [deleteUser, { isLoading: isDeleting }] = useDeleteAdminUserMutation();

    const users = data?.data?.users || [];
    const pagination = data?.data?.pagination;
    const departmentOptions = orgSettingsData?.data?.departments?.length
        ? dedupeDepartments(orgSettingsData.data.departments)
        : DEFAULT_DEPARTMENTS;

    const handleCreate = async (e: React.FormEvent) => {
        e.preventDefault(); setError('');
        try {
            await createUser({
                name: formData.name, email: formData.email,
                password: formData.password, role: formData.role,
                department: formData.department,
            } as any).unwrap();
            setShowCreate(false); setFormData(initialForm);
        } catch (err: any) { setError(err?.data?.message || 'Failed to create user'); }
    };

    const handleSaveCreds = async (payload: { name: string; email: string; role: string; department: string }) => {
        if (!editCreds) return;
        try {
            await updateUser({ id: editCreds._id, data: payload }).unwrap();
            setEditCreds(null);
        } catch (err: any) { alert(err?.data?.message || 'Failed to update user details'); }
    };

    const handleToggle = async (userId: string, isActive: boolean) => {
        try {
            if (isActive) await deactivateUser(userId).unwrap();
            else await activateUser(userId).unwrap();
        } catch (err: any) { alert(err?.data?.message || 'Failed'); }
    };

    const handleDelete = async () => {
        if (!deleteConfirm) return;
        try {
            await deleteUser(deleteConfirm.id).unwrap();
            setDeleteConfirm(null);
        } catch (err: any) { alert(err?.data?.message || 'Failed to delete user'); }
    };

    const handleResetPwd = async () => {
        if (!resetPwdUser || newPassword.length < 8) return;
        try {
            await resetPassword({ id: resetPwdUser, newPassword }).unwrap();
            setResetPwdUser(null); setNewPassword(''); alert('Password reset successfully');
        } catch (err: any) { alert(err?.data?.message || 'Failed'); }
    };

    const getRoleName = (role: any) => role ? (typeof role === 'object' ? role.name : role) : '—';

    const inputCls = 'w-full px-3 py-2 rounded-lg border text-sm outline-none';
    const inputSty = { borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-subtle)' };

    return (
        <div className="p-8 mx-auto" style={{ maxWidth: '1100px' }}>
            {/* Header */}
            <div className="flex items-center justify-between mb-6">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-lg flex items-center justify-center" style={{ backgroundColor: '#EFF6FF', color: '#3B82F6' }}>
                        <Users size={22} />
                    </div>
                    <div>
                        <h1 className="text-2xl font-bold" style={{ color: 'var(--color-text-primary)' }}>Users</h1>
                        <p className="text-sm" style={{ color: 'var(--color-text-secondary)' }}>{pagination?.total || 0} total users</p>
                    </div>
                </div>
                <button onClick={() => { setShowCreate(true); setShowPassword(false); setFormData(initialForm); setError(''); }}
                    className="flex items-center gap-2 px-4 py-2.5 rounded-lg text-white font-medium text-sm" style={{ backgroundColor: 'var(--color-primary)' }}>
                    <Plus size={18} /> Add User
                </button>
            </div>

            {/* Filters */}
            <div className="flex flex-wrap gap-3 mb-6 p-4 rounded-xl shadow-premium border-0" style={{ backgroundColor: 'var(--color-bg-surface)' }}>
                <div className="relative flex-1 min-w-[200px]">
                    <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2" style={{ color: 'var(--color-text-muted)' }} />
                    <input type="text" placeholder="Search by name or email…" value={search}
                        onChange={e => { setSearch(e.target.value); setPage(1); }}
                        className="w-full pl-9 pr-3 py-2 rounded-lg border text-sm" style={inputSty} />
                </div>
                <select value={filterStatus} onChange={e => { setFilterStatus(e.target.value); setPage(1); }}
                    className="px-3 py-2 rounded-lg border text-sm" style={inputSty}>
                    <option value="">All Status</option>
                    <option value="true">Active</option>
                    <option value="false">Inactive</option>
                </select>
            </div>

            {/* Table */}
            <div className="rounded-xl shadow-premium overflow-hidden border-0" style={{ backgroundColor: 'var(--color-bg-surface)' }}>
                {isLoading ? (
                    <div className="p-8 text-center" style={{ color: 'var(--color-text-muted)' }}>Loading users…</div>
                ) : users.length === 0 ? (
                    <div className="p-8 text-center" style={{ color: 'var(--color-text-muted)' }}>No users found</div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead>
                                <tr className="border-b" style={{ borderColor: 'var(--color-border-default)' }}>
                                    {['User', 'Role', 'Department', 'Status', 'Actions'].map(h => (
                                        <th key={h} className={`text-xs font-semibold uppercase tracking-wider px-5 py-3 ${h === 'Actions' ? 'text-right' : 'text-left'}`} style={{ color: 'var(--color-text-muted)' }}>{h}</th>
                                    ))}
                                </tr>
                            </thead>
                            <tbody>
                                {users.map((user: any) => {
                                    const roleStr = getRoleName(user.role).toLowerCase();
                                    const isSuperAdmin = roleStr === 'super-admin' || roleStr === 'super_admin';
                                    return (
                                        <tr key={user._id} className="border-b last:border-b-0 transition-colors" style={{ borderColor: 'var(--color-border-default)' }}>
                                            <td className="px-5 py-3.5">
                                                <div className="flex items-center gap-3">
                                                    <div className="w-9 h-9 rounded-full flex items-center justify-center text-white text-sm font-semibold flex-shrink-0" style={{ backgroundColor: 'var(--color-primary)' }}>
                                                        {user.name?.charAt(0)?.toUpperCase() || 'U'}
                                                    </div>
                                                    <div>
                                                        <div className="text-sm font-medium" style={{ color: 'var(--color-text-primary)' }}>{user.name}</div>
                                                        <div className="text-xs" style={{ color: 'var(--color-text-muted)' }}>{user.email}</div>
                                                    </div>
                                                </div>
                                            </td>
                                            <td className="px-5 py-3.5">
                                                <span className="text-sm" style={{ color: 'var(--color-text-secondary)' }}>{getRoleName(user.role)}</span>
                                            </td>
                                            <td className="px-5 py-3.5">
                                                <span className="text-sm" style={{ color: 'var(--color-text-secondary)' }}>{user.department || '—'}</span>
                                            </td>
                                            <td className="px-5 py-3.5">
                                                <span className="text-xs font-medium px-2.5 py-1 rounded-full"
                                                    style={{ backgroundColor: user.isActive ? '#ECFDF5' : '#FEF2F2', color: user.isActive ? '#059669' : '#DC2626' }}>
                                                    {user.isActive ? 'Active' : 'Inactive'}
                                                </span>
                                            </td>
                                            <td className="px-5 py-3.5">
                                                <div className="flex items-center justify-end gap-1">
                                                    <button onClick={() => setEditCreds(user)} className="p-2 rounded-lg hover:bg-gray-100 transition-colors" title="Edit user details">
                                                        <Pencil size={15} style={{ color: 'var(--color-text-muted)' }} />
                                                    </button>
                                                    {!isSuperAdmin && (
                                                        <>
                                                            <button onClick={() => handleToggle(user._id, user.isActive)} className="p-2 rounded-lg hover:bg-gray-100 transition-colors" title={user.isActive ? 'Deactivate' : 'Activate'}>
                                                                {user.isActive ? <ToggleRight size={16} style={{ color: '#10B981' }} /> : <ToggleLeft size={16} style={{ color: '#EF4444' }} />}
                                                            </button>
                                                            <button onClick={() => setDeleteConfirm({ id: user._id, name: user.name })} className="p-2 rounded-lg hover:bg-red-50 transition-colors" title="Delete user">
                                                                <Trash2 size={15} style={{ color: '#EF4444' }} />
                                                            </button>
                                                        </>
                                                    )}
                                                    <button onClick={() => { setResetPwdUser(user._id); setShowPassword(false); setNewPassword(''); }} className="p-2 rounded-lg hover:bg-gray-100 transition-colors" title="Reset password">
                                                        <KeyRound size={16} style={{ color: 'var(--color-text-muted)' }} />
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    )
                                })}
                            </tbody>
                        </table>
                    </div>
                )}
                {pagination && pagination.pages > 1 && (
                    <div className="flex items-center justify-between px-5 py-3 border-t" style={{ borderColor: 'var(--color-border-default)' }}>
                        <span className="text-sm" style={{ color: 'var(--color-text-muted)' }}>Page {pagination.page} of {pagination.pages}</span>
                        <div className="flex gap-2">
                            <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1} className="px-3 py-1.5 text-sm rounded-lg border disabled:opacity-40" style={{ borderColor: 'var(--color-border-default)' }}>Previous</button>
                            <button onClick={() => setPage(p => p + 1)} disabled={page >= pagination.pages} className="px-3 py-1.5 text-sm rounded-lg border disabled:opacity-40" style={{ borderColor: 'var(--color-border-default)' }}>Next</button>
                        </div>
                    </div>
                )}
            </div>

            {/* Create User Modal */}
            {showCreate && (
                <ModalPortal>

                    <div className="w-full max-w-lg rounded-[1rem] shadow-premium m-4" style={{ backgroundColor: 'var(--color-bg-surface)' }}>
                        <div className="flex items-center justify-between px-6 py-4 border-b" style={{ borderColor: 'var(--color-border-default)' }}>
                            <h3 className="text-lg font-semibold" style={{ color: 'var(--color-text-primary)' }}>Create User</h3>
                            <button onClick={() => setShowCreate(false)} className="p-1.5 rounded hover:bg-gray-100"><X size={18} /></button>
                        </div>
                        <form onSubmit={handleCreate}>
                            <div className="px-6 py-5 space-y-4">
                                {error && <div className="p-3 rounded-lg text-sm text-red-700 bg-red-50 border border-red-200">{error}</div>}
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>Full Name</label>
                                        <input required type="text" value={formData.name} placeholder="e.g. Ananya Sharma"
                                            onChange={e => setFormData({ ...formData, name: e.target.value })}
                                            className={inputCls} style={inputSty} />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>Email</label>
                                        <input required type="email" value={formData.email} placeholder="user@company.com"
                                            autoComplete="off"
                                            onChange={e => setFormData({ ...formData, email: e.target.value })}
                                            className={inputCls} style={inputSty} />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>Password</label>
                                        <div className="relative">
                                            <input required type={showPassword ? "text" : "password"} value={formData.password} minLength={8} placeholder="Min 8 characters"
                                                autoComplete="new-password"
                                                onChange={e => setFormData({ ...formData, password: e.target.value })}
                                                className={inputCls} style={inputSty} />
                                            <button
                                                type="button"
                                                onClick={() => setShowPassword(!showPassword)}
                                                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 focus:outline-none"
                                            >
                                                {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                                            </button>
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>Role / Designation</label>
                                        <select required value={formData.role}
                                            onChange={e => setFormData({ ...formData, role: e.target.value })}
                                            className={inputCls} style={inputSty}>
                                            <option value="" disabled>Select a role</option>
                                            {rolesData?.data?.map((r: any) => (
                                                <option key={r._id} value={r._id}>{r.name}</option>
                                            ))}
                                        </select>
                                    </div>
                                    <div className="col-span-2">
                                        <label className="block text-sm font-medium mb-1" style={{ color: 'var(--color-text-primary)' }}>Department</label>
                                        <select value={formData.department}
                                            onChange={e => setFormData({ ...formData, department: e.target.value })}
                                            className={inputCls} style={inputSty}>
                                            <option value="">No Department</option>
                                            {departmentOptions.map(d => <option key={d} value={d}>{d}</option>)}
                                        </select>
                                    </div>
                                </div>
                                <p className="text-xs" style={{ color: 'var(--color-text-muted)' }}>
                                    💡 After creating the user, go to <strong>Permissions</strong> in the sidebar to assign module access.
                                </p>
                            </div>
                            <div className="flex justify-end gap-3 px-6 py-4 border-t" style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-subtle)' }}>
                                <button type="button" onClick={() => setShowCreate(false)} disabled={isCreating} className="px-4 py-2 text-sm rounded-lg border disabled:opacity-50" style={{ borderColor: 'var(--color-border-default)' }}>Cancel</button>
                                <button type="submit" disabled={isCreating} className="px-5 py-2 text-sm font-semibold rounded-lg text-white disabled:opacity-50" style={{ backgroundColor: 'var(--color-primary)' }}>{isCreating ? 'Creating...' : 'Create User'}</button>
                            </div>
                        </form>
                    </div>
                </ModalPortal>
            )}

            {/* Edit User Details Modal */}
            {editCreds && (
                <EditCredentialsModal
                    user={editCreds}
                    roles={rolesData?.data || []}
                    departmentOptions={departmentOptions}
                    onClose={() => setEditCreds(null)}
                    onSave={handleSaveCreds}
                    isSaving={isUpdating}
                />
            )}

            {/* Delete Confirmation */}
            {deleteConfirm && (
                <ModalPortal>

                    <div className="w-full max-w-sm rounded-[1rem] p-6 m-4 shadow-premium" style={{ backgroundColor: 'var(--color-bg-surface)' }}>
                        <div className="flex items-center gap-3 mb-4">
                            <div className="w-10 h-10 rounded-full flex items-center justify-center" style={{ backgroundColor: '#FEF2F2' }}>
                                <Trash2 size={18} style={{ color: '#EF4444' }} />
                            </div>
                            <div>
                                <h3 className="text-base font-semibold" style={{ color: 'var(--color-text-primary)' }}>Delete User</h3>
                                <p className="text-sm" style={{ color: 'var(--color-text-muted)' }}>This action cannot be undone.</p>
                            </div>
                        </div>
                        <p className="text-sm mb-5" style={{ color: 'var(--color-text-secondary)' }}>
                            Are you sure you want to permanently delete <strong>{deleteConfirm.name}</strong>?
                        </p>
                        <div className="flex justify-end gap-3">
                            <button onClick={() => setDeleteConfirm(null)} disabled={isDeleting} className="px-4 py-2 text-sm rounded-lg border disabled:opacity-50" style={{ borderColor: 'var(--color-border-default)' }}>Cancel</button>
                            <button onClick={handleDelete} disabled={isDeleting} className="px-4 py-2 text-sm font-semibold rounded-lg text-white disabled:opacity-50" style={{ backgroundColor: '#EF4444' }}>{isDeleting ? 'Deleting...' : 'Delete User'}</button>
                        </div>
                    </div>
                </ModalPortal>
            )}

            {/* Reset Password Modal */}
            {resetPwdUser && (
                <ModalPortal>

                    <div className="w-full max-w-sm rounded-[1rem] p-6 m-4 shadow-premium" style={{ backgroundColor: 'var(--color-bg-surface)' }}>
                        <div className="flex items-center justify-between mb-4">
                            <h3 className="text-lg font-semibold" style={{ color: 'var(--color-text-primary)' }}>Reset Password</h3>
                            <button onClick={() => setResetPwdUser(null)} className="p-1 rounded hover:bg-gray-100"><X size={18} /></button>
                        </div>
                        <div className="space-y-4">
                            <div className="relative">
                                <input type={showPassword ? "text" : "password"} value={newPassword} onChange={e => setNewPassword(e.target.value)}
                                    autoComplete="new-password"
                                    className={inputCls} style={inputSty} minLength={8} placeholder="New password (min 8 chars)" />
                                <button
                                    type="button"
                                    onClick={() => setShowPassword(!showPassword)}
                                    className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 focus:outline-none"
                                >
                                    {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
                                </button>
                            </div>
                            <div className="flex justify-end gap-3">
                                <button onClick={() => setResetPwdUser(null)} disabled={isResetting} className="px-4 py-2 text-sm rounded-lg border disabled:opacity-50" style={{ borderColor: 'var(--color-border-default)' }}>Cancel</button>
                                <button onClick={handleResetPwd} disabled={newPassword.length < 8 || isResetting}
                                    className="px-4 py-2 text-sm font-medium rounded-lg text-white disabled:opacity-50" style={{ backgroundColor: '#EF4444' }}>
                                    {isResetting ? 'Resetting...' : 'Reset Password'}
                                </button>
                            </div>
                        </div>
                    </div>
                </ModalPortal>
            )}
        </div>
    );
}

