                                                            </p>
                                                            )
                                                        ))}
                                                </div>
                                            </td>
                                            <td
                                                className="px-4 py-3 text-xs"
                                                style={{ color: 'var(--color-text-secondary)' }}
                                            >
                                                {formatSubmissionTime(submission.submittedAt)}
                                            </td>
                                            <td className="px-4 py-3">
                                                {submission.submittedAfterDeadline ? (
                                                    <span
                                                        className="inline-flex items-center gap-1 rounded-full px-2 py-1 text-[11px] font-medium"
                                                        style={{ backgroundColor: '#FEF3C7', color: '#92400E' }}
                                                    >
                                                        <Clock3 size={11} />
                                                        Late Submission
                                                    </span>
                                                ) : (
                                                    <span
                                                        className="inline-flex items-center gap-1 rounded-full px-2 py-1 text-[11px] font-medium"
                                                        style={{ backgroundColor: '#DCFCE7', color: '#166534' }}
                                                    >
                                                        On Time
                                                    </span>
                                                )}
                                            </td>
                                            <td className="px-4 py-3">
                                                {candidate?._id ? (
                                                    actionState ? (
                                                        <span
                                                            className="inline-flex items-center gap-1 rounded-full px-2 py-1 text-[11px] font-medium"
                                                            style={{
                                                                backgroundColor:
                                                                    actionState === 'rejected'
                                                                        ? '#FEE2E2'
                                                                        : '#DCFCE7',
                                                                color:
                                                                    actionState === 'rejected'
                                                                        ? '#B91C1C'
                                                                        : '#166534',
                                                            }}
                                                        >
                                                            {actionState === 'rejected'
                                                                ? 'Rejected'
                                                                : 'Invited to Interview'}
                                                        </span>
                                                    ) : (
                                                        <div className="flex items-center gap-2">
                                                            <button
                                                                onClick={() => rejectCandidate(submission._id, candidate._id)}
                                                                disabled={updatingStatus || sendingInvite}
                                                                className="inline-flex items-center gap-1 px-2.5 py-1.5 rounded-md border text-xs"
                                                                style={{
                                                                    borderColor: '#FCA5A5',
                                                                    color: '#B91C1C',
                                                                    opacity: updatingStatus || sendingInvite ? 0.6 : 1,
                                                                }}
                                                            >
                                                                <XCircle size={11} />
                                                                Reject
                                                            </button>
                                                            <button
                                                                onClick={() => moveToInterview(submission._id, candidate._id)}
                                                                disabled={updatingStatus || sendingInvite}
                                                                className="inline-flex items-center gap-1 px-2.5 py-1.5 rounded-md border text-xs"
                                                                style={{
                                                                    borderColor: '#86EFAC',
                                                                    color: '#166534',
                                                                    opacity: updatingStatus || sendingInvite ? 0.6 : 1,
                                                                }}
                                                            >
                                                                <CheckCircle2 size={11} />
                                                                Invite to Interview
                                                            </button>
                                                        </div>
                                                    )
                                                ) : (
                                                    <span className="text-xs" style={{ color: 'var(--color-text-muted)' }}>
                                                        N/A
                                                    </span>
                                                )}
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    )}
                </div>
            )}

        </div>
    );
}

import { useEffect, useRef, useState } from 'react';
import { useParams, Link, useNavigate, useLocation } from 'react-router-dom';
import { useGetClientQuery, useGetClientProjectsQuery, useAddClientActivityMutation, useSendClientOnboardingMutation, useGeneratePortalTokenMutation, useRevokePortalTokenMutation, useTogglePortalMutation, useUpdateClientMutation, useUploadClientDocumentsMutation } from '@/features/client/clientApi';
import {
    ArrowLeft,
    Mail,
    Phone,
    MapPin,
    DollarSign,
    Edit,
    FolderKanban,
    Building2,
    Globe,
    FileText,
    Hash,
    Info,
    Plus,
    MessageSquare,
    User,
    Loader2,
    Send,
    CheckCircle2,
    Clock,
    Shield,
    ExternalLink,
    Copy,
    RefreshCw,
    Trash2,
    Link2,
    Upload,
} from 'lucide-react';
import type { Project } from '@/features/project/types/types';
import type { ClientLink } from '@/features/client/types/types';
import { useAppSelector } from '@/app/hooks';
import { useGetPartnersQuery } from '@/features/partners/partnersApi';

type Tab = 'info' | 'projects' | 'activity' | 'documents' | 'links';

export default function ClientDetailPage() {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const location = useLocation();
    const [activeTab, setActiveTab] = useState<Tab>('info');
    const [activityType, setActivityType] = useState<'note' | 'call' | 'email' | 'meeting'>('note');
    const [activityDesc, setActivityDesc] = useState('');
    const [linkName, setLinkName] = useState('');
    const [linkUrl, setLinkUrl] = useState('');
    const [editingLinkIndex, setEditingLinkIndex] = useState<number | null>(null);
    const [confirmingDocumentIndex, setConfirmingDocumentIndex] = useState<string | null>(null);
    const [confirmingLinkIndex, setConfirmingLinkIndex] = useState<number | null>(null);
    const [editingDocumentId, setEditingDocumentId] = useState<string | null>(null);
    const [editingDocumentName, setEditingDocumentName] = useState('');
    const [resendStatus, setResendStatus] = useState<'idle' | 'sending' | 'sent' | 'error'>('idle');
    const [portalLinkCopied, setPortalLinkCopied] = useState(false);
    const [generatePortalToken, { isLoading: isGenerating }] = useGeneratePortalTokenMutation();
    const [revokePortalToken, { isLoading: isRevoking }] = useRevokePortalTokenMutation();
    const [togglePortal, { isLoading: isTogglingPortal }] = useTogglePortalMutation();
    const user = useAppSelector((state) => state.auth.user);
    const roleName = user?.role
        ? typeof user.role === 'object'
            ? String((user.role as any).name || '')
            : String(user.role)
        : '';
    const isAdminUser = ['super-admin', 'super_admin', 'admin'].includes(roleName.toLowerCase());

    const { data: clientData, isLoading, error } = useGetClientQuery(id!);
    const { data: projectsData } = useGetClientProjectsQuery(id!);
    const { data: partnersData } = useGetPartnersQuery({ limit: 200 }, { skip: !isAdminUser });
    const [addActivity, { isLoading: isAddingActivity }] = useAddClientActivityMutation();
    const [updateClient, { isLoading: isUpdatingClient }] = useUpdateClientMutation();
    const [uploadClientDocuments, { isLoading: isUploadingDocuments }] = useUploadClientDocumentsMutation();
    const [sendOnboarding] = useSendClientOnboardingMutation();
    const fileInputRef = useRef<HTMLInputElement>(null);
    useEffect(() => {
        setConfirmingDocumentIndex(null);
        setConfirmingLinkIndex(null);
    }, [activeTab]);


    const handleResendOnboarding = async () => {
        if (!id) return;
        setResendStatus('sending');
        try {
            await sendOnboarding(id).unwrap();
            setResendStatus('sent');
            setTimeout(() => setResendStatus('idle'), 3000);
        } catch {
            setResendStatus('error');
            setTimeout(() => setResendStatus('idle'), 3000);
        }
    };

    if (isLoading) {
        return (
            <div className="p-8">
                <div className="text-center py-12">
                    <div className="inline-block w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
                    <p className="text-neutral-600 mt-4">Loading client...</p>
                </div>
            </div>
        );
    }

    if (error || !clientData) {
        return (
            <div className="p-8">
                <div className="bg-red-50 border border-red-200 rounded-lg p-4 text-red-800">
                    Client not found or failed to load.
                </div>
            </div>
        );
    }

    const client = clientData.data.client;
    const projects = projectsData?.data.projects || [];
    const partnerId = typeof client.partnerId === 'object' ? (client.partnerId as any)?._id : client.partnerId;
    const referredPartner = partnersData?.data?.partners?.find((partner: any) => partner._id === partnerId);

    const handleAddActivity = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!activityDesc.trim()) return;

        try {
            await addActivity({
                clientId: id!,
                data: {
                    type: activityType,
                    description: activityDesc,
                    date: new Date().toISOString(),
                },
            }).unwrap();
            setActivityDesc('');
        } catch (error) {
            console.error('Failed to add activity:', error);
        }
    };

    const currentUserId = (user as any)?._id || (user as any)?.id || '';

    const normalizeLinksForPayload = (links: ClientLink[]) => {
        return links.map((link) => ({
            name: link.name,
            url: link.url,
            addedAt: link.addedAt,
        }));
    };

    const handleRequestDeleteDocument = (documentId: string) => {
        setConfirmingLinkIndex(null);
        setConfirmingDocumentIndex((prev) => (prev === documentId ? null : documentId));
    };

    const splitFileName = (name: string) => {
        const lastDotIndex = name.lastIndexOf('.');
        if (lastDotIndex <= 0) return { base: name, extension: '' };
        return { base: name.slice(0, lastDotIndex), extension: name.slice(lastDotIndex) };
    };

    const handleUploadDocuments = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const files = Array.from(e.target.files || []);
        if (!id || files.length === 0) return;

        try {
            await uploadClientDocuments({ clientId: id, files }).unwrap();
        } catch (error) {
            console.error('Failed to upload documents:', error);
            alert('Failed to upload documents. Please try again.');
        } finally {
            e.target.value = '';
        }
    };

    const handleStartRenameDocument = (documentId: string, currentName: string) => {
        const { base } = splitFileName(currentName);
        setEditingDocumentId(documentId);
        setEditingDocumentName(base);
    };

    const handleCancelRenameDocument = () => {
        setEditingDocumentId(null);
        setEditingDocumentName('');
    };

    const handleSaveRenameDocument = async (documentId: string) => {
        if (!id || !client) return;

        const currentDocument = (client.documents || []).find((doc) => doc._id === documentId);
        if (!currentDocument) return;

        const trimmedBaseName = editingDocumentName.trim();
        if (!trimmedBaseName) {
            alert('Document name cannot be empty.');
            return;
        }

        const { extension } = splitFileName(currentDocument.name);
        const renamedFileName = `${trimmedBaseName}${extension}`;

        const renamedDocuments = (client.documents || [])
            .map((doc) => (doc._id === documentId ? { ...doc, name: renamedFileName } : doc))
            .map((doc) => ({
                name: doc.name,
                url: doc.url,
                cloudinaryId: doc.cloudinaryId,
                size: doc.size,
                mimeType: doc.mimeType,
                uploadedAt: doc.uploadedAt,
                uploadedBy: typeof doc.uploadedBy === 'object' ? (doc.uploadedBy as any)?._id : doc.uploadedBy || currentUserId,
            }));

        try {
            await updateClient({ id, data: { documents: renamedDocuments } }).unwrap();
            handleCancelRenameDocument();
        } catch (error) {
            console.error('Failed to rename document:', error);
            alert('Failed to rename document. Please try again.');
        }
    };

    const handleDeleteDocument = async (documentId: string) => {
        if (!id || !client) return;

        const filteredDocuments = (client.documents || [])
            .filter((doc) => doc._id !== documentId)
            .map((doc) => ({
                name: doc.name,
                url: doc.url,
                cloudinaryId: doc.cloudinaryId,
                size: doc.size,
                mimeType: doc.mimeType,
                uploadedAt: doc.uploadedAt,
                uploadedBy: typeof doc.uploadedBy === 'object' ? (doc.uploadedBy as any)?._id : doc.uploadedBy || currentUserId,
            }));

        try {
            await updateClient({ id, data: { documents: filteredDocuments } }).unwrap();
            setConfirmingDocumentIndex(null);
            if (editingDocumentId === documentId) {
                handleCancelRenameDocument();
            }
        } catch (error) {
            console.error('Failed to delete document:', error);
            alert('Failed to delete document. Please try again.');
        }
    };

    const handleSaveLink = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!id || !linkName.trim() || !linkUrl.trim()) return;

        const existingLinks = [...(client.links || [])] as ClientLink[];
        const nextLink: ClientLink = {
            name: linkName.trim(),
            url: linkUrl.trim(),
            addedAt: new Date().toISOString(),
        };

        if (editingLinkIndex !== null) {
            const prev = existingLinks[editingLinkIndex];
            existingLinks[editingLinkIndex] = {
                ...prev,
                ...nextLink,
                addedAt: prev?.addedAt || nextLink.addedAt,
            };
        } else {
            existingLinks.push(nextLink);
        }

        try {
            await updateClient({
                id,
                data: {
                    links: normalizeLinksForPayload(existingLinks),
                },
            }).unwrap();
            setLinkName('');
            setLinkUrl('');
            setEditingLinkIndex(null);
        } catch (error) {
            console.error('Failed to save link:', error);
        }
    };

    const handleEditLink = (index: number) => {
        const link = (client.links || [])[index];
        if (!link) return;
        setLinkName(link.name || '');
        setLinkUrl(link.url || '');
        setEditingLinkIndex(index);
    };

    const handleDeleteLink = async (index: number) => {
        if (!id) return;
        const existingLinks = [...(client.links || [])] as ClientLink[];
        const nextLinks = existingLinks.filter((_, i) => i !== index);
        try {
            await updateClient({
                id,
                data: {
                    links: normalizeLinksForPayload(nextLinks),
                },
            }).unwrap();
            if (editingLinkIndex === index) {
                setLinkName('');
                setLinkUrl('');
                setEditingLinkIndex(null);
            }
        } catch (error) {
            console.error('Failed to delete link:', error);
        }
    };

    const handleRequestDeleteLink = (index: number) => {
        setConfirmingDocumentIndex(null);
        setConfirmingLinkIndex((prev) => (prev === index ? null : index));
    };

    const activityIcons = {
        note: MessageSquare,
        call: Phone,
        email: Mail,
        meeting: User,
    };

    // Registration Type Label Helper
    const getRegistrationLabel = () => {
        if (!client.registrationType) return null;
        switch (client.registrationType) {
            case 'Registered':
                return { label: 'Registered Entity', color: 'bg-blue-100 text-blue-800', icon: <Building2 size={16} /> };
            case 'Unregistered':
                return { label: 'Unregistered Entity', color: 'bg-gray-100 text-gray-800', icon: <FileText size={16} /> };
            case 'Overseas':
                return { label: 'Overseas Entity', color: 'bg-purple-100 text-purple-800', icon: <Globe size={16} /> };
            default:
                return null;
        }
    };

    const regInfo = getRegistrationLabel();
    const sortedDocuments = [...(client.documents || [])]
        .sort((a, b) => new Date(b.uploadedAt || 0).getTime() - new Date(a.uploadedAt || 0).getTime());
    const sortedLinks = (client.links || [])
        .map((link, originalIndex) => ({ link, originalIndex }))
        .sort((a, b) => new Date(b.link.addedAt || 0).getTime() - new Date(a.link.addedAt || 0).getTime());


    return (
        <div className="p-8 max-w-7xl mx-auto">
            {/* Header */}
            <div className="flex items-center gap-4 mb-6">
                <button
                    onClick={() => navigate('/crm/clients')}
                    className="p-2 hover:bg-neutral-100 rounded-lg transition-colors"
                >
                    <ArrowLeft size={24} />
                </button>
                <div className="flex-1">
                    <div className="flex items-center gap-3">
                        <h1 className="text-3xl font-bold text-neutral-900">{client.name}</h1>
                        <span
                            className={`px-3 py-1 text-sm font-medium rounded ${client.status === 'active'
                                ? 'bg-green-100 text-green-800'
                                : client.status === 'inactive'
                                    ? 'bg-yellow-100 text-yellow-800'
                                    : 'bg-neutral-100 text-neutral-800'
                                }`}
                        >
                            {client.status}
                        </span>
                    </div>
                    {client.companyName && (
                        <p className="text-neutral-600 mt-1 flex items-center gap-2">
                            <Building2 size={16} className="text-neutral-400" />
                            {client.companyName}
                        </p>
                    )}
                </div>

                {/* Onboarding status badge */}
                {client.onboardingStatus && (
                    <div className="flex items-center gap-2">
                        {client.onboardingStatus === 'submitted' ? (
                            <span className="flex items-center gap-1.5 px-3 py-1 bg-green-50 text-green-700 border border-green-200 rounded-full text-xs font-medium">
                                <CheckCircle2 size={12} />
                                Form Submitted
                            </span>
                        ) : (
                            <span className="flex items-center gap-1.5 px-3 py-1 bg-amber-50 text-amber-700 border border-amber-200 rounded-full text-xs font-medium">
                                <Clock size={12} />
                                Onboarding Pending
                            </span>
                        )}
                    </div>
                )}
                {/* Resend / Send onboarding form */}
                {client.email && client.onboardingStatus !== 'submitted' && (
                    <button
                        onClick={handleResendOnboarding}
                        disabled={resendStatus === 'sending'}
                        className="flex items-center gap-2 px-4 py-2 border border-neutral-300 text-neutral-700 rounded-lg hover:bg-neutral-50 transition-colors disabled:opacity-50 text-sm"
                        title={`Send onboarding form to ${client.email}`}
                    >
                        {resendStatus === 'sending' ? (
                            <Loader2 size={16} className="animate-spin" />
                        ) : resendStatus === 'sent' ? (
                            <CheckCircle2 size={16} className="text-green-500" />
                        ) : (
                            <Send size={16} />
                        )}
                        {resendStatus === 'sent' ? 'Sent!' : resendStatus === 'error' ? 'Failed' : client.onboardingStatus === 'pending' ? 'Resend Form' : 'Send Onboarding Form'}
                    </button>
                )}
                <Link
                    to={`/crm/clients/${id}/edit`}
                    state={{ backgroundLocation: location, returnTo: location.pathname }}
                    className="flex items-center gap-2 px-4 py-2 bg-primary text-white rounded-lg hover:bg-primary-dark transition-colors"
                >
                    <Edit size={20} />
                    Edit Client
                </Link>
            </div>

            {/* Tabs Navigation */}
            <div className="border-b border-neutral-200 mb-6">
                <div className="flex gap-6">
                    <button
                        onClick={() => setActiveTab('info')}
                        className={`pb-3 px-1 text-sm font-medium transition-colors border-b-2 ${activeTab === 'info'
                            ? 'border-primary text-primary'
                            : 'border-transparent text-neutral-500 hover:text-neutral-700'
                            }`}
                    >
                        Client Information
                    </button>
                    <button
                        onClick={() => setActiveTab('projects')}
                        className={`pb-3 px-1 text-sm font-medium transition-colors border-b-2 ${activeTab === 'projects'
                            ? 'border-primary text-primary'
                            : 'border-transparent text-neutral-500 hover:text-neutral-700'
                            }`}
                    >
                        Projects ({projects.length})
                    </button>
                    <button
                        onClick={() => setActiveTab('activity')}
                        className={`pb-3 px-1 text-sm font-medium transition-colors border-b-2 ${activeTab === 'activity'
                            ? 'border-primary text-primary'
                            : 'border-transparent text-neutral-500 hover:text-neutral-700'
                            }`}
                    >
                        Activity Logged
                    </button>
                    <button
                        onClick={() => setActiveTab('documents')}
                        className={`pb-3 px-1 text-sm font-medium transition-colors border-b-2 ${activeTab === 'documents'
                            ? 'border-primary text-primary'
                            : 'border-transparent text-neutral-500 hover:text-neutral-700'
                            }`}
                    >
                        Documents ({client.documents?.length || 0})
                    </button>
                    <button
                        onClick={() => setActiveTab('links')}
                        className={`pb-3 px-1 text-sm font-medium transition-colors border-b-2 ${activeTab === 'links'
                            ? 'border-primary text-primary'
                            : 'border-transparent text-neutral-500 hover:text-neutral-700'
                            }`}
                    >
                        Links ({client.links?.length || 0})
                    </button>
                </div>
            </div>

            {/* Tab Content */}
            {activeTab === 'info' ? (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Left Column */}
                    <div className="lg:col-span-2 space-y-6">
                        {/* Summary & Registration Card */}
                        <div className="bg-white rounded-lg border border-neutral-200 p-6 shadow-sm">
                            <h2 className="text-lg font-semibold text-neutral-900 mb-4 flex items-center gap-2">
                                <Info size={20} className="text-primary" />
                                Business Details
                            </h2>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div>
                                    <p className="text-sm text-neutral-500 mb-1">Registration Type</p>
                                    {regInfo ? (
                                        <div className={`inline-flex items-center gap-2 px-3 py-1 rounded-full text-sm font-medium ${regInfo.color}`}>
                                            {regInfo.icon}
                                            {regInfo.label}
                                        </div>
                                    ) : (
                                        <p className="text-neutral-900 font-medium">Not Specified</p>
                                    )}
                                </div>

                                {isAdminUser && referredPartner && (
                                    <div>
                                        <p className="text-sm text-neutral-500 mb-1">Referred By Partner</p>
                                        <Link
                                            to={`/admin/partners/manage/${referredPartner._id}`}
                                            className="inline-flex items-center gap-2 text-neutral-900 font-medium hover:text-primary"
                                        >
                                            <Shield size={16} className="text-neutral-400" />
                                            {referredPartner.userId?.name || referredPartner.contactPerson || referredPartner.companyName || 'Partner'}
                                        </Link>
                                    </div>
                                )}

                                {client.gstNumber && (
                                    <div>
                                        <p className="text-sm text-neutral-500 mb-1">GST Number</p>
                                        <p className="text-neutral-900 font-medium font-mono flex items-center gap-2">
                                            <Hash size={16} className="text-neutral-400" />
                                            {client.gstNumber}
                                        </p>
                                    </div>
                                )}

                                {client.vatNumber && (
                                    <div>
                                        <p className="text-sm text-neutral-500 mb-1">VAT Number</p>
                                        <p className="text-neutral-900 font-medium font-mono flex items-center gap-2">
                                            <Hash size={16} className="text-neutral-400" />
                                            {client.vatNumber}
                                        </p>
                                    </div>
                                )}
                            </div>

                            {/* Address */}
                            {client.address && (
                                <div className="mt-6 pt-6 border-t border-neutral-100">
                                    <h3 className="text-sm font-semibold text-neutral-900 mb-3 flex items-center gap-2">
                                        <MapPin size={16} className="text-neutral-400" />
                                        Address
                                    </h3>
                                    <p className="text-neutral-700">
                                        {client.address.street && <span className="block">{client.address.street}</span>}
                                        <span className="block">
                                            {[client.address.city, client.address.state, client.address.postalCode]
                                                .filter(Boolean)
                                                .join(', ')}
                                        </span>
                                        {client.address.country && <span className="block font-medium">{client.address.country}</span>}
                                    </p>
                                </div>
                            )}
                        </div>

                        {/* Additional Details (Custom Fields) */}
                        {client.customDetails && client.customDetails.length > 0 && (
                            <div className="bg-white rounded-lg border border-neutral-200 p-6 shadow-sm">
                                <h2 className="text-lg font-semibold text-neutral-900 mb-4 flex items-center gap-2">
                                    <FileText size={20} className="text-primary" />
                                    Additional Information
                                </h2>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    {client.customDetails.map((detail, index) => (
                                        <div key={index} className="bg-neutral-50 p-3 rounded-lg border border-neutral-100">
                                            <p className="text-xs text-neutral-500 font-medium uppercase mb-1">{detail.key}</p>
                                            <p className="text-sm text-neutral-900">{detail.value}</p>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {/* Notes */}
                        {client.notes && (
                            <div className="bg-white rounded-lg border border-neutral-200 p-6 shadow-sm">
                                <h2 className="text-lg font-semibold text-neutral-900 mb-4">Notes</h2>
                                <p className="text-sm text-neutral-700 whitespace-pre-wrap bg-yellow-50 p-4 rounded-lg border border-yellow-100 text-yellow-900">
                                    {client.notes}
                                </p>
                            </div>
                        )}
                    </div>

                    {/* Right Column */}
