}

import { useState, useRef, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { useNavigate, useLocation } from 'react-router-dom';
import {
    Plus,
    Search,
    LayoutDashboard,
    List,
    Calendar,
    Loader2,
    AlertCircle,
    Mail,
    MessageSquare,
    User,
} from 'lucide-react';
import {
    DndContext,
    DragOverlay,
    PointerSensor,
    useSensor,
    useSensors,
    useDroppable,
    useDraggable,
    type DragCancelEvent,
    type DragEndEvent,
    type DragStartEvent,
} from '@dnd-kit/core';
import { useGetLeadsQuery, useUpdateLeadMutation } from '@/features/crm';
import type { Lead } from '@/features/crm';

const stages = [
    { id: 'new', label: 'New', color: 'var(--color-info)' },
    { id: 'contacted', label: 'Contacted', color: 'var(--color-warning)' },
    { id: 'qualified', label: 'Qualified', color: 'var(--color-success)' },
    { id: 'proposal-sent', label: 'Proposal', color: '#4338CA' },
    { id: 'negotiation', label: 'Negotiation', color: '#7E22CE' },
    { id: 'closed', label: 'Closed', color: 'var(--color-success-dark, #059669)' },
    { id: 'pending', label: 'Pending', color: '#92400E' },
    { id: 'lead-lost', label: 'Lost', color: 'var(--color-danger)' },
    { id: 'follow-up', label: 'Follow Up', color: '#1D4ED8' },
];

// ============================================
// LEAD CARD
// ============================================
function LeadCard({
    lead,
    onClick,
    dragProps,
    isDragging = false,
}: {
    lead: Lead;
    onClick?: () => void;
    dragProps?: {
        setNodeRef?: (element: HTMLElement | null) => void;
        attributes?: Record<string, any>;
        listeners?: Record<string, any>;
    };
    isDragging?: boolean;
}) {
    const partnerName = typeof lead.partnerId === 'object'
        ? (lead.partnerId as any)?.userId?.name || (lead.partnerId as any)?.contactPerson || (lead.partnerId as any)?.companyName || 'Partner'
        : lead.partnerId
            ? 'Partner'
            : '';

    return (
        <div
            ref={dragProps?.setNodeRef}
            {...dragProps?.listeners}
            {...dragProps?.attributes}
            onClick={onClick}
            style={{
                cursor: dragProps ? (isDragging ? 'grabbing' : 'grab') : undefined,
                opacity: isDragging ? 0.35 : 1,
            }}
            className="bg-white p-3 rounded-lg border border-gray-200 shadow-sm hover:shadow-md transition-shadow touch-none"
        >
            <h3 className="font-medium text-sm text-gray-900 line-clamp-2">{lead.name}</h3>
            {lead.company && <p className="text-xs text-gray-500 truncate">{lead.company}</p>}
            {lead.email && (
                <div className="flex items-center gap-1 text-xs text-gray-400 mt-1">
                    <Mail size={10} className="shrink-0" />
                    <span className="truncate">{lead.email}</span>
                </div>
            )}

            {lead.expectedCloseDate && (
                <div className="flex items-center gap-1 text-xs text-gray-500 mt-3 pt-3 border-t border-gray-100">
                    <Calendar size={12} />
                    <span>
                        {new Date(lead.expectedCloseDate).toLocaleDateString(undefined, {
                            month: 'short',
                            day: 'numeric',
                        })}
                    </span>
                </div>
            )}

            {/* Notes preview */}
            {lead.notes && (
                <div className="flex items-start gap-1 text-xs text-gray-400 mt-1.5 mb-1">
                    <MessageSquare size={10} className="shrink-0 mt-0.5" />
                    <span className="line-clamp-1">{lead.notes}</span>
                </div>
            )}

            {lead.partnerId && (
                <div className="mt-2 mb-1 inline-flex items-center rounded-full px-2 py-0.5 text-[11px] font-medium bg-blue-100 text-blue-700">
                    Referred by: {partnerName}
                </div>
            )}

            <div className="mt-2 flex justify-between items-center">
                <div className="flex items-center gap-1.5 min-w-0 flex-1">
                    <div className="w-5 h-5 rounded-full bg-primary/10 flex items-center justify-center text-[10px] font-semibold shrink-0" style={{ color: 'var(--color-primary)' }}>
                        {(lead.assignedTo as any)?.name?.[0]?.toUpperCase() || <User size={10} />}
                    </div>
                    <span className="text-xs text-gray-500 truncate">
                        {(lead.assignedTo as any)?.name || 'Unassigned'}
                    </span>
                </div>
                <div
                    className="w-2 h-2 rounded-full"
                    style={{
                        backgroundColor:
                            lead.priority === 'critical' ? 'var(--color-danger)' :
                                lead.priority === 'high' ? '#EA580C' :
                                    lead.priority === 'medium' ? 'var(--color-warning)' :
                                        'var(--color-success)',
                    }}
                />
            </div>
        </div>
    );
}

function DraggableLeadCard({ lead, onClick }: { lead: Lead; onClick: () => void }) {
    const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
        id: lead._id,
        data: { lead },
    });

    const wasDragging = useRef(false);
    useEffect(() => {
        if (isDragging) {
            wasDragging.current = true;
            return;
        }

        if (wasDragging.current) {
            const timeoutId = window.setTimeout(() => {
                wasDragging.current = false;
            }, 0);
            return () => window.clearTimeout(timeoutId);
        }
    }, [isDragging]);

    return (
        <LeadCard
            lead={lead}
            dragProps={{ setNodeRef, listeners, attributes }}
            isDragging={isDragging}
            onClick={() => {
                if (wasDragging.current) return;
                onClick();
            }}
        />
    );
}

// ============================================
// DROPPABLE COLUMN
// ============================================
function StageColumn({
    stage,
    leads,
    navigate,
    returnTo,
}: {
    stage: { id: string; label: string; color: string };
    leads: Lead[];
    navigate: (path: string, options?: any) => void;
    returnTo: string;
}) {
    const { setNodeRef, isOver } = useDroppable({ id: stage.id });

    return (
        <div
            ref={setNodeRef}
            className={`flex flex-col w-72 h-full rounded-xl border transition-colors ${isOver
                    ? 'bg-primary/5 border-primary/30 ring-2 ring-primary/20'
                    : 'bg-gray-100/50 border-gray-200'
                }`}
        >
            {/* Column Header */}
            <div className="p-3 border-b border-gray-200 bg-white rounded-t-xl">
                <div className="flex justify-between items-center">
                    <span
                        className="text-xs font-semibold px-2 py-1 rounded-full uppercase"
                        style={{ backgroundColor: `${stage.color}20`, color: stage.color }}
                    >
                        {stage.label}
                    </span>
                    <span className="text-xs text-gray-500 font-medium">{leads.length}</span>
                </div>
            </div>

            {/* Cards Container */}
            <div className="flex-1 overflow-y-auto p-2 space-y-3">
                {leads.map((lead) => (
                    <DraggableLeadCard
                        key={lead._id}
                        lead={lead}
                        onClick={() => navigate(`/crm/leads/${lead._id}`, { state: { returnTo } })}
                    />
                ))}
                {leads.length === 0 && (
                    <div
                        className={`text-center py-8 text-xs border-2 border-dashed rounded-lg ${isOver
                                ? 'text-primary/60 border-primary/30 bg-primary/5'
                                : 'text-gray-400 border-gray-200'
                            }`}
                    >
                        {isOver ? 'Drop here' : 'No deals'}
                    </div>
                )}
            </div>
        </div>
    );
}

// ============================================
// MAIN PIPELINE PAGE
// ============================================
export default function CrmPipelinePage() {
    const navigate = useNavigate();
    const location = useLocation();
    const [search, setSearch] = useState('');
    const [activeLead, setActiveLead] = useState<Lead | null>(null);
    const [activeLeadWidth, setActiveLeadWidth] = useState<number | null>(null);
    const { data, isLoading, error } = useGetLeadsQuery({ limit: 200, search });
    const [updateLead] = useUpdateLeadMutation();

    const leads = data?.data.leads || [];

    const columns = stages.map((stage) => {
        const stageLeads = leads.filter((lead) => lead.stage === stage.id);
        return { ...stage, leads: stageLeads };
    });

    // DnD sensors — activate after 5px movement to allow click-through
    const sensors = useSensors(
        useSensor(PointerSensor, {
            activationConstraint: { distance: 5 },
        })
    );

    const handleDragStart = (event: DragStartEvent) => {
        setActiveLead(event.active.data.current?.lead ?? null);
        setActiveLeadWidth(event.active.rect.current.initial?.width ?? null);
    };

    const handleDragCancel = (_event: DragCancelEvent) => {
        setActiveLead(null);
        setActiveLeadWidth(null);
    };

    const handleDragEnd = async (event: DragEndEvent) => {
        const { active, over } = event;
        setActiveLead(null);
        setActiveLeadWidth(null);
        if (!over) return;

        const leadId = active.id as string;
        const newStage = over.id as string;
        const lead = leads.find((l) => l._id === leadId);

        // Don't update if dropping into the same stage
        if (!lead || lead.stage === newStage) return;

        // Don't allow moving locked leads
        if (lead.isLocked) return;

        try {
            await updateLead({
                id: leadId,
                data: { stage: newStage as Lead['stage'] },
            }).unwrap();
        } catch (err) {
            console.error('Failed to update lead stage:', err);
        }
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center h-[calc(100vh-64px)]">
                <Loader2 className="animate-spin text-gray-500 mr-2" />
                <span className="text-gray-500">Loading pipeline...</span>
            </div>
        );
    }

    if (error) {
        return (
            <div className="flex items-center justify-center h-[calc(100vh-64px)] text-red-500">
                <AlertCircle className="mr-2" />
                Error loading pipeline
            </div>
        );
    }

    return (
        <div className="flex flex-col h-[calc(100vh-var(--topbar-height))] min-h-[calc(100vh-var(--topbar-height))] -mx-4 -mt-5 w-[calc(100%+2rem)] sm:-mx-6 sm:-mt-6 sm:w-[calc(100%+3rem)] lg:-mx-8 lg:-mt-7 lg:w-[calc(100%+4rem)]">
            {/* Header */}
            <div className="flex-none px-4 sm:px-6 py-4 bg-white border-b border-gray-200">
                <div className="flex justify-between items-center">
                    <h1 className="text-2xl font-bold text-gray-900">Deals Pipeline</h1>
                    <div className="flex items-center gap-3">
                        <div className="relative">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                            <input
                                type="text"
                                placeholder="Search deals..."
                                value={search}
                                onChange={(e) => setSearch(e.target.value)}
                                className="pl-9 pr-4 py-2 rounded-lg border border-gray-200 text-sm w-64 focus:outline-none focus:ring-2 focus:ring-primary/20"
                            />
                        </div>
                        <div className="flex bg-gray-100 rounded-lg p-1 border border-gray-200">
                            <button
                                onClick={() => navigate('/crm/leads')}
                                className="p-2 rounded hover:bg-white text-gray-500"
                            >
                                <List size={18} />
                            </button>
                            <button className="p-2 rounded bg-white shadow-sm text-primary">
                                <LayoutDashboard size={18} />
                            </button>
                        </div>
                        <button
                            className="flex items-center gap-2 px-4 py-2 bg-primary text-white rounded-lg hover:bg-primary-dark transition-colors"
                            onClick={() =>
                                navigate('/crm/leads/new', {
                                    state: {
                                        backgroundLocation: location,
                                        returnTo: location.pathname,
                                    },
                                })
                            }
                        >
                            <Plus size={16} />
                            New Deal
                        </button>
                    </div>
                </div>
            </div>

            {/* Kanban Board with DnD */}
            <DndContext
                sensors={sensors}
                onDragStart={handleDragStart}
                onDragCancel={handleDragCancel}
                onDragEnd={handleDragEnd}
            >
                <div className="flex-1 min-h-0 overflow-x-auto px-4 sm:px-6 py-4 bg-gray-50">
                    <div className="flex h-full gap-4 min-w-max">
                        {columns.map((column) => (
                            <StageColumn
                                key={column.id}
                                stage={column}
                                leads={column.leads}
                                navigate={navigate}
                                returnTo={location.pathname}
                            />
                        ))}
                    </div>
                </div>
                {typeof document !== 'undefined'
                    ? createPortal(
                        <DragOverlay zIndex={9999}>
                            {activeLead ? (
                                <div
                                    className="rotate-0 shadow-2xl"
                                    style={{ width: activeLeadWidth ?? undefined }}
                                >
                                    <LeadCard lead={activeLead} />
                                </div>
                            ) : null}
                        </DragOverlay>,
                        document.body
                    )
                    : null}
            </DndContext>
        </div>
    );
}

import { Suspense, lazy, useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useForm, useFieldArray, type SubmitHandler } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import {
    ArrowLeft,
    Save,
    Loader2,
    AlertCircle,
    Layout,
    Target,
    Cpu,
    Calendar,
    DollarSign,
    Plus,
    Trash2,
    FileText
} from 'lucide-react';
import {
    useCreateProposalMutation,
    useGetLeadsQuery,
    useGetProposalByIdQuery,
    useUpdateProposalMutation,
} from '@/features/crm';
import type { Proposal } from '@/features/crm/types/types';

// Tab Components
import OverviewTab from '../features/crm/components/Proposal/OverviewTab';
import ScopeTab from '../features/crm/components/Proposal/ScopeTab';
import TechTab from '../features/crm/components/Proposal/TechTab';
import ExecutionTab from '../features/crm/components/Proposal/ExecutionTab';
import BudgetTab from '../features/crm/components/Proposal/BudgetTab';

const ProposalPdfDownloadButton = lazy(() => import('../features/crm/components/Proposal/ProposalPdfDownloadButton'));

// Schema - We can use a looser schema for portions or the full one. 
// For now, let's keep the base required fields tight and others optional/flexible as defined in validator.
// We'll trust the backend validation for the complex nested structures or add Zod there if needed.
const baseProposalSchema = z.object({
    title: z.string().min(1, 'Title is required'),
    leadId: z.string().min(1, 'Lead is required'),
    validUntil: z.string().optional(),
    // We allow items to be empty if using BudgetV2, but for now let's keep it as is or optional
    items: z.array(z.any()).optional(),
    tax: z.coerce.number().min(0).default(0),
    currency: z.string().default('INR'),
    status: z.string().default('draft'),
});

export default function CrmProposalFormPage() {
    const { id } = useParams<{ id: string }>();
    const isEditMode = !!id;
    const navigate = useNavigate();
    const [serverError, setServerError] = useState<string | null>(null);
    const [activeTab, setActiveTab] = useState<'overview' | 'scope' | 'tech' | 'execution' | 'budget'>('overview');

    // Fetch leads
    const { data: leadsData, isLoading: isLoadingLeads } = useGetLeadsQuery({ limit: 100 });
    const leads = leadsData?.data.leads || [];

    // Fetch proposal
    const { data: proposalData, isLoading: isLoadingProposal } = useGetProposalByIdQuery(id!, { skip: !isEditMode });

    const [createProposal, { isLoading: isCreating }] = useCreateProposalMutation();
    const [updateProposal, { isLoading: isUpdating }] = useUpdateProposalMutation();

    const form = useForm<Partial<Proposal>>({
        resolver: zodResolver(baseProposalSchema) as any,
        defaultValues: {
            currency: 'INR',
            tax: 0,
            items: [{ description: '', quantity: 1, unitPrice: 0, total: 0 }],
            status: 'draft',
            // Initialize empty sections to avoid undefined errors in tabs
            overview: {},
            businessChallenge: { painPoints: [] },
            targetAudience: {},
            goals: {},
            scopeOfWork: { phases: [] },
            features: { phases: [] },
            userFlow: { steps: [] },
            techStack: { integrations: [] },
            nfr: {},
            designRequirements: {},
            deliverables: { phases: [] },
            successMetrics: { business: [], user: [], technical: [] },
            dependencies: { assumptions: [], constraints: [], clientRequirements: [] },
            timeline: { phases: [] },
            team: { resources: [] },
            budgetV2: { includeExclude: [], thirdPartyCosts: [], paymentSchedule: [] },
            futureScope: { items: [] },
            risks: { items: [] },
            terms: { clauses: [] },
            nextSteps: [],
        },
    });

    const { register, control, handleSubmit, watch, reset, setValue, formState: { errors } } = form;

    const { fields: itemFields, append: appendItem, remove: removeItem } = useFieldArray({
        control,
        name: 'items',
    });

    const formData = watch();

    // Calculate totals for the Legacy Items (still useful for quick quotes)
    const items = formData.items || [];
    const taxRate = formData.tax || 0;
    const subtotal = items.reduce((sum, item) => sum + ((item.quantity || 0) * (item.unitPrice || 0)), 0);
    const taxAmount = (subtotal * taxRate) / 100;
    const total = subtotal + taxAmount;

    // Sync total to form data if needed, or just let backend handle it.
    // We'll update it visually.

    useEffect(() => {
        if (proposalData?.data.proposal) {
            const p = proposalData.data.proposal;
            // Spread to ensure all nested fields are populated
            reset({
                ...p,
                validUntil: p.validUntil ? new Date(p.validUntil).toISOString().split('T')[0] : '',
                leadId: (p.leadId as any)?._id || p.leadId,
            });
        }
    }, [proposalData, reset]);

    const handleChildChange = (newData: Partial<Proposal>) => {
        // Merge new data into form state
        // This is a bit heavy-handed, but ensures sync. 
        // Optimized way: pass specific handlers. simpler way:
        Object.keys(newData).forEach((key) => {
            setValue(key as keyof Proposal, newData[key as keyof Proposal], { shouldDirty: true });
        });
    };

    const onSubmit: SubmitHandler<Partial<Proposal>> = async (data) => {
        setServerError(null);
        try {
            const payload = {
                ...data,
                items: data.items?.map((item: any) => ({
                    ...item,
                    quantity: Number(item.quantity),
                    unitPrice: Number(item.unitPrice),
                    total: Number(item.quantity) * Number(item.unitPrice)
                })),
                tax: Number(data.tax),
                subtotal, // Client calculation
                total,    // Client calculation
            };

            if (isEditMode) {
                await updateProposal({ id: id!, data: payload }).unwrap();
            } else {
                await createProposal(payload as any).unwrap();
            }
            navigate('/crm/proposals');
        } catch (error: any) {
            console.error('Failed to save:', error);
            setServerError(error.data?.message || 'Failed to save proposal.');
        }
    };

    const isLoading = isEditMode ? isLoadingProposal : false;
    const isSaving = isCreating || isUpdating;

    if (isLoading) return <div className="flex justify-center p-10"><Loader2 className="animate-spin" /></div>;

    const tabs = [
        { id: 'overview', label: 'Overview', icon: Layout },
        { id: 'scope', label: 'Scope', icon: Target },
        { id: 'tech', label: 'Tech', icon: Cpu },
        { id: 'execution', label: 'Execution', icon: Calendar },
        { id: 'budget', label: 'Budget/Terms', icon: DollarSign },
    ];

    return (
        <div className="max-w-6xl mx-auto p-6 pb-20">
            {/* Header */}
            <div className="flex items-center justify-between mb-6">
                <div className="flex items-center gap-4">
                    <button onClick={() => navigate(-1)} className="p-2 hover:bg-gray-100 rounded-full">
                        <ArrowLeft size={20} className="text-gray-500" />
                    </button>
                    <div>
                        <h1 className="text-2xl font-bold text-gray-900">{isEditMode ? 'Edit Proposal' : 'New Proposal'}</h1>
                        <p className="text-sm text-gray-500">Create a comprehensive business proposal</p>
                    </div>
                </div>
                <div className="flex gap-3">
                    <button
                        type="button"
                        onClick={() => navigate(-1)}
                        className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50"
                    >
                        Cancel
                    </button>
                    {isEditMode && proposalData?.data.proposal && (
                        <Suspense
                            fallback={
                                <button
                                    type="button"
                                    disabled
                                    className="flex items-center gap-2 px-4 py-2 border border-blue-200 bg-blue-50 text-blue-700 rounded-lg opacity-70"
                                >
                                    <FileText size={18} />
                                    Loading PDF...
                                </button>
                            }
                        >
                            <ProposalPdfDownloadButton proposal={proposalData.data.proposal} />
                        </Suspense>
                    )}
                    <button
                        onClick={handleSubmit(onSubmit)}
                        disabled={isSaving}
                        className="flex items-center gap-2 px-6 py-2 bg-primary text-white rounded-lg hover:bg-primary-dark disabled:opacity-50"
                    >
                        {isSaving ? <Loader2 size={18} className="animate-spin" /> : <Save size={18} />}
                        Save Proposal
                    </button>
                </div>
            </div>

            {serverError && (
                <div className="mb-6 p-4 bg-red-50 text-red-700 rounded-lg flex items-center gap-2">
                    <AlertCircle size={20} />
                    {serverError}
                </div>
            )}

            <form className="space-y-6">
                {/* 1. Core Details (Always Visible) */}
                <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-sm grid grid-cols-1 md:grid-cols-4 gap-6">
                    <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700 mb-1">Proposal Title *</label>
                        <input
                            {...register('title')}
                            className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20"
                            placeholder="e.g. E-Commerce Platform Revamp"
                        />
                        {errors.title && <p className="text-xs text-red-500 mt-1">{String(errors.title.message)}</p>}
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Client *</label>
                        <select
                            {...register('leadId')}
                            className="w-full px-4 py-2 rounded-lg border border-gray-200 bg-white"
                            disabled={isLoadingLeads}
                        >
                            <option value="">Select Lead...</option>
