                                                            className="mt-4 inline-flex items-center gap-2 rounded-lg border px-3 py-2 text-xs font-medium"
                                                            style={{ borderColor: 'var(--color-border-default)', color: 'var(--color-text-primary)', backgroundColor: '#F9FAFB' }}
                                                        >
                                                            <Pencil size={13} />
                                                            Edit Account
                                                        </button>
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>
