                                    <button
                                        type="button"
                                        onClick={openOtherAccountCreator}
                                        className="inline-flex w-full items-center justify-center gap-2 rounded-lg px-4 py-3 text-sm font-semibold text-white"
                                        style={{ backgroundColor: 'var(--color-primary)' }}
                                    >
                                        <Plus size={16} />
                                        Add Account
                                    </button>
                                </div>
                            )}
                        </aside>
                    </div>
                </ModalPortal>
            )}
        </div>
    );
}

