                                            </div>
                                            <p className="text-xs mt-2" style={{ color: '#6B7280' }}>
                                                Due fixed expenses appear here on their scheduled date. Approving creates the expense entry, and rejecting keeps a clear decision trail.
                                            </p>
                                        </div>

                                        {isLoadingApprovals ? (
                                            <div className="rounded-2xl border p-8 flex items-center justify-center" style={{ borderColor: '#E5E7EB' }}>
                                                <Loader2 size={20} className="animate-spin" style={{ color: '#4F46E5' }} />
                                            </div>
                                        ) : approvalItems.length === 0 ? (
                                            <div className="rounded-2xl border p-8 text-center" style={{ borderColor: '#E5E7EB' }}>
                                                <ShieldCheck size={28} className="mx-auto mb-3" style={{ color: '#A5B4FC' }} />
                                                <p className="text-sm font-medium" style={{ color: '#374151' }}>No approval requests yet</p>
                                                <p className="text-xs mt-1" style={{ color: '#6B7280' }}>Once a fixed expense reaches its due date, the request will show up here.</p>
                                            </div>
                                        ) : (
                                            approvalItems.map((approval: any) => {
                                                const draft = approvalDrafts[approval._id];
                                                const isExpanded = expandedApprovalId === approval._id;
                                                const statusConfig = approval.status === 'approved'
                                                    ? { icon: CheckCircle2, bg: '#DCFCE7', color: '#166534', label: 'Approved' }
                                                    : approval.status === 'rejected'
                                                        ? { icon: CircleX, bg: '#FEE2E2', color: '#991B1B', label: 'Rejected' }
                                                        : { icon: Clock3, bg: '#FEF3C7', color: '#92400E', label: 'Pending Approval' };
                                                const StatusIcon = statusConfig.icon;

                                                return (
                                                    <div key={approval._id} className="rounded-2xl border p-4" style={{ borderColor: '#E5E7EB', backgroundColor: '#FFFFFF' }}>
                                                        <div className="flex flex-wrap items-center justify-between gap-3">
                                                            <div className="min-w-0">
                                                                <div className="flex items-center gap-2 flex-wrap">
                                                                    <h4 className="text-sm font-semibold" style={{ color: '#111827' }}>{approval.title}</h4>
                                                                    <span className="inline-flex items-center gap-1 rounded-full px-2 py-1 text-[11px] font-semibold" style={{ backgroundColor: statusConfig.bg, color: statusConfig.color }}>
                                                                        <StatusIcon size={12} />
                                                                        {statusConfig.label}
                                                                    </span>
                                                                    <LevelBadge level={approval.level} />
                                                                </div>
                                                                <p className="text-sm mt-1" style={{ color: '#4B5563' }}>{approval.description}</p>
                                                                <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-xs mt-2" style={{ color: '#6B7280' }}>
                                                                    <span>Due: {new Date(approval.dueDate).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })}</span>
                                                                    <span>{approval.category}</span>
                                                                    <span>{approval.frequency}</span>
                                                                    <span>{formatCurrency(approval.amount)}</span>
                                                                </div>
                                                            </div>
                                                            <button
                                                                onClick={() => setExpandedApprovalId((current) => current === approval._id ? null : approval._id)}
                                                                className="inline-flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium"
                                                                style={{ backgroundColor: '#F8FAFC', color: '#374151' }}
                                                            >
                                                                {approval.status === 'pending' ? 'Review' : 'View'}
                                                                {isExpanded ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
                                                            </button>
                                                        </div>

                                                        {isExpanded && draft && (
                                                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-4 pt-4 border-t" style={{ borderColor: '#E5E7EB' }}>
                                                                <div>
                                                                    <label className="text-sm font-medium mb-1.5 block" style={{ color: '#374151' }}>Paid Date</label>
                                                                    <input
                                                                        type="date"
                                                                        value={draft.paidDate}
                                                                        onChange={(e) => updateApprovalDraft(approval._id, { paidDate: e.target.value })}
                                                                        disabled={approval.status !== 'pending'}
                                                                        className="w-full px-3 py-2 rounded-lg border text-sm disabled:bg-gray-50"
                                                                        style={{ borderColor: '#E5E7EB', color: '#374151' }}
                                                                    />
                                                                </div>
                                                                <div>
                                                                    <label className="text-sm font-medium mb-1.5 block" style={{ color: '#374151' }}>Amount</label>
                                                                    <input
                                                                        type="number"
                                                                        value={draft.amount || ''}
                                                                        onChange={(e) => updateApprovalDraft(approval._id, { amount: parseFloat(e.target.value) || 0 })}
                                                                        disabled={approval.status !== 'pending'}
                                                                        className="w-full px-3 py-2 rounded-lg border text-sm disabled:bg-gray-50"
                                                                        style={{ borderColor: '#E5E7EB', color: '#374151' }}
                                                                    />
                                                                </div>
                                                                <div className="md:col-span-2">
                                                                    <label className="text-sm font-medium mb-1.5 block" style={{ color: '#374151' }}>Description</label>
                                                                    <input
                                                                        type="text"
                                                                        value={draft.description}
                                                                        onChange={(e) => updateApprovalDraft(approval._id, { description: e.target.value })}
                                                                        disabled={approval.status !== 'pending'}
                                                                        className="w-full px-3 py-2 rounded-lg border text-sm disabled:bg-gray-50"
                                                                        style={{ borderColor: '#E5E7EB', color: '#374151' }}
                                                                    />
                                                                </div>
                                                                <div>
                                                                    <label className="text-sm font-medium mb-1.5 block" style={{ color: '#374151' }}>Vendor</label>
                                                                    <input
                                                                        type="text"
                                                                        value={draft.vendor}
                                                                        onChange={(e) => updateApprovalDraft(approval._id, { vendor: e.target.value })}
                                                                        disabled={approval.status !== 'pending'}
                                                                        className="w-full px-3 py-2 rounded-lg border text-sm disabled:bg-gray-50"
                                                                        style={{ borderColor: '#E5E7EB', color: '#374151' }}
                                                                    />
                                                                </div>
                                                                <div>
                                                                    <label className="text-sm font-medium mb-1.5 block" style={{ color: '#374151' }}>Paid By</label>
                                                                    <input
                                                                        type="text"
                                                                        value={draft.paidBy}
                                                                        onChange={(e) => updateApprovalDraft(approval._id, { paidBy: e.target.value })}
                                                                        disabled={approval.status !== 'pending'}
                                                                        className="w-full px-3 py-2 rounded-lg border text-sm disabled:bg-gray-50"
                                                                        style={{ borderColor: '#E5E7EB', color: '#374151' }}
                                                                    />
                                                                </div>
                                                                <div>
                                                                    <label className="text-sm font-medium mb-1.5 block" style={{ color: '#374151' }}>Source</label>
                                                                    <select
                                                                        value={draft.sourceAccountKey}
                                                                        onChange={(e) => updateApprovalDraft(approval._id, { sourceAccountKey: e.target.value as ExpenseSourceAccount | '' })}
                                                                        disabled={approval.status !== 'pending'}
                                                                        className="w-full px-3 py-2 rounded-lg border text-sm disabled:bg-gray-50"
                                                                        style={{ borderColor: '#E5E7EB', color: '#374151' }}
                                                                    >
                                                                        <option value="">Select source</option>
                                                                        {EXPENSE_SOURCE_OPTIONS.map((option) => (
                                                                            <option key={option.value} value={option.value}>{option.label}</option>
                                                                        ))}
                                                                    </select>
                                                                </div>
                                                                <div className="md:col-span-2">
                                                                    <label className="text-sm font-medium mb-1.5 block" style={{ color: '#374151' }}>Expense Notes</label>
                                                                    <textarea
                                                                        rows={2}
                                                                        value={draft.notes}
                                                                        onChange={(e) => updateApprovalDraft(approval._id, { notes: e.target.value })}
                                                                        disabled={approval.status !== 'pending'}
                                                                        className="w-full px-3 py-2 rounded-lg border text-sm resize-none disabled:bg-gray-50"
                                                                        style={{ borderColor: '#E5E7EB', color: '#374151' }}
                                                                    />
                                                                </div>
                                                                <div className="md:col-span-2">
                                                                    <label className="text-sm font-medium mb-1.5 block" style={{ color: '#374151' }}>
                                                                        {approval.status === 'pending' ? 'Approval / Rejection Notes' : 'Decision Notes'}
                                                                    </label>
                                                                    <textarea
                                                                        rows={2}
                                                                        value={draft.responseNotes}
                                                                        onChange={(e) => updateApprovalDraft(approval._id, { responseNotes: e.target.value })}
                                                                        disabled={approval.status !== 'pending'}
                                                                        className="w-full px-3 py-2 rounded-lg border text-sm resize-none disabled:bg-gray-50"
                                                                        style={{ borderColor: '#E5E7EB', color: '#374151' }}
                                                                    />
                                                                </div>
                                                            </div>
                                                        )}

                                                        {isExpanded && approval.status !== 'pending' ? (
                                                            <div className="mt-4 text-xs" style={{ color: '#6B7280' }}>
                                                                {approval.actedAt
                                                                    ? `Decision recorded on ${new Date(approval.actedAt).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })}.`
                                                                    : 'Decision recorded.'}
                                                            </div>
                                                        ) : isExpanded ? (
                                                            <div className="flex flex-wrap items-center justify-end gap-3 mt-4">
                                                                <button
                                                                    onClick={() => handleApprovalAction(approval._id, 'reject')}
                                                                    disabled={isRejectingFixedExpense || isApprovingFixedExpense}
                                                                    className="px-4 py-2 rounded-lg text-sm font-medium disabled:opacity-50"
                                                                    style={{ backgroundColor: '#FEF2F2', color: '#B91C1C' }}
                                                                >
                                                                    Reject
                                                                </button>
                                                                <button
                                                                    onClick={() => handleApprovalAction(approval._id, 'approve')}
                                                                    disabled={isApprovingFixedExpense || isRejectingFixedExpense}
                                                                    className="px-4 py-2 rounded-lg text-sm font-medium text-white disabled:opacity-50"
                                                                    style={{ backgroundColor: '#16A34A' }}
                                                                >
                                                                    Approve and record expense
                                                                </button>
                                                            </div>
                                                        ) : approval.status === 'pending' ? (
                                                            <div className="mt-3 text-xs" style={{ color: '#6B7280' }}>
                                                                Paid date can be edited when you expand this request.
                                                            </div>
                                                        ) : null}
                                                    </div>
                                                );
                                            })
                                        )}
                                    </div>
                                )}
                            </div>
                            {fixedDrawerTab === 'manage' && (
                                <div className="px-5 py-4 border-t" style={{ borderColor: '#E5E7EB', backgroundColor: 'white' }}>
                                    <div className="flex justify-end">
                                        <button
                                            onClick={() => openFixedExpenseForm('new')}
                                            className="inline-flex items-center gap-2 px-4 py-3 rounded-full text-sm font-medium shadow-lg"
                                            style={{ backgroundColor: '#4F46E5', color: '#FFFFFF' }}
                                        >
                                            <Plus size={16} />
                                            Add fixed expense
                                        </button>
                                    </div>
                                </div>
                            )}
                    </div>
                </>,
                document.body
            )}

            {typeof document !== 'undefined' && createPortal(
                <button
                    onClick={openAddModal}
                    className="fixed bottom-6 right-6 flex items-center gap-2 px-4 py-3 rounded-full text-sm font-medium transition-all hover:shadow-lg transform hover:scale-105 z-50"
                    style={{ background: 'var(--color-primary)', color: 'white', boxShadow: '0 4px 12px rgba(0,0,0,0.15)' }}
                >
                    <Plus size={18} />
                    Add Expense
                </button>,
                document.body
            )}
        </div>
    );
}

import { useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import {
    AlertTriangle,
    Calendar,
    Clock3,
    Filter,
    FolderKanban,
    Loader2,
    Receipt,
    Search,
    Wallet,
} from 'lucide-react';
import { useGetRevenuesQuery } from '@/features/finance/api/financeApi';
import { useGetProjectsQuery } from '@/features/project/projectApi';

type ReceivableSource = 'finance-revenue' | 'phase-payment';
type ReceivableStatus = 'pending' | 'partial' | 'overdue';

type ReceivableItem = {
    id: string;
    source: ReceivableSource;
    sourceLabel: string;
    party: string;
    title: string;
    status: ReceivableStatus;
    dueDate: Date | null;
    outstanding: number;
    expected: number;
    received: number;
};

const formatCurrency = (value: number) => new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0,
}).format(value);

const formatCompactCurrency = (value: number) => {
    if (Math.abs(value) >= 10000000) return `₹${(value / 10000000).toFixed(2)} Cr`;
    if (Math.abs(value) >= 100000) return `₹${(value / 100000).toFixed(2)} L`;
    if (Math.abs(value) >= 1000) return `₹${(value / 1000).toFixed(1)} K`;
    return formatCurrency(value);
};

const formatDate = (date: Date | null) => {
    if (!date) return 'No due date';
    return new Intl.DateTimeFormat('en-IN', {
        day: '2-digit',
        month: 'short',
        year: 'numeric',
    }).format(date);
};

const getStartOfDay = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate());
const daysDiff = (from: Date, to: Date) => Math.ceil((to.getTime() - from.getTime()) / (24 * 60 * 60 * 1000));

const getPhaseExpectedAmount = (phase: any, project: any) => {
    if (Number(phase?.paymentAmount || 0) > 0) return Number(phase.paymentAmount || 0);
    if (Number(phase?.paymentPercentage || 0) > 0 && Number(project?.budget || 0) > 0) {
        return (Number(project.budget || 0) * Number(phase.paymentPercentage || 0)) / 100;
    }
    return 0;
};

export default function FinanceReceivablesPage() {
    const [search, setSearch] = useState('');
    const [sourceFilter, setSourceFilter] = useState<'all' | ReceivableSource>('all');
    const [statusFilter, setStatusFilter] = useState<'all' | 'due' | 'overdue'>('all');

    const { data: revenuesData, isLoading: revenuesLoading } = useGetRevenuesQuery({
        page: 1,
        limit: 1000,
    });
    const { data: projectsData, isLoading: projectsLoading } = useGetProjectsQuery({});

    const receivables = useMemo(() => {
        const today = getStartOfDay(new Date());
        const openRevenues = (revenuesData?.data?.revenues || [])
            .filter((item: any) => ['pending', 'partial', 'overdue'].includes(String(item?.status || '').toLowerCase()))
            .map((item: any): ReceivableItem | null => {
                const expected = Number(item?.totalAmount || item?.amountINR || item?.amount || 0);
                const received = Number(item?.receivedAmount || 0);
                const outstanding = Math.max(0, expected - received);
                if (outstanding <= 0) return null;

                const dueDate = item?.dueDate ? getStartOfDay(new Date(item.dueDate)) : null;
                const status: ReceivableStatus = dueDate && dueDate < today
                    ? 'overdue'
                    : (String(item?.status || 'pending').toLowerCase() === 'partial' ? 'partial' : 'pending');

                return {
                    id: String(item?._id || ''),
                    source: 'finance-revenue',
                    sourceLabel: 'Finance Revenue',
                    party: String(item?.client || 'Unknown client'),
                    title: String(item?.description || item?.invoiceNumber || 'Receivable'),
                    status,
                    dueDate,
                    outstanding,
                    expected,
                    received,
                };
            })
            .filter((item: ReceivableItem | null): item is ReceivableItem => Boolean(item));

        const phaseReceivables = (projectsData?.data || []).flatMap((project: any) => {
            const phases = project?.phases || [];
            return phases
                .filter((phase: any) => phase?.hasPayment)
                .map((phase: any, index: number): ReceivableItem | null => {
                    const expected = getPhaseExpectedAmount(phase, project);
                    const received = Number(phase?.paymentReceivedAmount || 0);
                    const outstanding = Math.max(0, expected - received);
                    const statusRaw = String(phase?.paymentStatus || 'pending').toLowerCase();

                    if (outstanding <= 0 || !['pending', 'partial'].includes(statusRaw)) {
                        return null;
                    }

                    const dueDateRaw = phase?.paymentDueDate || phase?.endDate || null;
                    const dueDate = dueDateRaw ? getStartOfDay(new Date(dueDateRaw)) : null;
                    const status: ReceivableStatus = dueDate && dueDate < today
                        ? 'overdue'
                        : (statusRaw === 'partial' ? 'partial' : 'pending');

                    return {
                        id: `${String(project?._id || 'project')}-${String(phase?._id || index)}`,
                        source: 'phase-payment',
                        sourceLabel: 'Project Phase',
                        party: String(project?.name || 'Project'),
                        title: `Phase: ${String(phase?.name || 'Unnamed')}`,
                        status,
                        dueDate,
                        outstanding,
                        expected,
                        received,
                    };
                })
                .filter((item: ReceivableItem | null): item is ReceivableItem => Boolean(item));
        });

        return [...openRevenues, ...phaseReceivables].sort((a, b) => {
            if (!a.dueDate && !b.dueDate) return 0;
            if (!a.dueDate) return 1;
            if (!b.dueDate) return -1;
            return a.dueDate.getTime() - b.dueDate.getTime();
        });
    }, [projectsData, revenuesData]);

    const filteredItems = useMemo(() => {
        const today = getStartOfDay(new Date());

        return receivables.filter((item) => {
            if (sourceFilter !== 'all' && item.source !== sourceFilter) return false;
            if (statusFilter === 'overdue' && !(item.dueDate && item.dueDate < today)) return false;
            if (statusFilter === 'due' && item.dueDate && item.dueDate < today) return false;

            const q = search.trim().toLowerCase();
            if (!q) return true;
            return [item.party, item.title, item.sourceLabel]
                .join(' ')
                .toLowerCase()
                .includes(q);
        });
    }, [receivables, search, sourceFilter, statusFilter]);

    const stats = useMemo(() => {
        const today = getStartOfDay(new Date());
        const totalOpen = receivables.reduce((acc, item) => acc + item.outstanding, 0);
        const overdueAmount = receivables
            .filter((item) => item.dueDate && item.dueDate < today)
            .reduce((acc, item) => acc + item.outstanding, 0);
        const dueSoonAmount = receivables
            .filter((item) => {
                if (!item.dueDate) return false;
                const d = daysDiff(today, item.dueDate);
                return d >= 0 && d <= 7;
            })
            .reduce((acc, item) => acc + item.outstanding, 0);
        const phaseAmount = receivables
            .filter((item) => item.source === 'phase-payment')
            .reduce((acc, item) => acc + item.outstanding, 0);

        return { totalOpen, overdueAmount, dueSoonAmount, phaseAmount };
    }, [receivables]);

    const isLoading = revenuesLoading || projectsLoading;

    return (
        <div className="space-y-6 pb-12">
            <div className="flex items-center gap-2 text-sm" style={{ color: 'var(--color-text-muted)' }}>
                <Link to="/finance" className="transition-colors hover:underline" style={{ color: 'var(--color-text-muted)' }}>
                    Finance Dashboard
                </Link>
                <span>{'>'}</span>
                <span style={{ color: 'var(--color-text-primary)', fontWeight: 500 }}>Receivables</span>
            </div>

            <div>
                <h1 className="text-2xl font-bold" style={{ color: 'var(--color-text-primary)' }}>Receivables Audit</h1>
                <p className="mt-1 text-sm" style={{ color: 'var(--color-text-muted)' }}>
                    Unified view of pending finance invoices and project phase-wise due pipeline.
                </p>
            </div>

            <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
                {[
                    { label: 'Total Open Receivables', value: stats.totalOpen, icon: Wallet, color: '#0EA5E9', bg: '#F0F9FF' },
                    { label: 'Overdue Amount', value: stats.overdueAmount, icon: AlertTriangle, color: '#DC2626', bg: '#FEF2F2' },
                    { label: 'Due in 7 Days', value: stats.dueSoonAmount, icon: Clock3, color: '#F59E0B', bg: '#FFFBEB' },
                    { label: 'Phase-wise Pipeline', value: stats.phaseAmount, icon: FolderKanban, color: '#16A34A', bg: '#F0FDF4' },
                ].map((card) => (
                    <div key={card.label} className="rounded-xl border p-4" style={{ backgroundColor: 'white', borderColor: 'var(--color-border-default)' }}>
                        <div className="mb-3 flex items-center justify-between">
                            <div className="flex h-10 w-10 items-center justify-center rounded-lg" style={{ backgroundColor: card.bg }}>
                                <card.icon size={20} style={{ color: card.color }} />
                            </div>
                        </div>
                        <p className="text-xs font-medium uppercase tracking-[0.14em]" style={{ color: 'var(--color-text-muted)' }}>{card.label}</p>
                        <p className="mt-2 text-2xl font-bold" style={{ color: 'var(--color-text-primary)' }}>{formatCompactCurrency(card.value)}</p>
                        <p className="mt-1 text-xs" style={{ color: 'var(--color-text-muted)' }}>{formatCurrency(card.value)}</p>
                    </div>
                ))}
            </div>

            <div className="rounded-xl border p-4" style={{ backgroundColor: 'white', borderColor: 'var(--color-border-default)' }}>
                <div className="grid grid-cols-1 gap-3 lg:grid-cols-4">
                    <div className="relative lg:col-span-2">
                        <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2" style={{ color: '#9CA3AF' }} />
                        <input
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                            placeholder="Search by project, client, or title"
                            className="w-full rounded-xl border py-2.5 pl-9 pr-3 text-sm"
                            style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'white', color: 'var(--color-text-primary)' }}
                        />
                    </div>
                    <div className="relative">
                        <Filter size={16} className="absolute left-3 top-1/2 -translate-y-1/2" style={{ color: '#9CA3AF' }} />
                        <select
                            value={sourceFilter}
                            onChange={(e) => setSourceFilter(e.target.value as 'all' | ReceivableSource)}
                            className="w-full rounded-xl border py-2.5 pl-9 pr-3 text-sm"
                            style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'white', color: 'var(--color-text-primary)' }}
                        >
                            <option value="all">All Sources</option>
                            <option value="finance-revenue">Finance Revenue</option>
                            <option value="phase-payment">Project Phase</option>
                        </select>
                    </div>
                    <div className="relative">
                        <Calendar size={16} className="absolute left-3 top-1/2 -translate-y-1/2" style={{ color: '#9CA3AF' }} />
                        <select
                            value={statusFilter}
                            onChange={(e) => setStatusFilter(e.target.value as 'all' | 'due' | 'overdue')}
                            className="w-full rounded-xl border py-2.5 pl-9 pr-3 text-sm"
                            style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'white', color: 'var(--color-text-primary)' }}
                        >
                            <option value="all">All Dates</option>
                            <option value="due">Not Overdue</option>
                            <option value="overdue">Overdue Only</option>
                        </select>
                    </div>
                </div>
            </div>

            <div className="rounded-xl border overflow-hidden" style={{ backgroundColor: 'white', borderColor: 'var(--color-border-default)' }}>
                <div className="px-5 py-4 border-b" style={{ borderColor: 'var(--color-border-default)' }}>
                    <h2 className="text-base font-semibold" style={{ color: 'var(--color-text-primary)' }}>
                        Pending Receivables Detail ({filteredItems.length})
                    </h2>
                </div>

                {isLoading ? (
                    <div className="flex items-center justify-center py-16">
                        <Loader2 size={28} className="animate-spin" style={{ color: 'var(--color-primary)' }} />
                    </div>
                ) : filteredItems.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-16">
                        <Receipt size={48} className="mb-3" style={{ color: 'var(--color-text-muted)' }} />
                        <p className="text-sm" style={{ color: 'var(--color-text-muted)' }}>No receivables found for selected filters.</p>
                    </div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="w-full min-w-[980px]">
                            <thead>
                                <tr style={{ backgroundColor: '#F9FAFB' }}>
                                    <th className="text-left px-5 py-3 text-xs font-semibold uppercase tracking-wider" style={{ color: '#6B7280' }}>Source</th>
                                    <th className="text-left px-5 py-3 text-xs font-semibold uppercase tracking-wider" style={{ color: '#6B7280' }}>Party</th>
                                    <th className="text-left px-5 py-3 text-xs font-semibold uppercase tracking-wider" style={{ color: '#6B7280' }}>Item</th>
                                    <th className="text-left px-5 py-3 text-xs font-semibold uppercase tracking-wider" style={{ color: '#6B7280' }}>Due Date</th>
                                    <th className="text-right px-5 py-3 text-xs font-semibold uppercase tracking-wider" style={{ color: '#6B7280' }}>Expected</th>
                                    <th className="text-right px-5 py-3 text-xs font-semibold uppercase tracking-wider" style={{ color: '#6B7280' }}>Received</th>
                                    <th className="text-right px-5 py-3 text-xs font-semibold uppercase tracking-wider" style={{ color: '#6B7280' }}>Outstanding</th>
                                    <th className="text-center px-5 py-3 text-xs font-semibold uppercase tracking-wider" style={{ color: '#6B7280' }}>Status</th>
                                </tr>
                            </thead>
                            <tbody>
                                {filteredItems.map((item, index) => {
                                    const overdue = item.status === 'overdue';
                                    const dueSoon = item.dueDate ? daysDiff(getStartOfDay(new Date()), item.dueDate) <= 7 && daysDiff(getStartOfDay(new Date()), item.dueDate) >= 0 : false;
                                    return (
                                        <tr
                                            key={item.id}
                                            className="transition-colors hover:bg-gray-50"
                                            style={{ borderTop: index > 0 ? '1px solid #E5E7EB' : undefined }}
                                        >
                                            <td className="px-5 py-3 text-sm" style={{ color: '#111827' }}>
                                                <span
                                                    className="inline-flex items-center rounded-full px-2.5 py-1 text-xs font-medium"
                                                    style={{
                                                        backgroundColor: item.source === 'phase-payment' ? '#ECFDF5' : '#EEF2FF',
                                                        color: item.source === 'phase-payment' ? '#166534' : '#3730A3',
                                                    }}
                                                >
                                                    {item.sourceLabel}
                                                </span>
                                            </td>
                                            <td className="px-5 py-3 text-sm font-medium" style={{ color: '#111827' }}>{item.party}</td>
                                            <td className="px-5 py-3 text-sm" style={{ color: '#374151' }}>{item.title}</td>
                                            <td className="px-5 py-3 text-sm" style={{ color: '#374151' }}>{formatDate(item.dueDate)}</td>
                                            <td className="px-5 py-3 text-sm text-right" style={{ color: '#6B7280' }}>{formatCurrency(item.expected)}</td>
                                            <td className="px-5 py-3 text-sm text-right" style={{ color: '#6B7280' }}>{formatCurrency(item.received)}</td>
                                            <td className="px-5 py-3 text-sm text-right font-semibold" style={{ color: overdue ? '#DC2626' : '#111827' }}>{formatCurrency(item.outstanding)}</td>
                                            <td className="px-5 py-3 text-sm text-center">
                                                <span
                                                    className="inline-flex items-center rounded-full px-2.5 py-1 text-xs font-medium"
                                                    style={{
                                                        backgroundColor: overdue ? '#FEF2F2' : (dueSoon ? '#FFFBEB' : '#F0FDF4'),
                                                        color: overdue ? '#B91C1C' : (dueSoon ? '#B45309' : '#166534'),
                                                    }}
                                                >
                                                    {overdue ? 'Overdue' : dueSoon ? 'Due Soon' : item.status === 'partial' ? 'Partial' : 'Pending'}
                                                </span>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>
        </div>
    );
}

import { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import {
    TrendingUp, IndianRupee, Clock, Receipt, Plus, X,
    Search, Calendar, Building2, Edit2, Trash2,
    Check, AlertCircle, Loader2, Globe,
} from 'lucide-react';
import {
    useGetRevenuesQuery,
    useCreateRevenueMutation,
    useUpdateRevenueMutation,
    useDeleteRevenueMutation,
} from '@/features/finance/api/financeApi';
import ModalPortal from '@/components/ui/ModalPortal';

// ── Types ─────────────────────────────────────────────────────────────────
type RevenueSource = 'manual' | 'invoice' | 'project';
type RevenueStatus = 'received' | 'pending' | 'partial' | 'overdue';
type Currency = 'INR' | 'USD' | 'EUR' | 'GBP' | 'AED';

interface RevenueFormData {
    date: string;
    description: string;
    client: string;
    project?: string;
    amount: number;
    currency: Currency;
    exchangeRate: number;
    amountINR: number;
    gstApplicable: boolean;
    gstRate: number;
    gst: number;
    tdsDeducted: number;
    totalAmount: number;
    receivedAmount: number;
    source: RevenueSource;
    status: RevenueStatus;
    invoiceNumber?: string;
    dueDate?: string;
    notes?: string;
}

// ── Currency Config ───────────────────────────────────────────────────────
const CURRENCIES: { code: Currency; symbol: string; name: string }[] = [
    { code: 'INR', symbol: '₹', name: 'Indian Rupee' },
    { code: 'USD', symbol: '$', name: 'US Dollar' },
    { code: 'EUR', symbol: '€', name: 'Euro' },
    { code: 'GBP', symbol: '£', name: 'British Pound' },
    { code: 'AED', symbol: 'د.إ', name: 'UAE Dirham' },
];

// ── Format Currency ───────────────────────────────────────────────────────
const formatCurrency = (value: number, currency: Currency = 'INR') => {
    return new Intl.NumberFormat('en-IN', {
        style: 'currency',
        currency: currency,
        maximumFractionDigits: 0,
    }).format(value);
};

const formatShortCurrency = (value: number) => {
    if (value >= 10000000) return `₹${(value / 10000000).toFixed(2)} Cr`;
    if (value >= 100000) return `₹${(value / 100000).toFixed(2)} L`;
    if (value >= 1000) return `₹${(value / 1000).toFixed(1)} K`;
    return formatCurrency(value);
};

// ── Status Badge Component ────────────────────────────────────────────────
const StatusBadge = ({ status }: { status: RevenueStatus }) => {
    const config = {
        received: { label: 'Received', color: '#22C55E', bg: '#F0FDF4', icon: Check },
        pending: { label: 'Pending', color: '#F59E0B', bg: '#FFFBEB', icon: Clock },
        partial: { label: 'Partial', color: '#6366F1', bg: '#EEF2FF', icon: AlertCircle },
        overdue: { label: 'Overdue', color: '#EF4444', bg: '#FEF2F2', icon: AlertCircle },
    };
    const { label, color, bg, icon: Icon } = config[status];

    return (
        <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium" style={{ background: bg, color }}>
            <Icon size={12} />
            {label}
        </span>
    );
};

// ── Source Badge Component ────────────────────────────────────────────────
const SourceBadge = ({ source }: { source: RevenueSource }) => {
    const config = {
        manual: { label: 'Manual', color: '#8B5CF6', bg: '#F5F3FF' },
        invoice: { label: 'Invoice', color: '#0EA5E9', bg: '#F0F9FF' },
        project: { label: 'Project', color: '#10B981', bg: '#ECFDF5' },
    };
    const { label, color, bg } = config[source];

    return (
        <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium" style={{ background: bg, color }}>
            {label}
        </span>
    );
};

// ── Empty State Component ─────────────────────────────────────────────────
const EmptyState = () => (
    <div className="text-center py-12">
        <Receipt size={48} className="mx-auto mb-3" style={{ color: '#9CA3AF' }} />
        <p className="text-sm" style={{ color: '#6B7280' }}>No revenue entries found</p>
        <p className="text-xs mt-1" style={{ color: '#9CA3AF' }}>Add your first revenue entry to get started</p>
    </div>
);

export default function FinanceRevenuePage() {
    const [showAddModal, setShowAddModal] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [searchQuery, setSearchQuery] = useState('');
    const [filterStatus, setFilterStatus] = useState<RevenueStatus | 'all'>('all');
    const [filterSource, setFilterSource] = useState<RevenueSource | 'all'>('all');

    const initialFormData: RevenueFormData = {
        date: new Date().toISOString().split('T')[0],
        description: '',
        client: '',
        project: '',
        amount: 0,
        currency: 'INR',
        exchangeRate: 1,
        amountINR: 0,
        gstApplicable: true,
        gstRate: 18,
        gst: 0,
        tdsDeducted: 0,
        totalAmount: 0,
        receivedAmount: 0,
        source: 'manual',
        status: 'pending',
        invoiceNumber: '',
        dueDate: '',
        notes: '',
    };

    const [formData, setFormData] = useState<RevenueFormData>(initialFormData);

    // API Hooks
    const { data: revenuesData, isLoading } = useGetRevenuesQuery({
        status: filterStatus !== 'all' ? filterStatus : undefined,
        source: filterSource !== 'all' ? filterSource : undefined,
        search: searchQuery || undefined,
    });
    const [createRevenue, { isLoading: isCreating }] = useCreateRevenueMutation();
    const [updateRevenue, { isLoading: isUpdating }] = useUpdateRevenueMutation();
    const [deleteRevenue] = useDeleteRevenueMutation();

    const revenues = revenuesData?.data?.revenues || [];

    // Calculate metrics from actual data
    const metrics = {
        totalRevenue: revenues.reduce((acc: number, e: any) => acc + (e.amountINR || e.amount || 0), 0),
        received: revenues.reduce((acc: number, e: any) => acc + (e.receivedAmount || 0), 0),
        pending: revenues.reduce((acc: number, e: any) => {
            const total = e.amountINR || e.amount || 0;
            const received = e.receivedAmount || 0;
            return acc + (total - received);
        }, 0),
        gstCollected: revenues
            .filter((e: any) => e.status === 'received')
            .reduce((acc: number, e: any) => acc + (e.gst || 0), 0),
    };

    const metricCards = [
        { label: 'Total Revenue', value: formatShortCurrency(metrics.totalRevenue), fullValue: formatCurrency(metrics.totalRevenue), icon: TrendingUp, color: '#22C55E', bg: '#F0FDF4' },
        { label: 'Received', value: formatShortCurrency(metrics.received), fullValue: formatCurrency(metrics.received), icon: IndianRupee, color: '#6366F1', bg: '#EEF2FF' },
        { label: 'Pending', value: formatShortCurrency(metrics.pending), fullValue: formatCurrency(metrics.pending), icon: Clock, color: '#F59E0B', bg: '#FFFBEB' },
        { label: 'GST Collected', value: formatShortCurrency(metrics.gstCollected), fullValue: formatCurrency(metrics.gstCollected), icon: Receipt, color: '#0EA5E9', bg: '#F0F9FF' },
    ];

    // Auto-calculate amounts when form data changes
    useEffect(() => {
        const amountINR = formData.currency === 'INR' ? formData.amount : formData.amount * formData.exchangeRate;
        const gst = formData.gstApplicable ? (amountINR * formData.gstRate) / 100 : 0;
        const totalAmount = amountINR + gst - formData.tdsDeducted;

        setFormData(prev => ({
            ...prev,
            amountINR,
            gst,
            totalAmount,
        }));
    }, [formData.amount, formData.currency, formData.exchangeRate, formData.gstApplicable, formData.gstRate, formData.tdsDeducted]);

    const handleSubmit = async () => {
        try {
            if (editingId) {
                await updateRevenue({ id: editingId, ...formData }).unwrap();
            } else {
                await createRevenue(formData).unwrap();
            }
            setShowAddModal(false);
            setEditingId(null);
            setFormData(initialFormData);
        } catch (error) {
            console.error('Failed to save revenue:', error);
        }
    };

    const handleEdit = (entry: any) => {
        setFormData({
            ...initialFormData,
            ...entry,
            date: entry.date?.split('T')[0] || new Date().toISOString().split('T')[0],
            dueDate: entry.dueDate?.split('T')[0] || '',
        });
        setEditingId(entry._id);
        setShowAddModal(true);
    };

    const handleDelete = async (id: string) => {
        if (window.confirm('Are you sure you want to delete this revenue entry?')) {
            try {
                await deleteRevenue(id).unwrap();
            } catch (error) {
                console.error('Failed to delete revenue:', error);
            }
        }
    };

    const openAddModal = () => {
        setFormData(initialFormData);
        setEditingId(null);
        setShowAddModal(true);
    };

    return (
        <div className="space-y-6">
            {/* ── Header ──────────────────────────────────────────────────── */}
