                                    <label className="text-sm font-medium mb-1.5 block" style={{ color: '#374151' }}>Project (Optional)</label>
                                    <input
                                        type="text"
                                        placeholder="Enter project name"
                                        value={formData.project}
                                        onChange={(e) => setFormData({ ...formData, project: e.target.value })}
