                            >
                                {isUpdatingPayroll ? <Loader2 size={15} className="animate-spin" /> : <Briefcase size={15} />}
                                Save Payroll Changes
                            </button>
                        </form>
                    </div>
                </ModalPortal>
            )}
        </div>
    );
}

