    }, [copySourceJob]);

    useEffect(() => {
        if (!isJobCopyModalOpen) {
            return;
        }

        const hasValidSelection = sourceJobs.some((job) => job._id === copySourceJobId);
        if (hasValidSelection) {
            return;
