                            style={inputStyle}
                        />
                    </Field>

                    <Field label="Help Text">
                        <input
                            type="text"
                            value={newField.helpText}
                            onChange={(e) =>
                                setNewField((prev) => ({ ...prev, helpText: e.target.value }))
