                            <option key={t} value={t}>
                                {EMPLOYMENT_TYPE_LABELS[t]}
                            </option>
                        ))}
                    </select>

                    {/* Clear filters */}
                    {(search || filterDept || filterType) && (
                        <button
                            onClick={() => {
                                setSearch('');
                                setFilterDept('');
                                setFilterType('');
