                                                    <Clock size={11} />
                                                    {EMPLOYMENT_TYPE_LABELS[job.employmentType]}
                                                </span>
                                            </td>

                                            {/* Hiring toggle */}
                                            <td className="px-4 py-4">
                                                {canManage ? (
                                                    <button
                                                        onClick={() => handleToggle(job._id)}
                                                        className="flex items-center gap-2 text-xs font-medium transition-colors"
                                                        title={
