                                                        Disabled
                                                    </span>
                                                ) : (
                                                    <div className="flex flex-col gap-1">
                                                        <span
                                                            className="text-xs font-medium"
                                                            style={{
                                                                color:
                                                                    job.interviewScheduling.syncStatus === 'synced'
                                                                        ? 'var(--color-success)'
                                                                        : job.interviewScheduling.syncStatus ===
                                                                          'failed'
                                                                        ? 'var(--color-danger)'
                                                                        : 'var(--color-text-secondary)',
                                                            }}
                                                        >
                                                            {job.interviewScheduling.syncStatus}
                                                        </span>
                                                        <span
                                                            className="text-[11px]"
                                                            style={{ color: 'var(--color-text-muted)' }}
