                                                    </div>
                                                )}
                                            </td>

                                            {/* Date */}
                                            <td
                                                className="px-4 py-4 text-sm"
                                                style={{ color: 'var(--color-text-secondary)' }}
                                            >
                                                {formatDate(job.createdAt)}
                                            </td>

                                            {/* Actions */}
                                            {canManage && (
                                                <td className="px-4 py-4 text-right">
                                                    <div
                                                        className="relative inline-block"
                                                        ref={(el) => {
                                                            menuRefs.current[job._id] = el;
                                                        }}
                                                    >
                                                        <button
                                                            onClick={() =>
                                                                setOpenMenuId(
                                                                    openMenuId === job._id
                                                                        ? null
                                                                        : job._id
                                                                )
                                                            }
                                                            className="p-1.5 rounded-md transition-colors"
                                                            style={{
                                                                color: 'var(--color-text-muted)',
                                                            }}
                                                            onMouseEnter={(e) => {
                                                                e.currentTarget.style.backgroundColor =
                                                                    'var(--color-bg-subtle)';
                                                                e.currentTarget.style.color =
                                                                    'var(--color-text-primary)';
                                                            }}
                                                            onMouseLeave={(e) => {
                                                                e.currentTarget.style.backgroundColor =
                                                                    'transparent';
                                                                e.currentTarget.style.color =
                                                                    'var(--color-text-muted)';
                                                            }}
                                                        >
                                                            <MoreVertical size={16} />
                                                        </button>

                                                        {openMenuId === job._id && (
                                                            <div
                                                                className="absolute right-0 top-8 w-44 rounded-lg shadow-lg z-20 overflow-hidden"
                                                                style={{
                                                                    backgroundColor:
                                                                        'var(--color-bg-surface)',
                                                                    border: '1px solid var(--color-border-default)',
                                                                }}
                                                            >
                                                                {job.isHiring && (
                                                                    <button
                                                                        onClick={() => {
                                                                            navigator.clipboard.writeText(
                                                                                window.location.origin + '/apply/' + job._id
                                                                            );
                                                                            setOpenMenuId(null);
                                                                            setCopiedId(job._id);
                                                                            setTimeout(() => setCopiedId(null), 2000);
                                                                        }}
                                                                        className="flex items-center gap-2 w-full px-3 py-2 text-sm transition-colors"
                                                                        style={{
                                                                            color: 'var(--color-primary)',
                                                                        }}
                                                                        onMouseEnter={(e) => {
                                                                            e.currentTarget.style.backgroundColor =
                                                                                'var(--color-primary-soft)';
                                                                        }}
                                                                        onMouseLeave={(e) => {
                                                                            e.currentTarget.style.backgroundColor =
                                                                                'transparent';
                                                                        }}
                                                                    >
                                                                        <Link size={14} />
                                                                        Copy Apply Link
                                                                    </button>
                                                                )}
                                                                <button
                                                                    onClick={() => {
                                                                        setOpenMenuId(null);
                                                                        navigate(
                                                                            `/hiring/jobs/${job._id}/edit`
                                                                        );
                                                                    }}
                                                                    className="flex items-center gap-2 w-full px-3 py-2 text-sm transition-colors"
                                                                    style={{
                                                                        color: 'var(--color-text-primary)',
                                                                    }}
                                                                    onMouseEnter={(e) => {
                                                                        e.currentTarget.style.backgroundColor =
                                                                            'var(--color-bg-subtle)';
                                                                    }}
                                                                    onMouseLeave={(e) => {
                                                                        e.currentTarget.style.backgroundColor =
                                                                            'transparent';
                                                                    }}
                                                                >
                                                                    <Pencil size={14} />
                                                                    Edit
                                                                </button>
                                                                <button
                                                                    onClick={() => {
                                                                        setOpenMenuId(null);
                                                                        setDeleteError('');
                                                                        setDeleteConfirm({
                                                                            id: job._id,
                                                                            title: job.title,
                                                                        });
                                                                    }}
                                                                    className="flex items-center gap-2 w-full px-3 py-2 text-sm transition-colors"
                                                                    style={{
                                                                        color: 'var(--color-danger)',
                                                                    }}
                                                                    onMouseEnter={(e) => {
                                                                        e.currentTarget.style.backgroundColor =
                                                                            'var(--color-danger-soft)';
                                                                    }}
                                                                    onMouseLeave={(e) => {
                                                                        e.currentTarget.style.backgroundColor =
                                                                            'transparent';
                                                                    }}
                                                                >
                                                                    <Trash2 size={14} />
                                                                    Delete
                                                                </button>
                                                            </div>
                                                        )}
                                                    </div>
                                                </td>
                                            )}
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    )}
                </div>
            </div>

            {/* ── Delete Confirmation Modal ─────────────── */}
            {deleteConfirm && (
                <div className="fixed inset-0 z-50 flex items-center justify-center">
                    {/* Backdrop */}
                    <div
                        className="absolute inset-0"
                        style={{ backgroundColor: 'rgba(0,0,0,0.4)' }}
                        onClick={() => setDeleteConfirm(null)}
                    />
                    {/* Modal */}
                    <div
                        className="relative z-10 w-full max-w-sm rounded-xl p-6 shadow-xl"
                        style={{
                            backgroundColor: 'var(--color-bg-surface)',
                            border: '1px solid var(--color-border-default)',
                        }}
                    >
                        <h3
                            className="text-base font-semibold mb-2"
                            style={{ color: 'var(--color-text-primary)' }}
                        >
                            Delete Job Posting
                        </h3>
                        <p
                            className="text-sm mb-6"
                            style={{ color: 'var(--color-text-secondary)' }}
                        >
                            Are you sure you want to delete{' '}
                            <span
                                className="font-medium"
                                style={{ color: 'var(--color-text-primary)' }}
                            >
                                {deleteConfirm.title}
                            </span>
                            ? This action cannot be undone.
                        </p>
                        <div className="flex justify-end gap-3">
                            <button
                                onClick={() => setDeleteConfirm(null)}
                                className="px-4 py-2 text-sm rounded-lg border"
                                style={{
                                    borderColor: 'var(--color-border-default)',
                                    color: 'var(--color-text-secondary)',
                                }}
                            >
                                Cancel
                            </button>
                            <button
                                onClick={handleDelete}
                                disabled={isDeleting}
                                className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-white rounded-lg"
                                style={{ backgroundColor: 'var(--color-danger)' }}
                            >
                                {isDeleting && (
                                    <Loader2 size={14} className="animate-spin" />
                                )}
                                Delete
                            </button>
                        </div>
                        {deleteError && (
                            <p className="text-xs mt-3" style={{ color: 'var(--color-danger)' }}>
                                {deleteError}
                            </p>
                        )}
                    </div>
                </div>
            )}

            {/* ── Copied toast ─────────────────────────── */}
            {copiedId && typeof document !== 'undefined' && createPortal(
                <div
                    className="fixed bottom-6 left-1/2 -translate-x-1/2 flex items-center gap-2 px-4 py-2.5 rounded-lg shadow-lg text-sm font-medium text-white z-50 pointer-events-none"
                    style={{ backgroundColor: 'var(--color-primary)' }}
                >
                    <Link size={14} />
                    Application link copied!
                </div>,
                document.body
            )}
        </>
    );
}

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { AlertCircle, Loader2, RefreshCw } from 'lucide-react';
import { useGetHiringReportSummaryQuery } from '@/features/hiring/hiringApi';
import type { ApplicationStatus } from '@/features/hiring/types/types';

const STATUS_LABELS: Record<ApplicationStatus, string> = {
    new: 'New',
    screening: 'Screening',
    shortlisted: 'Shortlisted',
    'assignment-round': 'Assignment',
    'assignment-submitted': 'Assignment Submitted',
    interview: 'Interview',
    'interview-scheduled': 'Interview Scheduled',
    'interview-rescheduled': 'Interview Rescheduled',
    'interview-cancelled': 'Interview Cancelled',
    offered: 'Offered',
    hired: 'Hired',
    rejected: 'Rejected',
};

function toPercent(value: number | null): string {
    if (value === null || Number.isNaN(value)) {
        return '-';
    }
    return `${value.toFixed(1)}%`;
}

export default function HiringReportsPage() {
    const navigate = useNavigate();
    const [lastDays, setLastDays] = useState(30);

    const { data, isLoading, error, refetch, isFetching } = useGetHiringReportSummaryQuery({
        lastDays,
    });

    if (isLoading) {
        return (
            <div
                className="flex items-center justify-center h-[calc(100vh-64px)]"
                style={{ backgroundColor: 'var(--color-bg-app)' }}
            >
                <div className="flex items-center gap-2 text-sm" style={{ color: 'var(--color-text-secondary)' }}>
                    <Loader2 size={18} className="animate-spin" />
                    Loading hiring analytics...
                </div>
            </div>
        );
    }

    if (error || !data?.data) {
        return (
            <div
                className="flex items-center justify-center h-[calc(100vh-64px)]"
                style={{ backgroundColor: 'var(--color-bg-app)' }}
            >
                <div className="flex items-center gap-2 text-sm" style={{ color: 'var(--color-danger)' }}>
                    <AlertCircle size={18} />
                    Unable to load hiring analytics.
                </div>
            </div>
        );
    }

    const report = data.data;

    return (
        <div
            className="px-8 py-6 max-w-[1280px] mx-auto"
            style={{ backgroundColor: 'var(--color-bg-app)', minHeight: '100vh' }}
        >
            <div className="flex items-center justify-between mb-6">
                <div>
                    <h1 className="text-2xl font-semibold" style={{ color: 'var(--color-text-primary)' }}>
                        Hiring Analytics
                    </h1>
                    <p className="text-sm mt-1" style={{ color: 'var(--color-text-secondary)' }}>
                        Pipeline conversion, stage aging, and recruiter performance overview
                    </p>
                </div>
                <div className="flex items-center gap-2">
                    <select
                        value={lastDays}
                        onChange={(event) => setLastDays(Number(event.target.value))}
