import { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useCreateEmployeeMutation, useUpdateEmployeeMutation, useGetEmployeeQuery, useGetEmployeesQuery } from '@/features/hrms/hrmsApi';
import { useGetUsersQuery } from '@/features/auth/authApi';
import { useGetOrgSettingsQuery } from '@/features/overall-admin/api/adminApi';
import { ArrowLeft, Save, Loader2, UserPlus } from 'lucide-react';
import { dedupeDepartments, resolveDepartmentValue, DEFAULT_DEPARTMENTS } from '@/utils/department';
const EMPLOYMENT_TYPES = ['full-time', 'part-time', 'contract', 'intern'];

const DEFAULT_ONBOARDING_CHECKLIST = [
    'Welcome orientation completed',
    'IT setup (laptop, email, accounts)',
    'HR documentation submitted',
    'Team introduction done',
    'First week goals assigned',
    'Probation terms explained',
];

export default function HrmsEmployeeFormPage() {
    const navigate = useNavigate();
    const { id } = useParams();
    const isEdit = Boolean(id);

    const { data: existingData } = useGetEmployeeQuery(id!, { skip: !isEdit });
    const { data: usersData } = useGetUsersQuery();
    const { data: employeesData } = useGetEmployeesQuery({ limit: 100 });
    const { data: orgSettingsData } = useGetOrgSettingsQuery();
    const [createEmployee, { isLoading: isCreating }] = useCreateEmployeeMutation();
    const [updateEmployee, { isLoading: isUpdating }] = useUpdateEmployeeMutation();

    const users = usersData?.data?.users || usersData?.data || [];
    const existingEmployees = employeesData?.data?.employees || [];
    const internalUsers = Array.isArray(users)
        ? users.filter((u: any) => {
            const roleName = typeof u?.role === 'object' ? String(u.role?.name || '') : String(u?.role || '');
            return roleName.toLowerCase() !== 'partner';
        })
        : [];
    // Users that don't already have an employee record
    const availableUsers = Array.isArray(internalUsers)
        ? internalUsers.filter((u: any) => !existingEmployees.some((e: any) => (e.userId?._id || e.userId) === u._id))
        : [];
    const [form, setForm] = useState({
        userId: '',
        employeeId: '',
        designation: '',
        department: '',
        employmentType: 'full-time',
        joiningDate: new Date().toISOString().split('T')[0],
        probationEndDate: '',
        status: 'active',
        reportingTo: '',
        paidLeavesPerYear: 12,
        workSchedule: { workingDaysPerWeek: 5, hoursPerDay: 8 },
    });

const [autoFilledDept, setAutoFilledDept] = useState(false);
    const [errorMsg, setErrorMsg] = useState('');
    const configuredDepartments = orgSettingsData?.data?.departments?.length
        ? dedupeDepartments(orgSettingsData.data.departments)
        : DEFAULT_DEPARTMENTS;
    const departmentOptions = form.department && !configuredDepartments.includes(form.department)
        ? [form.department, ...configuredDepartments]
        : configuredDepartments;

    useEffect(() => {
        if (existingData?.data?.employee) {
            const emp = existingData.data.employee;
            setForm({
                userId: (emp.userId as any)?._id || '',
                employeeId: emp.employeeId,
                designation: emp.designation,
                department: emp.department,
                employmentType: emp.employmentType,
                joiningDate: emp.joiningDate?.split('T')[0] || '',
                probationEndDate: emp.probationEndDate?.split('T')[0] || '',
                status: emp.status,
                reportingTo: (emp.reportingTo as any)?._id || '',
                paidLeavesPerYear: (emp as any).paidLeavesPerYear ?? 12,
                workSchedule: emp.workSchedule || { workingDaysPerWeek: 5, hoursPerDay: 8 },
            });
        }
    }, [existingData]);

    useEffect(() => {
        if (isEdit || departmentOptions.length === 0) return;
        setForm((prev) => {
            if (prev.department && departmentOptions.includes(prev.department)) {
                return prev;
            }

            return {
                ...prev,
                department: departmentOptions[0],
            };
        });
    }, [departmentOptions, isEdit]);

    const cleanPayload = (data: any) => {
        const cleaned = { ...data };
        if (!cleaned.reportingTo) delete cleaned.reportingTo;
        if (!cleaned.probationEndDate) delete cleaned.probationEndDate;
        return cleaned;
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setErrorMsg('');
        try {
            if (isEdit) {
                const { userId, employeeId, ...updateData } = form;
                await updateEmployee({ id: id!, data: cleanPayload(updateData) }).unwrap();
            } else {
                const payload = cleanPayload({
                    ...form,
                    onboarding: {
                        status: 'not-started',
                        checklist: DEFAULT_ONBOARDING_CHECKLIST.map((item) => ({ item, completed: false })),
                    },
                });
                await createEmployee(payload).unwrap();
            }
            navigate('/hrms/employees');
        } catch (err: any) {
            const msg = err?.data?.message || err?.message || 'Failed to save employee. Please check the form and try again.';
            setErrorMsg(msg);
            console.error('Failed to save employee:', err);
        }
    };

    const isSaving = isCreating || isUpdating;

    const inputStyle = {
        borderColor: 'var(--color-border-default)',
        backgroundColor: 'var(--color-bg-surface)',
        color: 'var(--color-text-primary)',
    };

    return (
        <div className="mx-auto" style={{ maxWidth: '860px' }}>
            {/* Header */}
            <div className="flex items-center gap-3 mb-6">
                <button onClick={() => navigate('/hrms/employees')} className="p-2 rounded-lg border cursor-pointer hover:bg-gray-50" style={{ borderColor: 'var(--color-border-default)' }}>
                    <ArrowLeft size={18} style={{ color: 'var(--color-text-muted)' }} />
                </button>
                <div className="flex items-center gap-2">
                    <UserPlus size={22} style={{ color: 'var(--color-primary)' }} />
                    <div>
                        <h1 className="text-2xl font-semibold" style={{ color: 'var(--color-text-primary)' }}>
                            {isEdit ? 'Edit Employee' : 'Add Employee'}
                        </h1>
                        <p className="text-sm" style={{ color: 'var(--color-text-secondary)' }}>
                            {isEdit
                                ? 'Update employee information'
                                : 'Create a new employee profile. Additional details will be collected via a self-onboarding form.'}
                        </p>
                    </div>
                </div>
            </div>

            {/* Error Banner */}
            {errorMsg && (
                <div className="mb-4 p-3 rounded-lg text-sm" style={{ backgroundColor: '#FEE2E2', color: '#991B1B', border: '1px solid #FECACA' }}>
                    ⚠️ {errorMsg}
                </div>
            )}

            <form onSubmit={handleSubmit}>
                {/* Basic Info */}
                <div className="rounded-lg border p-6 mb-4" style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-surface)' }}>
                    <h2 className="text-sm font-semibold mb-4 uppercase tracking-wider" style={{ color: 'var(--color-text-muted)' }}>Basic Information</h2>
                    <div className="grid grid-cols-2 gap-4">
                        {!isEdit && (
                            <div>
                                <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--color-text-secondary)' }}>Select User *</label>
                                <select required value={form.userId} onChange={(e) => {
                                        const selectedUser = availableUsers.find((u: any) => u._id === e.target.value);
                                        const userDepartment = String(selectedUser?.department || '').trim();
                                        const matchedDept =
                                            departmentOptions.find(
                                                (department) =>
                                                    department.toLowerCase() === userDepartment.toLowerCase()
                                            ) || resolveDepartmentValue(userDepartment, departmentOptions);
                                        setAutoFilledDept(!!matchedDept);
                                        setForm({ ...form, userId: e.target.value, ...(matchedDept ? { department: matchedDept } : {}) });
                                    }}
                                    className="w-full px-3 py-2.5 text-sm rounded-lg border cursor-pointer" style={inputStyle}>
                                    <option value="">— Choose a user —</option>
                                    {availableUsers.map((u: any) => (
                                        <option key={u._id} value={u._id}>{u.name} ({u.email})</option>
                                    ))}
                                </select>
                                {availableUsers.length === 0 && (
                                    <p className="text-xs mt-1" style={{ color: 'var(--color-text-muted)' }}>
                                        All users already have employee records, or no users found.
                                    </p>
                                )}
                            </div>
                        )}
                        <div>
                            <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--color-text-secondary)' }}>Employee ID *</label>
                            <input type="text" value={isEdit ? form.employeeId : 'Auto-generated on Save'} disabled={true}
                                onChange={(e) => setForm({ ...form, employeeId: e.target.value })}
                                className="w-full px-3 py-2.5 text-sm rounded-lg border" style={{ ...inputStyle, opacity: 0.7, cursor: 'not-allowed' }} placeholder="e.g. CU-0042" />
                        </div>
                        <div>
                            <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--color-text-secondary)' }}>Designation *</label>
                            <input type="text" required value={form.designation} onChange={(e) => setForm({ ...form, designation: e.target.value })}
                                className="w-full px-3 py-2.5 text-sm rounded-lg border" style={inputStyle} placeholder="e.g. Sr. Developer" />
                        </div>
                        <div>
                            <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--color-text-secondary)' }}>Department *</label>
                            <select required value={form.department} onChange={(e) => { setAutoFilledDept(false); setForm({ ...form, department: e.target.value }); }}
                                className="w-full px-3 py-2.5 text-sm rounded-lg border cursor-pointer" style={inputStyle}>
                                {departmentOptions.map((department) => (
                                    <option key={department} value={department}>
                                        {department}
                                    </option>
                                ))}
                            </select>
                            {autoFilledDept && (
                                <p className="text-xs mt-1" style={{ color: '#16A34A' }}>✓ Auto-filled from user profile</p>
                            )}
                        </div>
                        <div>
                            <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--color-text-secondary)' }}>Employment Type</label>
                            <select value={form.employmentType} onChange={(e) => setForm({ ...form, employmentType: e.target.value })}
                                className="w-full px-3 py-2.5 text-sm rounded-lg border cursor-pointer" style={inputStyle}>
                                {EMPLOYMENT_TYPES.map((t) => <option key={t} value={t}>{t.charAt(0).toUpperCase() + t.slice(1)}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--color-text-secondary)' }}>Joining Date *</label>
                            <input type="date" required value={form.joiningDate} onChange={(e) => setForm({ ...form, joiningDate: e.target.value })}
                                className="w-full px-3 py-2.5 text-sm rounded-lg border" style={inputStyle} />
                        </div>
                        <div>
                            <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--color-text-secondary)' }}>Probation End Date</label>
                            <input type="date" value={form.probationEndDate} onChange={(e) => setForm({ ...form, probationEndDate: e.target.value })}
                                className="w-full px-3 py-2.5 text-sm rounded-lg border" style={inputStyle} />
                        </div>
                        <div>
                            <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--color-text-secondary)' }}>Reports To</label>
                            <select value={form.reportingTo} onChange={(e) => setForm({ ...form, reportingTo: e.target.value })}
                                className="w-full px-3 py-2.5 text-sm rounded-lg border cursor-pointer" style={inputStyle}>
                                <option value="">— None —</option>
                                {existingEmployees.map((emp: any) => (
                                    <option key={emp._id} value={emp._id}>
                                        {emp.userId?.name || emp.employeeId} — {emp.designation}
                                    </option>
                                ))}
                            </select>
                        </div>
                    </div>
                </div>

                {/* Work Schedule */}
                <div className="rounded-lg border p-6 mb-6" style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-surface)' }}>
                    <h2 className="text-sm font-semibold mb-4 uppercase tracking-wider" style={{ color: 'var(--color-text-muted)' }}>Work Schedule &amp; Leaves</h2>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--color-text-secondary)' }}>Working Days / Week</label>
                            <input type="number" min={1} max={7} value={form.workSchedule.workingDaysPerWeek}
                                onChange={(e) => setForm({ ...form, workSchedule: { ...form.workSchedule, workingDaysPerWeek: parseInt(e.target.value) || 5 } })}
                                className="w-full px-3 py-2.5 text-sm rounded-lg border" style={inputStyle} />
                        </div>
                        <div>
                            <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--color-text-secondary)' }}>Hours / Day</label>
                            <input type="number" min={1} max={24} value={form.workSchedule.hoursPerDay}
                                onChange={(e) => setForm({ ...form, workSchedule: { ...form.workSchedule, hoursPerDay: parseInt(e.target.value) || 8 } })}
                                className="w-full px-3 py-2.5 text-sm rounded-lg border" style={inputStyle} />
                        </div>
                        <div>
                            <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--color-text-secondary)' }}>
                                Paid Leaves / Year
                                <span className="ml-1 text-xs font-normal" style={{ color: 'var(--color-text-muted)' }}>(used in payroll)</span>
                            </label>
                            <input
                                type="number"
                                min={0}
                                max={365}
                                value={form.paidLeavesPerYear}
                                onChange={(e) => setForm({ ...form, paidLeavesPerYear: parseInt(e.target.value) || 0 })}
                                className="w-full px-3 py-2.5 text-sm rounded-lg border"
                                style={inputStyle}
                                placeholder="e.g. 12"
                            />
                        </div>
                    </div>
                </div>

                {/* Info note */}
                {!isEdit && (
                    <div className="mb-6 px-4 py-3 rounded-lg text-sm flex gap-2"
                        style={{ backgroundColor: '#EFF6FF', color: '#1D4ED8', border: '1px solid #BFDBFE' }}>
                        <span>ℹ️</span>
                        <span>
                            Personal information, bank details, and identity documents will be collected directly from
                            the employee via a secure self-onboarding form. You can share that form from the employee's
                            profile page after creation.
                        </span>
                    </div>
                )}

                {/* Submit */}
                <div className="flex gap-3 pb-8">
                    <button
                        type="submit"
                        disabled={isSaving}
                        className="flex items-center gap-2 px-6 py-2.5 text-sm font-medium text-white rounded-lg transition-colors cursor-pointer disabled:opacity-60"
                        style={{ backgroundColor: 'var(--color-primary)' }}
                    >
                        {isSaving ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />}
                        {isSaving ? 'Saving...' : isEdit ? 'Update Employee' : 'Create Employee'}
                    </button>
                    <button type="button" onClick={() => navigate('/hrms/employees')}
                        className="px-6 py-2.5 text-sm font-medium rounded-lg border cursor-pointer"
                        style={{ borderColor: 'var(--color-border-default)', color: 'var(--color-text-primary)' }}>
                        Cancel
                    </button>
                </div>
            </form>
        </div>
    );
}

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useGetEmployeesQuery, useDeleteEmployeeMutation } from '@/features/hrms/hrmsApi';
import { useGetOrgSettingsQuery } from '@/features/overall-admin/api/adminApi';
import {
    Plus, Search, Trash2, Edit, Eye, Users, Building2, ChevronLeft, ChevronRight,
} from 'lucide-react';
import { dedupeDepartments, formatDepartmentLabel, normalizeDepartmentKey, DEFAULT_DEPARTMENTS } from '@/utils/department';
const STATUSES = ['active', 'on-notice', 'relieved', 'terminated'];

export default function HrmsEmployeesPage() {
    const navigate = useNavigate();
    const [searchInput, setSearchInput] = useState('');
    const [search, setSearch] = useState('');          // debounced value sent to API
    const [department, setDepartment] = useState('');
    const [status, setStatus] = useState('');
    const [page, setPage] = useState(1);
    const { data: orgSettingsData } = useGetOrgSettingsQuery();

    // Debounce: update `search` 350ms after the user stops typing
    useEffect(() => {
        const timer = setTimeout(() => setSearch(searchInput), 350);
        return () => clearTimeout(timer);
    }, [searchInput]);

    const { data, isLoading } = useGetEmployeesQuery({
        search: search || undefined,
        department: department || undefined,
        status: status || undefined,
        page,
        limit: 20,
    });

    const [deleteEmployee] = useDeleteEmployeeMutation();

    const employees = data?.data?.employees || [];
    const pagination = data?.data?.pagination;
    const departmentOptions = orgSettingsData?.data?.departments?.length
        ? dedupeDepartments(orgSettingsData.data.departments)
        : DEFAULT_DEPARTMENTS;

    const handleDelete = async (id: string, name: string) => {
        if (window.confirm(`Are you sure you want to delete ${name}?`)) {
            try {
                await deleteEmployee(id).unwrap();
            } catch (err) {
                console.error('Failed to delete employee:', err);
            }
        }
    };

    const getStatusColor = (s: string) => {
        switch (s) {
            case 'active': return { bg: 'var(--color-success-soft)', color: 'var(--color-success)' };
            case 'on-notice': return { bg: 'var(--color-warning-soft)', color: '#92400E' };
            case 'relieved': return { bg: 'var(--color-bg-subtle)', color: 'var(--color-text-muted)' };
            case 'terminated': return { bg: '#FEE2E2', color: '#991B1B' };
            default: return { bg: 'var(--color-bg-subtle)', color: 'var(--color-text-muted)' };
        }
    };

    const getDeptColor = (d: string) => {
        const colors: Record<string, string> = {
            engineering: '#3B82F6', design: '#8B5CF6', marketing: '#F59E0B',
            finance: '#10B981', hr: '#EC4899', admin: '#6B7280',
        };
        return colors[normalizeDepartmentKey(d)] || '#6B7280';
    };

    return (
        <div className="mx-auto" style={{ maxWidth: '1200px' }}>
            {/* Header */}
            <div className="flex items-center justify-between mb-6">
                <div>
                    <h1 className="text-2xl font-semibold" style={{ color: 'var(--color-text-primary)' }}>
                        Employees
                    </h1>
                    <p className="text-sm mt-1" style={{ color: 'var(--color-text-secondary)' }}>
                        Manage employee profiles, departments, and onboarding
                    </p>
                </div>
                <button
                    onClick={() => navigate('/hrms/employees/new')}
                    className="flex items-center gap-2 px-4 py-2.5 text-sm font-medium text-white rounded-lg transition-colors cursor-pointer"
                    style={{ backgroundColor: 'var(--color-primary)' }}
                >
                    <Plus size={16} />
                    Add Employee
                </button>
            </div>

            {/* Filters */}
            <div className="flex gap-3 mb-6">
                <div className="relative flex-1">
                    <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2" style={{ color: 'var(--color-text-muted)' }} />
                    <input
                        type="text"
                        placeholder="Search by name, email, ID, designation..."
                        value={searchInput}
                        onChange={(e) => { setSearchInput(e.target.value); setPage(1); }}
                        className="w-full pl-9 pr-4 py-2.5 text-sm rounded-lg border outline-none"
                        style={{
                            borderColor: 'var(--color-border-default)',
                            backgroundColor: 'var(--color-bg-surface)',
                            color: 'var(--color-text-primary)',
                        }}
                    />
                </div>
                <select
                    value={department}
                    onChange={(e) => { setDepartment(e.target.value); setPage(1); }}
                    className="px-3 py-2.5 text-sm rounded-lg border cursor-pointer"
                    style={{
                        borderColor: 'var(--color-border-default)',
                        backgroundColor: 'var(--color-bg-surface)',
                        color: 'var(--color-text-primary)',
                    }}
                >
                    <option value="">All Departments</option>
                    {departmentOptions.map((d) => (
                        <option key={d} value={d}>{d}</option>
                    ))}
                </select>
                <select
                    value={status}
                    onChange={(e) => { setStatus(e.target.value); setPage(1); }}
                    className="px-3 py-2.5 text-sm rounded-lg border cursor-pointer"
                    style={{
                        borderColor: 'var(--color-border-default)',
                        backgroundColor: 'var(--color-bg-surface)',
                        color: 'var(--color-text-primary)',
                    }}
                >
                    <option value="">All Statuses</option>
                    {STATUSES.map((s) => (
                        <option key={s} value={s}>{s.charAt(0).toUpperCase() + s.slice(1).replace('-', ' ')}</option>
                    ))}
                </select>
            </div>

            {/* Table */}
            <div className="rounded-lg border overflow-hidden" style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-surface)' }}>
                {isLoading ? (
                    <div className="p-12 text-center" style={{ color: 'var(--color-text-muted)' }}>Loading employees...</div>
                ) : employees.length === 0 ? (
                    <div className="p-12 text-center">
                        <Users size={40} className="mx-auto mb-3" style={{ color: 'var(--color-text-muted)' }} />
                        <p className="text-sm" style={{ color: 'var(--color-text-muted)' }}>No employees found</p>
                    </div>
                ) : (
                    <table className="w-full">
                        <thead>
                            <tr style={{ backgroundColor: 'var(--color-bg-subtle)' }}>
                                {['Employee', 'Department', 'Designation', 'Type', 'Status', 'Joining Date', 'Actions'].map((h) => (
                                    <th key={h} className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wider" style={{ color: 'var(--color-text-muted)' }}>
                                        {h}
                                    </th>
                                ))}
                            </tr>
                        </thead>
                        <tbody>
                            {employees.map((emp) => {
                                const statusStyle = getStatusColor(emp.status);
                                return (
                                    <tr
                                        key={emp._id}
                                        onClick={() => navigate(`/hrms/employees/${emp._id}`)}
                                        className="border-t cursor-pointer hover:bg-neutral-50 transition-colors"
                                        style={{ borderColor: 'var(--color-border-default)' }}
                                    >
                                        <td className="px-4 py-3">
                                            <div className="flex items-center gap-3">
                                                <div
                                                    className="w-9 h-9 rounded-full flex items-center justify-center text-white text-sm font-semibold"
                                                    style={{ backgroundColor: getDeptColor(emp.department) }}
                                                >
                                                    {(emp.userId as any)?.name?.charAt(0)?.toUpperCase() || '?'}
                                                </div>
                                                <div>
                                                    <div className="text-sm font-medium" style={{ color: 'var(--color-text-primary)' }}>
                                                        {(emp.userId as any)?.name || 'Unknown'}
                                                    </div>
                                                    <div className="text-xs" style={{ color: 'var(--color-text-muted)' }}>
                                                        {emp.employeeId} · {(emp.userId as any)?.email}
                                                    </div>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="px-4 py-3">
                                            <span className="inline-flex items-center gap-1 text-xs font-medium px-2 py-1 rounded-full"
                                                style={{ backgroundColor: getDeptColor(emp.department) + '20', color: getDeptColor(emp.department) }}
                                            >
                                                <Building2 size={12} />
                                                {formatDepartmentLabel(emp.department)}
                                            </span>
                                        </td>
                                        <td className="px-4 py-3 text-sm" style={{ color: 'var(--color-text-primary)' }}>{emp.designation}</td>
                                        <td className="px-4 py-3 text-sm capitalize" style={{ color: 'var(--color-text-secondary)' }}>{emp.employmentType}</td>
                                        <td className="px-4 py-3">
                                            <span className="text-xs font-medium px-2 py-1 rounded-full" style={{ backgroundColor: statusStyle.bg, color: statusStyle.color }}>
                                                {emp.status}
                                            </span>
                                        </td>
                                        <td className="px-4 py-3 text-sm" style={{ color: 'var(--color-text-secondary)' }}>
                                            {new Date(emp.joiningDate).toLocaleDateString()}
                                        </td>
                                        <td className="px-4 py-3">
                                            <div className="flex items-center gap-1" onClick={e => e.stopPropagation()}>
                                                <button onClick={() => navigate(`/hrms/employees/${emp._id}`)} className="p-1.5 rounded hover:bg-gray-100 cursor-pointer" title="View">
                                                    <Eye size={16} style={{ color: 'var(--color-text-muted)' }} />
                                                </button>
                                                <button onClick={() => navigate(`/hrms/employees/${emp._id}/edit`)} className="p-1.5 rounded hover:bg-gray-100 cursor-pointer" title="Edit">
                                                    <Edit size={16} style={{ color: 'var(--color-text-muted)' }} />
                                                </button>
                                                <button onClick={() => handleDelete(emp._id, (emp.userId as any)?.name)} className="p-1.5 rounded hover:bg-red-50 cursor-pointer" title="Delete">
                                                    <Trash2 size={16} style={{ color: '#EF4444' }} />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                )}

                {/* Pagination */}
                {pagination && pagination.pages > 1 && (
                    <div className="flex items-center justify-between px-4 py-3 border-t" style={{ borderColor: 'var(--color-border-default)' }}>
                        <div className="text-sm" style={{ color: 'var(--color-text-muted)' }}>
                            Showing {((page - 1) * 20) + 1}–{Math.min(page * 20, pagination.total)} of {pagination.total}
                        </div>
                        <div className="flex gap-1">
                            <button
                                onClick={() => setPage((p) => Math.max(1, p - 1))}
                                disabled={page === 1}
                                className="p-1.5 rounded border cursor-pointer disabled:opacity-50"
                                style={{ borderColor: 'var(--color-border-default)' }}
                            >
                                <ChevronLeft size={16} />
                            </button>
                            <button
                                onClick={() => setPage((p) => Math.min(pagination.pages, p + 1))}
                                disabled={page === pagination.pages}
                                className="p-1.5 rounded border cursor-pointer disabled:opacity-50"
                                style={{ borderColor: 'var(--color-border-default)' }}
                            >
                                <ChevronRight size={16} />
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

import { useState } from 'react';
