    };

    const handleReject = async (id: string, reason: string) => {
        try {
            await updateStatus({ id, data: { status: 'rejected', rejectionReason: reason } }).unwrap();
            setRejectingId(null);
            await refreshLeaveLists();
        } catch (err: any) {
            alert(err?.data?.message || 'Failed to reject leave request');
