    };

    const handleEditStatus = async (
        id: string,
        status: 'approved' | 'rejected' | 'cancelled',
        reason: string,
        type: LeaveType,
        isPaid: boolean
    ) => {
        try {
            await updateStatus({
                id,
                data: {
                    status,
                    rejectionReason: status === 'rejected' ? reason : undefined,
                    type,
                    isPaid,
                },
