                                            <label className="block text-xs font-medium mb-1.5"
                                                style={{ color: 'var(--color-text-secondary)' }}>
                                                {label}
                                            </label>
                                            <input
                                                type="text"
                                                value={(personalForm as any)[key]}
                                                onChange={e => setPersonalForm({ ...personalForm, [key]: e.target.value })}
                                                className={inputCls}
                                                style={inputStyle}
                                            />
                                        </div>
                                    ))}
                                </div>
                                <div className="pt-2 flex gap-3">
                                    <button type="submit" disabled={isSaving}
                                        className="flex-1 flex items-center justify-center gap-2 py-2.5 text-sm font-medium text-white rounded-lg cursor-pointer disabled:opacity-60"
                                        style={{ backgroundColor: 'var(--color-primary)' }}>
                                        {isSaving ? <Loader2 size={15} className="animate-spin" /> : <Save size={15} />}
                                        Save Changes
                                    </button>
                                    <button type="button" onClick={() => setActiveModal(null)}
                                        className="px-4 py-2.5 text-sm font-medium rounded-lg border cursor-pointer"
                                        style={{ borderColor: 'var(--color-border-default)', color: 'var(--color-text-primary)' }}>
                                        Cancel
                                    </button>
                                </div>
                            </form>
                        </div>
                    </ModalPortal>
                )}
            </div>
        );
    }

    // ── EMPLOYEE & TEAM MEMBER UI ───────────────────────────────────

    if (isPartnerEmployee && !partnerEmployeeInfo) {
        return (
            <div className="p-12 text-center" style={{ color: 'var(--color-text-muted)' }}>
                No team member profile found.
            </div>
        );
    }

    if (!employee && isRegularEmployee) {
        return (
            <div className="p-12 text-center" style={{ color: 'var(--color-text-muted)' }}>
                No employee profile found. Contact HR.
            </div>
        );
    }

    const bankMasked = [
        { label: 'Bank Name', raw: employee?.bankDetails?.bankName },
        {
            label: 'Account Number',
            raw: employee?.bankDetails?.accountNumber,
            masked: employee?.bankDetails?.accountNumber
                ? '•••• ' + employee.bankDetails.accountNumber.slice(-4)
                : null,
        },
        { label: 'IFSC Code', raw: employee?.bankDetails?.ifscCode },
        { label: 'Bank Branch', raw: employee?.bankDetails?.bankBranch },
        { label: 'UPI ID', raw: employee?.bankDetails?.upiId },
        {
            label: 'PAN Number',
            raw: employee?.bankDetails?.panNumber,
            masked: employee?.bankDetails?.panNumber
                ? employee.bankDetails.panNumber.slice(0, 3) + '••••' + employee.bankDetails.panNumber.slice(-3)
                : null,
        },
    ];

    return (
        <div className="mx-auto" style={{ maxWidth: '1000px' }}>
            {/* ── Profile Header ──────────────────────────────────── */}
            <div
                className="rounded-xl border p-6 mb-6 flex items-center gap-5"
                style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-surface)' }}
            >
                {isPartnerEmployee ? (
                    // Partner Employee Header
                    <>
                        <div
                            className="w-20 h-20 rounded-full flex items-center justify-center text-white text-2xl font-bold shrink-0"
                            style={{ background: 'linear-gradient(135deg, #6366F1, #8B5CF6)' }}
                        >
                            {partnerEmployeeInfo?.name?.substring(0, 2).toUpperCase() || 'P'}
                        </div>
                        <div>
                            <h1 className="text-xl font-semibold" style={{ color: 'var(--color-text-primary)' }}>
                                {partnerEmployeeInfo?.name}
                            </h1>
                            <p className="text-sm mt-0.5" style={{ color: 'var(--color-text-secondary)' }}>
                                {partnerEmployeeInfo?.designation || 'Partner Team Member'}
                            </p>
                        </div>
                    </>
                ) : (
                    // Employee Header
                    <>
                        {employee?.profilePhoto?.url ? (
                            <img
                                src={employee.profilePhoto.url}
                                alt="Profile"
                                className="w-20 h-20 rounded-full object-cover shrink-0"
                                style={{ border: '3px solid var(--color-border-default)' }}
                            />
                        ) : (
                            <div
                                className="w-20 h-20 rounded-full flex items-center justify-center text-white text-2xl font-bold shrink-0"
                                style={{ background: 'linear-gradient(135deg,#059669,#0EA5E9)' }}
                            >
                                {employee?.userId?.name?.split(' ').map((n: string) => n[0]).join('').toUpperCase().slice(0, 2) || 'U'}
                            </div>
                        )}
                        <div>
                            <h1 className="text-xl font-semibold" style={{ color: 'var(--color-text-primary)' }}>
                                {employee?.userId?.name}
                            </h1>
                            <p className="text-sm mt-0.5" style={{ color: 'var(--color-text-secondary)' }}>
                                {employee?.designation}
                                {employee?.employeeId && (
                                    <span className="ml-2 text-xs px-2 py-0.5 rounded-full font-mono"
                                        style={{ backgroundColor: 'var(--color-bg-subtle)', color: 'var(--color-text-muted)' }}>
                                        {employee.employeeId}
                                    </span>
                                )}
                            </p>
                            <p className="text-xs mt-1 capitalize" style={{ color: 'var(--color-text-muted)' }}>
                                {employee?.department} · {employee?.employmentType}
                            </p>
                            <div className="mt-3">
                                <button
                                    onClick={() => photoInputRef.current?.click()}
                                    disabled={isUploadingPhoto}
                                    className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-lg border cursor-pointer hover:bg-gray-50 disabled:opacity-60"
                                    style={{ borderColor: 'var(--color-border-default)', color: 'var(--color-text-secondary)' }}
                                >
                                    {isUploadingPhoto ? <Loader2 size={12} className="animate-spin" /> : <Camera size={12} />}
                                    Change Photo
                                </button>
                                <input
                                    ref={photoInputRef}
                                    type="file"
                                    accept="image/png,image/jpeg,image/webp"
                                    className="hidden"
                                    onChange={handleMyPhotoChange}
                                />
                            </div>
                        </div>
                    </>
                )}
            </div>

            <div className="grid grid-cols-3 gap-5">

                {/* Left — Employee Details + Personal Info */}
                <div className="col-span-2 space-y-5">
                    {/* Employee/Partner Details — read-only */}
                    {isPartnerEmployee ? (
                        <div className="rounded-xl border p-6"
                            style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-surface)' }}>
                            <SectionHeader
                                icon={<User size={17} style={{ color: 'var(--color-primary)' }} />}
                                title="Account Profile"
                            />
                            <div className="grid grid-cols-2 gap-y-5 gap-x-10">
                                <FieldRow label="Email">{partnerEmployeeInfo?.email}</FieldRow>
                                <FieldRow label="Designation">{partnerEmployeeInfo?.designation}</FieldRow>
                                <FieldRow label="Status">
                                    <span className="capitalize">{partnerEmployeeInfo?.isActive ? 'Active' : 'Inactive'}</span>
                                </FieldRow>
                            </div>
                        </div>
                    ) : (
                        <div className="rounded-xl border p-6"
                            style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-surface)' }}>
                            <SectionHeader
                                icon={<User size={17} style={{ color: 'var(--color-primary)' }} />}
                                title="Employee Details"
                            />
                            <div className="grid grid-cols-2 gap-y-5 gap-x-10">
                                <FieldRow label="Email">{employee?.userId?.email}</FieldRow>
                                <FieldRow label="Department">
                                    <span className="capitalize">{employee?.department}</span>
                                </FieldRow>
                                <FieldRow label="Employment Type">
                                    <span className="capitalize">{employee?.employmentType}</span>
                                </FieldRow>
                                <FieldRow label="Status">
                                    <span className="capitalize">{employee?.status?.replace('-', ' ')}</span>
                                </FieldRow>
                                <FieldRow label="Joining Date">
                                    {employee?.joiningDate
                                        ? new Date(employee.joiningDate).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })
                                        : '—'}
                                </FieldRow>
                                <FieldRow label="Working Days / Week">
                                    {employee?.workSchedule?.workingDaysPerWeek ?? 5} days
                                </FieldRow>
                            </div>
                        </div>
                    )}

                    {/* Personal Information — editable */}
                    <div className="rounded-xl border p-6"
                        style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-surface)' }}>
                        <SectionHeader
                            icon={<User size={17} style={{ color: 'var(--color-primary)' }} />}
                            title={'Personal Information'}
                            onEdit={openPersonalModal}
                        />
                        <div className="grid grid-cols-2 gap-y-5 gap-x-10">
                            {isPartnerEmployee ? (
                                <>
                                    <FieldRow label="Mobile">{partnerEmployeeInfo?.phone}</FieldRow>
                                </>
                            ) : (
                                <>
                                    <FieldRow label="Mobile">{employee?.personalInfo?.phone}</FieldRow>
                                    <FieldRow label="Alternate Mobile">{employee?.personalInfo?.alternatePhone}</FieldRow>
                                    <FieldRow label="Gender">
                                        <span className="capitalize">{employee?.personalInfo?.gender}</span>
                                    </FieldRow>
                                    <FieldRow label="Date of Birth">
                                        {employee?.personalInfo?.dob
                                            ? new Date(employee.personalInfo.dob).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })
                                            : '—'}
                                    </FieldRow>
                                    <FieldRow label="Father's Name">{employee?.personalInfo?.fatherName}</FieldRow>
                                    <FieldRow label="Father's Contact">{employee?.personalInfo?.fatherPhone}</FieldRow>
                                    <FieldRow label="Address">{employee?.personalInfo?.address?.street}</FieldRow>
                                    <FieldRow label="State">{employee?.personalInfo?.address?.state}</FieldRow>
                                    <FieldRow label="Pincode">{employee?.personalInfo?.address?.postalCode}</FieldRow>
                                </>
                            )}
                        </div>
                    </div>
                </div>

                {/* Right — Bank Details + Identity */}
                <div className="space-y-5">
                    {isRegularEmployee && (
                        <>
                            {/* Bank Details — editable */}
                            <div className="rounded-xl border p-6"
                                style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-surface)' }}>
                                <div className="flex items-center justify-between mb-5">
                                    <div className="flex items-center gap-2">
                                        <Briefcase size={17} style={{ color: 'var(--color-primary)' }} />
                                        <h2 className="text-sm font-semibold" style={{ color: 'var(--color-text-primary)' }}>
                                            Bank Details
                                        </h2>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <button
                                            onClick={() => setShowBank(v => !v)}
                                            className="flex items-center gap-1 px-2.5 py-1.5 text-xs font-medium rounded-lg border cursor-pointer hover:bg-gray-50"
                                            style={{ borderColor: 'var(--color-border-default)', color: 'var(--color-text-secondary)' }}
                                        >
                                            {showBank ? <EyeOff size={12} /> : <Eye size={12} />}
                                            {showBank ? 'Hide' : 'Show'}
                                        </button>
                                        <button
                                            onClick={openBankModal}
                                            className="flex items-center gap-1 px-2.5 py-1.5 text-xs font-medium rounded-lg border cursor-pointer hover:bg-gray-50"
                                            style={{ borderColor: 'var(--color-border-default)', color: 'var(--color-text-secondary)' }}
                                        >
                                            <Edit size={12} /> Edit
                                        </button>
                                    </div>
                                </div>
                                <div className="space-y-2">
                                    {bankMasked.map(({ label, raw, masked }) => (
                                        <div key={label} className="flex justify-between items-center py-2 border-b last:border-0"
                                            style={{ borderColor: 'var(--color-border-default)' }}>
                                            <span className="text-xs" style={{ color: 'var(--color-text-muted)' }}>{label}</span>
                                            <span className="text-sm font-medium"
                                                style={{
                                                    color: showBank && raw ? 'var(--color-text-primary)' : 'var(--color-text-muted)',
                                                    fontFamily: !showBank && raw ? 'monospace' : undefined,
                                                }}>
                                                {showBank ? (raw || '—') : (masked || raw ? (masked || raw) : '—')}
                                            </span>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Identity Verification — view only */}
                            {employee?.identityVerification?.type && (
                                <div className="rounded-xl border p-6"
                                    style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'var(--color-bg-surface)' }}>
                                    <div className="flex items-center gap-2 mb-4">
                                        <ShieldCheck size={17} style={{ color: 'var(--color-primary)' }} />
                                        <h2 className="text-sm font-semibold" style={{ color: 'var(--color-text-primary)' }}>
                                            Identity Verification
                                        </h2>
                                    </div>
                                    <div className="space-y-3">
                                        <div className="flex justify-between items-center py-2 border-b"
                                            style={{ borderColor: 'var(--color-border-default)' }}>
                                            <span className="text-xs" style={{ color: 'var(--color-text-muted)' }}>Type</span>
                                            <span className="text-sm font-medium capitalize" style={{ color: 'var(--color-text-primary)' }}>
                                                {employee.identityVerification.type}
                                            </span>
                                        </div>
                                        <div className="flex justify-between items-center py-2 border-b"
                                            style={{ borderColor: 'var(--color-border-default)' }}>
                                            <span className="text-xs" style={{ color: 'var(--color-text-muted)' }}>ID Number</span>
                                            <div className="flex items-center gap-2">
                                                <span className="text-sm font-medium font-mono" style={{ color: 'var(--color-text-primary)' }}>
                                                    {employee.identityVerification.idNumber
                                                        ? showIdNumber
                                                            ? String(employee.identityVerification.idNumber)
                                                            : '•••• ' + String(employee.identityVerification.idNumber).slice(-4)
                                                        : '—'}
                                                </span>
                                                {employee.identityVerification.idNumber && (
                                                    <button
                                                        onClick={() => setShowIdNumber(v => !v)}
                                                        className="flex items-center gap-1 px-2 py-0.5 text-xs rounded-md border cursor-pointer hover:bg-gray-50"
                                                        style={{ borderColor: 'var(--color-border-default)', color: 'var(--color-text-secondary)' }}
                                                    >
                                                        {showIdNumber ? <EyeOff size={10} /> : <Eye size={10} />}
                                                    </button>
                                                )}
                                            </div>
                                        </div>
                                        {employee.identityVerification.documentCloudinaryId && (
                                            <div className="pt-1">
                                                <a
                                                    href={`${API_BASE}/hrms/employees/${employee._id}/identity-document`}
                                                    target="_blank"
                                                    rel="noopener noreferrer"
                                                    className="text-xs flex items-center gap-1.5"
                                                    style={{ color: 'var(--color-primary)' }}
                                                >
                                                    <Eye size={12} /> View Document
                                                </a>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            )}
                        </>
                    )}
                </div>
            </div>

            {/* ── Personal Info Modal ──────────────────────────────── */}
            {activeModal === 'personal' && (
                <ModalPortal>
                    <div className="w-full max-w-4xl rounded-xl border p-5 shadow-xl"
                        style={{ backgroundColor: 'var(--color-bg-surface)', borderColor: 'var(--color-border-default)' }}>
                        <div className="flex justify-between items-center mb-5">
                            <h2 className="text-base font-semibold" style={{ color: 'var(--color-text-primary)' }}>
                                Edit Personal Information
                            </h2>
                            <button onClick={() => setActiveModal(null)}
                                className="p-1 rounded-md hover:bg-gray-100 cursor-pointer">
                                <X size={18} style={{ color: 'var(--color-text-muted)' }} />
                            </button>
                        </div>
                        <form onSubmit={handleSavePersonal} className="space-y-3">
                            <div className="grid grid-cols-2 lg:grid-cols-3 gap-3">
                                {[
                                    { key: 'phone', label: 'Mobile', show: true },
                                    { key: 'alternatePhone', label: 'Alternate Mobile', show: isRegularEmployee },
                                    { key: 'fatherName', label: "Father's Name", show: isRegularEmployee },
                                    { key: 'fatherPhone', label: "Father's Contact", show: isRegularEmployee },
                                    { key: 'address_street', label: 'Address / Street', show: !isPartnerEmployee },
                                    { key: 'address_state', label: 'State', show: !isPartnerEmployee },
                                    { key: 'address_postalCode', label: 'Pincode', show: !isPartnerEmployee },
                                ].filter(f => f.show).map(({ key, label }) => (
                                    <div key={key}>
                                        <label className="block text-xs font-medium mb-1.5"
                                            style={{ color: 'var(--color-text-secondary)' }}>
                                            {label}
                                        </label>
                                        <input
                                            type="text"
                                            value={(personalForm as any)[key]}
                                            onChange={e => setPersonalForm({ ...personalForm, [key]: e.target.value })}
                                            className={inputCls}
                                            style={inputStyle}
                                        />
                                    </div>
                                ))}
                                {/* Gender */}
                                {isRegularEmployee && (
                                    <>
                                        <div>
                                            <label className="block text-xs font-medium mb-1.5"
                                                style={{ color: 'var(--color-text-secondary)' }}>Gender</label>
                                            <select
                                                value={personalForm.gender}
                                                onChange={e => setPersonalForm({ ...personalForm, gender: e.target.value })}
                                                className={inputCls}
                                                style={inputStyle}
                                            >
                                                <option value="">Select</option>
                                                <option value="male">Male</option>
                                                <option value="female">Female</option>
                                                <option value="other">Other</option>
                                            </select>
                                        </div>
                                        {/* DOB */}
                                        <div>
                                            <label className="block text-xs font-medium mb-1.5"
                                                style={{ color: 'var(--color-text-secondary)' }}>Date of Birth</label>
                                            <input
                                                type="date"
                                                value={personalForm.dob}
                                                onChange={e => setPersonalForm({ ...personalForm, dob: e.target.value })}
                                                className={inputCls}
                                                style={inputStyle}
                                            />
                                        </div>
                                    </>
                                )}
                            </div>
                            <div className="pt-2 flex gap-3">
                                <button type="submit" disabled={isSaving}
                                    className="flex-1 flex items-center justify-center gap-2 py-2.5 text-sm font-medium text-white rounded-lg cursor-pointer disabled:opacity-60"
                                    style={{ backgroundColor: 'var(--color-primary)' }}>
                                    {isSaving ? <Loader2 size={15} className="animate-spin" /> : <Save size={15} />}
                                    Save Changes
                                </button>
                                <button type="button" onClick={() => setActiveModal(null)}
                                    className="px-4 py-2.5 text-sm font-medium rounded-lg border cursor-pointer"
                                    style={{ borderColor: 'var(--color-border-default)', color: 'var(--color-text-primary)' }}>
                                    Cancel
                                </button>
                            </div>
                        </form>
                    </div>
                </ModalPortal>
            )}

            {/* ── Bank Details Modal ────────────────────────────────── */}
            {activeModal === 'bank' && (
                <ModalPortal>
                    <div className="w-full max-w-lg rounded-xl border p-5 shadow-xl"
                        style={{ backgroundColor: 'var(--color-bg-surface)', borderColor: 'var(--color-border-default)' }}>
                        <div className="flex justify-between items-center mb-5">
                            <h2 className="text-base font-semibold" style={{ color: 'var(--color-text-primary)' }}>
                                Edit Bank Details
                            </h2>
                            <button onClick={() => setActiveModal(null)}
                                className="p-1 rounded-md hover:bg-gray-100 cursor-pointer">
                                <X size={18} style={{ color: 'var(--color-text-muted)' }} />
                            </button>
                        </div>
                        <form onSubmit={handleSaveBank} className="space-y-3">
                            <div className="grid grid-cols-2 gap-3">
                                {[
                                    ['bankName', 'Bank Name'],
                                    ['accountNumber', 'Account Number'],
                                    ['ifscCode', 'IFSC Code'],
                                    ['bankBranch', 'Branch'],
                                    ['panNumber', 'PAN Number'],
                                    ['upiId', 'UPI ID'],
                                ].map(([key, label]) => (
                                    <div key={key}>
                                        <label className="block text-xs font-medium mb-1.5"
                                            style={{ color: 'var(--color-text-secondary)' }}>
                                            {label}
                                        </label>
                                        <input
                                            type="text"
                                            value={(bankForm as any)[key]}
                                            onChange={e => setBankForm({ ...bankForm, [key]: e.target.value })}
                                            className={inputCls}
                                            style={inputStyle}
                                        />
                                    </div>
                                ))}
                            </div>
                            <div className="pt-2 flex gap-3">
                                <button type="submit" disabled={isSaving}
                                    className="flex-1 flex items-center justify-center gap-2 py-2.5 text-sm font-medium text-white rounded-lg cursor-pointer disabled:opacity-60"
                                    style={{ backgroundColor: 'var(--color-primary)' }}>
                                    {isSaving ? <Loader2 size={15} className="animate-spin" /> : <Save size={15} />}
                                    Save Changes
                                </button>
                                <button type="button" onClick={() => setActiveModal(null)}
                                    className="px-4 py-2.5 text-sm font-medium rounded-lg border cursor-pointer"
                                    style={{ borderColor: 'var(--color-border-default)', color: 'var(--color-text-primary)' }}>
                                    Cancel
                                </button>
                            </div>
                        </form>
                    </div>
                </ModalPortal>
            )}
        </div>
    );
}

import { useMemo, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import {
    ArrowLeft,
    Building2,
    Copy,
    Pencil,
    RefreshCcw,
    ToggleLeft,
    ToggleRight,
    UserCircle2,
} from 'lucide-react';
import {
    useActivatePartnerMutation,
    useDeactivatePartnerMutation,
    useGetPartnerByIdQuery,
    useGetPartnerClientsQuery,
    useGetPartnerProjectsQuery,
    useRegeneratePartnerTokenMutation,
} from '@/features/partners/partnersApi';

type DetailTab = 'company' | 'personal' | 'access' | 'clients' | 'projects';

function InfoField({ label, value }: { label: string; value?: string | null }) {
    return (
        <div className="rounded-2xl border p-4" style={{ borderColor: 'var(--color-border-default)', backgroundColor: '#FCFCFD' }}>
            <p className="text-[11px] font-semibold uppercase tracking-[0.18em]" style={{ color: 'var(--color-text-muted)' }}>
                {label}
            </p>
            <p className="mt-2 text-sm font-medium break-words" style={{ color: 'var(--color-text-primary)' }}>
                {value && String(value).trim() ? value : '-'}
            </p>
        </div>
    );
}

export default function PartnerDetailPage() {
    const navigate = useNavigate();
    const { id } = useParams<{ id: string }>();
    const [tab, setTab] = useState<DetailTab>('company');

    const { data: partnerResponse, isLoading } = useGetPartnerByIdQuery(id || '', { skip: !id });
    const { data: clientsResponse, isFetching: isClientsLoading } = useGetPartnerClientsQuery(id || '', {
        skip: !id || tab !== 'clients',
    });
    const { data: projectsResponse, isFetching: isProjectsLoading } = useGetPartnerProjectsQuery(id || '', {
        skip: !id || tab !== 'projects',
    });

    const [activatePartner, { isLoading: isActivating }] = useActivatePartnerMutation();
    const [deactivatePartner, { isLoading: isDeactivating }] = useDeactivatePartnerMutation();
    const [regenerateToken, { isLoading: isRegenerating }] = useRegeneratePartnerTokenMutation();

    const partner = partnerResponse?.data;
    const clients = useMemo(() => {
        const rawClients = clientsResponse?.data || [];
        return Array.from(new Map(rawClients.map((client: any) => [client._id, client])).values());
    }, [clientsResponse?.data]);
    const projects = projectsResponse?.data || [];

    const stats = useMemo(() => ({
        clients: partner?.stats?.clientsCount || clients.length,
        projects: partner?.stats?.projectsCount || projects.length,
        activeProjects: partner?.stats?.activeProjectsCount || 0,
    }), [partner, clients.length, projects.length]);

    if (isLoading) {
        return <div className="p-8">Loading partner details...</div>;
    }

    if (!partner) {
        return <div className="p-8">Partner not found.</div>;
    }

    const formattedAddress = [
        partner.address?.street,
        partner.address?.city,
        partner.address?.state,
        partner.address?.country,
        partner.address?.postalCode,
    ]
        .filter(Boolean)
        .join(', ');

    const copyText = async (value: string, message: string) => {
        await navigator.clipboard.writeText(value);
        alert(message);
    };

    const handleToggle = async () => {
        try {
            if (partner.isActive) {
                await deactivatePartner(partner._id).unwrap();
            } else {
                await activatePartner(partner._id).unwrap();
            }
        } catch (error: any) {
            alert(error?.data?.message || 'Failed to update status');
        }
    };

    const handleRegenerate = async () => {
        try {
            const result = await regenerateToken(partner._id).unwrap();
            const link = result?.data?.registrationLink;
            if (link) {
                await copyText(link, 'New registration link copied to clipboard');
            }
        } catch (error: any) {
            alert(error?.data?.message || 'Failed to regenerate registration link');
        }
    };

    const tabs: Array<{ key: DetailTab; label: string }> = [
        { key: 'company', label: 'Company Info' },
        { key: 'personal', label: 'Personal Info' },
        { key: 'access', label: 'Access & Portal' },
        { key: 'clients', label: 'Clients' },
        { key: 'projects', label: 'Projects' },
    ];

    return (
        <div className="p-6 md:p-8 mx-auto space-y-6" style={{ maxWidth: '1240px' }}>
            <div className="flex flex-col gap-5 rounded-[28px] border bg-white p-6 shadow-sm" style={{ borderColor: 'var(--color-border-default)' }}>
                <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
                    <div className="flex items-start gap-4">
                        <button
                            onClick={() => navigate('/admin/partners/manage')}
                            className="mt-1 p-2.5 rounded-xl hover:bg-neutral-100 transition-colors"
                            style={{ border: '1px solid var(--color-border-default)' }}
                        >
                            <ArrowLeft size={20} />
                        </button>

                        <div className="space-y-3">
                            <div>
                                <h1 className="text-3xl font-bold" style={{ color: 'var(--color-text-primary)' }}>
                                    {partner.companyName || partner.contactPerson || 'Partner'}
                                </h1>
                                <p className="mt-1 text-sm" style={{ color: 'var(--color-text-secondary)' }}>
                                    {partner.userId?.email || partner.email || 'No email added'}
                                </p>
                            </div>

                            <div className="flex flex-wrap gap-2">
                                <span
                                    className="rounded-full px-3 py-1 text-xs font-semibold"
                                    style={{
                                        backgroundColor: partner.isActive ? '#ECFDF5' : '#FEF2F2',
                                        color: partner.isActive ? '#047857' : '#B91C1C',
                                    }}
                                >
                                    {partner.isActive ? 'Active' : 'Inactive'}
                                </span>
                                <span
                                    className="rounded-full px-3 py-1 text-xs font-semibold capitalize"
                                    style={{
                                        backgroundColor: partner.registrationStatus === 'completed' ? '#EEF2FF' : '#FFF7ED',
                                        color: partner.registrationStatus === 'completed' ? '#4338CA' : '#C2410C',
                                    }}
                                >
                                    {partner.registrationStatus || 'pending'}
                                </span>
                                <span
                                    className="rounded-full px-3 py-1 text-xs font-semibold"
                                    style={{ backgroundColor: '#F8FAFC', color: '#475569' }}
                                >
                                    Slug: {partner.slug || '-'}
                                </span>
                            </div>
                        </div>
                    </div>

                    <div className="flex flex-wrap items-center gap-3">
                        <button
                            onClick={() => navigate(`/admin/partners/manage/${partner._id}/edit`)}
                            className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl border text-sm font-medium transition-all hover:shadow-md"
                            style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'white' }}
                        >
                            <Pencil size={16} /> Edit Partner
                        </button>
                        <button
                            onClick={handleToggle}
                            disabled={isActivating || isDeactivating}
                            className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-medium transition-all hover:shadow-md disabled:opacity-50"
                            style={{
                                backgroundColor: partner.isActive ? '#FEF2F2' : '#ECFDF5',
                                color: partner.isActive ? '#DC2626' : '#059669',
                                border: `1px solid ${partner.isActive ? '#FCA5A5' : '#86EFAC'}`,
                            }}
                        >
                            {partner.isActive ? <ToggleRight size={18} /> : <ToggleLeft size={18} />}
                            {partner.isActive ? 'Deactivate' : 'Activate'}
                        </button>
                    </div>
                </div>

                <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
                    <div className="rounded-2xl border p-4" style={{ borderColor: 'var(--color-border-default)', backgroundColor: '#F8FAFC' }}>
                        <p className="text-xs font-semibold uppercase tracking-wider" style={{ color: 'var(--color-text-muted)' }}>Clients</p>
                        <p className="mt-2 text-3xl font-bold" style={{ color: 'var(--color-text-primary)' }}>{stats.clients}</p>
                    </div>
                    <div className="rounded-2xl border p-4" style={{ borderColor: 'var(--color-border-default)', backgroundColor: '#F8FAFC' }}>
                        <p className="text-xs font-semibold uppercase tracking-wider" style={{ color: 'var(--color-text-muted)' }}>Projects</p>
                        <p className="mt-2 text-3xl font-bold" style={{ color: 'var(--color-text-primary)' }}>{stats.projects}</p>
                    </div>
                    <div className="rounded-2xl border p-4" style={{ borderColor: 'var(--color-border-default)', backgroundColor: '#F8FAFC' }}>
                        <p className="text-xs font-semibold uppercase tracking-wider" style={{ color: 'var(--color-text-muted)' }}>Active Projects</p>
                        <p className="mt-2 text-3xl font-bold" style={{ color: 'var(--color-text-primary)' }}>{stats.activeProjects}</p>
                    </div>
                </div>
            </div>

            <div className="rounded-[28px] border bg-white shadow-sm" style={{ borderColor: 'var(--color-border-default)' }}>
                <div
                    className="flex flex-wrap gap-2 border-b px-4 pt-4"
                    style={{ borderColor: 'var(--color-border-default)', backgroundColor: '#F8FAFC' }}
                >
                    {tabs.map((item) => (
                        <button
                            key={item.key}
                            onClick={() => setTab(item.key)}
                            className="rounded-t-2xl px-5 py-3 text-sm font-semibold transition-all"
                            style={
                                tab === item.key
                                    ? {
                                        backgroundColor: 'white',
                                        color: 'var(--color-text-primary)',
                                        border: '1px solid var(--color-border-default)',
                                        borderBottomColor: 'white',
                                    }
                                    : {
                                        color: 'var(--color-text-secondary)',
                                        backgroundColor: 'transparent',
                                        border: '1px solid transparent',
                                    }
                            }
                        >
                            {item.label}
                        </button>
                    ))}
                </div>

                <div className="p-6 md:p-7">
                    {tab === 'company' && (
                        <div className="grid grid-cols-1 gap-6 xl:grid-cols-[320px_1fr]">
                            <div className="rounded-3xl border p-6 text-center" style={{ borderColor: 'var(--color-border-default)', backgroundColor: '#FCFCFD' }}>
                                <div className="mx-auto flex h-40 w-full max-w-[220px] items-center justify-center overflow-hidden rounded-3xl border bg-white" style={{ borderColor: 'var(--color-border-default)' }}>
                                    {partner.companyLogo ? (
                                        <img src={partner.companyLogo} alt={partner.companyName || 'Company logo'} className="h-full w-full object-contain p-5" />
                                    ) : (
                                        <div className="flex flex-col items-center gap-3">
                                            <Building2 size={40} style={{ color: '#94A3B8' }} />
                                            <span className="text-sm font-medium" style={{ color: 'var(--color-text-muted)' }}>No company logo</span>
                                        </div>
                                    )}
                                </div>
                                <p className="mt-5 text-lg font-bold" style={{ color: 'var(--color-text-primary)' }}>
                                    {partner.companyName || 'Company name not added'}
                                </p>
                                <p className="mt-1 text-sm" style={{ color: 'var(--color-text-secondary)' }}>
                                    {partner.websiteLink || 'Website not added yet'}
                                </p>
                            </div>

                            <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                                <InfoField label="Company Name" value={partner.companyName} />
                                <InfoField label="Website" value={partner.websiteLink} />
                                <InfoField label="Contact Person" value={partner.contactPerson} />
                                <InfoField label="Contact Person Phone" value={partner.contactPersonPhone} />
                                <div className="md:col-span-2">
                                    <InfoField label="Address" value={formattedAddress} />
                                </div>
                            </div>
                        </div>
                    )}

                    {tab === 'personal' && (
                        <div className="grid grid-cols-1 gap-6 xl:grid-cols-[320px_1fr]">
                            <div className="rounded-3xl border p-6 text-center" style={{ borderColor: 'var(--color-border-default)', backgroundColor: '#FCFCFD' }}>
                                <div className="mx-auto flex h-44 w-44 items-center justify-center overflow-hidden rounded-3xl border bg-white" style={{ borderColor: 'var(--color-border-default)' }}>
                                    {partner.photo ? (
                                        <img src={partner.photo} alt={partner.userId?.name || partner.contactPerson || 'Partner'} className="h-full w-full object-cover" />
                                    ) : (
                                        <UserCircle2 size={72} style={{ color: '#94A3B8' }} />
                                    )}
                                </div>
                                <p className="mt-5 text-lg font-bold" style={{ color: 'var(--color-text-primary)' }}>
                                    {partner.userId?.name || 'Name not available'}
                                </p>
                                <p className="mt-1 text-sm" style={{ color: 'var(--color-text-secondary)' }}>
                                    {partner.userId?.email || partner.email || 'No email added'}
                                </p>
                            </div>

                            <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                                <InfoField label="Primary Name" value={partner.userId?.name} />
                                <InfoField label="Primary Email" value={partner.userId?.email || partner.email} />
                                <InfoField label="Partner Phone" value={partner.phone} />
                                <InfoField label="Contact Person" value={partner.contactPerson} />
                            </div>
                        </div>
                    )}

                    {tab === 'access' && (
                        <div className="space-y-6">
                            <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
                                <InfoField label="Portal Slug" value={partner.slug} />
                                <InfoField label="Registration Status" value={partner.registrationStatus} />
                                <InfoField label="Created On" value={new Date(partner.createdAt).toLocaleString()} />
                                <InfoField label="Last Updated" value={new Date(partner.updatedAt).toLocaleString()} />
                            </div>

                            {partner.registrationStatus === 'completed' && partner.loginUrl && (
                                <div className="rounded-3xl border p-5" style={{ borderColor: 'var(--color-border-default)', backgroundColor: '#FCFCFD' }}>
                                    <p className="text-sm font-semibold" style={{ color: 'var(--color-text-primary)' }}>Partner Login Portal</p>
                                    <div className="mt-4 flex flex-col gap-3 lg:flex-row">
                                        <div className="flex-1 rounded-2xl border px-4 py-3 text-sm" style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'white', color: 'var(--color-text-secondary)' }}>
                                            {partner.loginUrl}
                                        </div>
                                        <button
                                            onClick={() => copyText(partner.loginUrl!, 'Login portal link copied to clipboard!')}
                                            className="inline-flex items-center justify-center gap-2 rounded-2xl px-5 py-3 text-sm font-semibold text-white"
                                            style={{ backgroundColor: 'var(--color-primary)' }}
                                        >
                                            <Copy size={16} />
                                            Copy Login Link
                                        </button>
                                    </div>
                                </div>
                            )}

                            {partner.registrationStatus === 'pending' && partner.onboardingUrl && (
                                <div className="rounded-3xl border p-5" style={{ borderColor: 'var(--color-border-default)', backgroundColor: '#FCFCFD' }}>
                                    <p className="text-sm font-semibold" style={{ color: 'var(--color-text-primary)' }}>Onboarding Form Link</p>
                                    <div className="mt-4 flex min-w-0 flex-col gap-3 lg:flex-row lg:items-start">
                                        <div
                                            className="min-w-0 flex-1 rounded-2xl border px-4 py-3 text-sm break-all"
                                            style={{ borderColor: 'var(--color-border-default)', backgroundColor: 'white', color: 'var(--color-text-secondary)' }}
                                        >
                                            {partner.onboardingUrl}
                                        </div>
                                        <button
                                            onClick={() => copyText(partner.onboardingUrl!, 'Onboarding link copied to clipboard!')}
                                            className="inline-flex shrink-0 items-center justify-center gap-2 self-start rounded-2xl px-5 py-3 text-sm font-semibold text-white"
                                            style={{ backgroundColor: '#D97706' }}
                                        >
                                            <Copy size={16} />
                                            Copy Onboarding Link
                                        </button>
                                    </div>
                                </div>
                            )}

                            {partner.registrationStatus === 'pending' && (
                                <div className="rounded-3xl border p-5" style={{ borderColor: 'var(--color-border-default)', backgroundColor: '#FCFCFD' }}>
                                    <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
                                        <div>
                                            <p className="text-sm font-semibold" style={{ color: 'var(--color-text-primary)' }}>
                                                Regenerate Registration Link
                                            </p>
                                            <p className="mt-1 text-sm" style={{ color: 'var(--color-text-secondary)' }}>
                                                Generate a fresh onboarding link if the current one is lost or expired.
                                            </p>
                                        </div>
                                        <button
                                            onClick={handleRegenerate}
                                            disabled={isRegenerating}
                                            className="inline-flex items-center justify-center gap-2 rounded-2xl px-5 py-3 text-sm font-semibold text-white disabled:opacity-60"
                                            style={{ backgroundColor: 'var(--color-primary)' }}
                                        >
                                            {isRegenerating ? <RefreshCcw size={16} className="animate-spin" /> : <RefreshCcw size={16} />}
                                            Regenerate Link
                                        </button>
                                    </div>
                                </div>
                            )}
                        </div>
                    )}

                    {tab === 'clients' && (
                        <div>
                            {isClientsLoading ? (
                                <div className="text-center py-12">
                                    <div className="inline-block h-8 w-8 animate-spin rounded-full border-4 border-solid border-current border-r-transparent" style={{ color: 'var(--color-primary)' }}></div>
                                    <p className="mt-3 text-sm" style={{ color: 'var(--color-text-muted)' }}>Loading clients...</p>
                                </div>
                            ) : clients.length === 0 ? (
                                <div className="rounded-3xl border p-12 text-center" style={{ borderColor: 'var(--color-border-default)', backgroundColor: '#FCFCFD' }}>
                                    <p className="text-base font-medium" style={{ color: 'var(--color-text-muted)' }}>
                                        No clients found for this partner.
                                    </p>
                                </div>
                            ) : (
                                <div className="overflow-hidden rounded-3xl border" style={{ borderColor: 'var(--color-border-default)' }}>
                                    <table className="w-full">
                                        <thead>
                                            <tr className="bg-neutral-50 border-b" style={{ borderColor: 'var(--color-border-default)' }}>
                                                <th className="text-left px-6 py-4 text-xs font-semibold uppercase tracking-wider" style={{ color: 'var(--color-text-muted)' }}>
                                                    Client Name
                                                </th>
                                                <th className="text-left px-6 py-4 text-xs font-semibold uppercase tracking-wider" style={{ color: 'var(--color-text-muted)' }}>
                                                    Email
                                                </th>
                                                <th className="text-left px-6 py-4 text-xs font-semibold uppercase tracking-wider" style={{ color: 'var(--color-text-muted)' }}>
                                                    Status
                                                </th>
                                            </tr>
                                        </thead>
                                        <tbody className="bg-white divide-y" style={{ borderColor: 'var(--color-border-default)' }}>
                                            {clients.map((client: any) => (
                                                <tr key={client._id} className="hover:bg-neutral-50 transition-colors">
                                                    <td className="px-6 py-4 text-sm font-medium" style={{ color: 'var(--color-text-primary)' }}>
                                                        {client.name || '-'}
                                                    </td>
                                                    <td className="px-6 py-4 text-sm" style={{ color: 'var(--color-text-secondary)' }}>
                                                        {client.email || '-'}
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <span
                                                            className="inline-block px-2.5 py-1 rounded-full text-xs font-medium capitalize"
                                                            style={{
                                                                backgroundColor: client.status === 'active' ? '#ECFDF5' : '#F3F4F6',
                                                                color: client.status === 'active' ? '#059669' : '#6B7280',
                                                            }}
                                                        >
                                                            {client.status || '-'}
                                                        </span>
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            )}
                        </div>
                    )}

                    {tab === 'projects' && (
                        <div>
                            {isProjectsLoading ? (
                                <div className="text-center py-12">
                                    <div className="inline-block h-8 w-8 animate-spin rounded-full border-4 border-solid border-current border-r-transparent" style={{ color: 'var(--color-primary)' }}></div>
                                    <p className="mt-3 text-sm" style={{ color: 'var(--color-text-muted)' }}>Loading projects...</p>
                                </div>
                            ) : projects.length === 0 ? (
                                <div className="rounded-3xl border p-12 text-center" style={{ borderColor: 'var(--color-border-default)', backgroundColor: '#FCFCFD' }}>
                                    <p className="text-base font-medium" style={{ color: 'var(--color-text-muted)' }}>
                                        No projects found for this partner.
                                    </p>
                                </div>
                            ) : (
                                <div className="overflow-hidden rounded-3xl border" style={{ borderColor: 'var(--color-border-default)' }}>
                                    <table className="w-full">
                                        <thead>
                                            <tr className="bg-neutral-50 border-b" style={{ borderColor: 'var(--color-border-default)' }}>
                                                <th className="text-left px-6 py-4 text-xs font-semibold uppercase tracking-wider" style={{ color: 'var(--color-text-muted)' }}>
                                                    Project Name
                                                </th>
                                                <th className="text-left px-6 py-4 text-xs font-semibold uppercase tracking-wider" style={{ color: 'var(--color-text-muted)' }}>
                                                    Status
                                                </th>
                                            </tr>
                                        </thead>
                                        <tbody className="bg-white divide-y" style={{ borderColor: 'var(--color-border-default)' }}>
                                            {projects.map((project: any) => (
                                                <tr key={project._id} className="hover:bg-neutral-50 transition-colors">
                                                    <td className="px-6 py-4 text-sm font-medium" style={{ color: 'var(--color-text-primary)' }}>
                                                        {project.name || '-'}
                                                    </td>
                                                    <td className="px-6 py-4">
                                                        <span
                                                            className="inline-block px-2.5 py-1 rounded-full text-xs font-medium capitalize"
                                                            style={{
                                                                backgroundColor: project.status === 'active' ? '#DBEAFE' : '#F3F4F6',
                                                                color: project.status === 'active' ? '#1D4ED8' : '#6B7280',
                                                            }}
                                                        >
                                                            {project.status || '-'}
                                                        </span>
                                                    </td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

import { useState, useMemo } from 'react';
import {
    useGetPartnerEmployeesQuery,
    useCreatePartnerEmployeeMutation,
    useUpdatePartnerEmployeeMutation,
    useDeletePartnerEmployeeMutation,
    useTogglePartnerEmployeeStatusMutation,
    useResetPartnerEmployeePasswordMutation,
    useGetPartnerEmployeeStatsQuery,
    type PartnerEmployee,
} from '@/features/partners/partnerEmployeeApi';
import {
    Search,
    Users,
    ToggleLeft,
    ToggleRight,
    Pencil,
    Trash2,
    X,
    Eye,
    EyeOff,
    Key,
    UserPlus,
} from 'lucide-react';

export default function PartnerEmployeesPage() {
    const [page, setPage] = useState(1);
    const [search, setSearch] = useState('');
    const [statusFilter, setStatusFilter] = useState<'' | 'true' | 'false'>('');
    const [showModal, setShowModal] = useState(false);
    const [editingEmployee, setEditingEmployee] = useState<PartnerEmployee | null>(null);
    const [showPasswordModal, setShowPasswordModal] = useState(false);
    const [passwordEmployeeId, setPasswordEmployeeId] = useState<string | null>(null);
    const [newPassword, setNewPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);

    const [formData, setFormData] = useState({
        name: '',
        email: '',
        password: '',
        phone: '',
        designation: '',
        modulePermissions: {
            projectManagement: true,
            crm: false,
            teamManagement: false,
        },
    });

    const { data: employeesResponse, isLoading, isFetching } = useGetPartnerEmployeesQuery({
        page,
        limit: 20,
        search: search || undefined,
        isActive: statusFilter === '' ? undefined : statusFilter === 'true',
    });

    const { data: statsResponse } = useGetPartnerEmployeeStatsQuery();

    const [createEmployee, { isLoading: isCreating }] = useCreatePartnerEmployeeMutation();
    const [updateEmployee, { isLoading: isUpdating }] = useUpdatePartnerEmployeeMutation();
    const [deleteEmployee] = useDeletePartnerEmployeeMutation();
    const [toggleStatus, { isLoading: isToggling }] = useTogglePartnerEmployeeStatusMutation();
    const [resetPassword, { isLoading: isResettingPassword }] = useResetPartnerEmployeePasswordMutation();

    const employees = useMemo(() => employeesResponse?.data?.employees || [], [employeesResponse]);
    const total = employeesResponse?.data?.total || 0;
    const totalPages = employeesResponse?.data?.totalPages || 1;
    const stats = statsResponse?.data || { total: 0, active: 0, inactive: 0 };

    const handleOpenModal = (employee?: PartnerEmployee) => {
        if (employee) {
            setEditingEmployee(employee);
            setFormData({
                name: employee.name,
                email: employee.email,
                password: '',
                phone: employee.phone || '',
                designation: employee.designation || '',
                modulePermissions: employee.modulePermissions || {
                    projectManagement: true,
                    crm: false,
                    teamManagement: false,
                },
            });
        } else {
            setEditingEmployee(null);
            setFormData({
                name: '',
                email: '',
                password: '',
                phone: '',
                designation: '',
                modulePermissions: {
                    projectManagement: true,
                    crm: false,
                    teamManagement: false,
                },
            });
        }
        setShowModal(true);
    };

    const handleCloseModal = () => {
        setShowModal(false);
        setEditingEmployee(null);
        setFormData({
            name: '',
            email: '',
            password: '',
            phone: '',
            designation: '',
            modulePermissions: {
                projectManagement: true,
                crm: false,
                teamManagement: false,
            },
        });
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            if (editingEmployee) {
                await updateEmployee({
                    id: editingEmployee._id,
                    data: {
                        name: formData.name,
                        email: formData.email,
                        phone: formData.phone || undefined,
                        designation: formData.designation || undefined,
                        modulePermissions: formData.modulePermissions,
                    },
                }).unwrap();
            } else {
                await createEmployee({
                    name: formData.name,
                    email: formData.email,
                    password: formData.password,
                    phone: formData.phone || undefined,
                    designation: formData.designation || undefined,
                    modulePermissions: formData.modulePermissions,
                }).unwrap();
            }
            handleCloseModal();
        } catch (err: any) {
            alert(err.data?.message || 'Failed to save employee');
        }
    };

    const handleDelete = async (id: string, name: string) => {
        if (!window.confirm(`Are you sure you want to delete ${name}?`)) return;
        try {
            await deleteEmployee(id).unwrap();
        } catch (err: any) {
            alert(err.data?.message || 'Failed to delete employee');
        }
    };

    const handleToggleStatus = async (id: string) => {
        try {
            await toggleStatus(id).unwrap();
        } catch (err: any) {
            alert(err.data?.message || 'Failed to toggle status');
        }
    };

    const handleOpenPasswordModal = (id: string) => {
        setPasswordEmployeeId(id);
        setNewPassword('');
        setShowPasswordModal(true);
    };

    const handleResetPassword = async () => {
        if (!passwordEmployeeId || newPassword.length < 6) {
            alert('Password must be at least 6 characters');
            return;
        }
        try {
            await resetPassword({ id: passwordEmployeeId, newPassword }).unwrap();
            setShowPasswordModal(false);
            setPasswordEmployeeId(null);
            setNewPassword('');
            alert('Password reset successfully');
        } catch (err: any) {
            alert(err.data?.message || 'Failed to reset password');
        }
    };

    return (
        <div className="p-6 md:p-8 mx-auto" style={{ maxWidth: '1400px' }}>
            {/* Header */}
            <div className="flex items-center justify-between mb-8">
                <div className="flex items-center gap-4">
                    <div
                        className="w-14 h-14 rounded-2xl flex items-center justify-center shadow-sm"
                        style={{ backgroundColor: '#EEF2FF', color: '#4F46E5' }}
                    >
                        <Users size={28} strokeWidth={2.5} />
                    </div>
                    <div>
                        <h1 className="text-3xl font-bold" style={{ color: 'var(--color-text-primary)' }}>
                            Team Members
                        </h1>
                        <p className="text-base mt-1" style={{ color: 'var(--color-text-secondary)' }}>
                            Manage your team's access to the portal
                        </p>
                    </div>
                </div>

                <button
                    onClick={() => handleOpenModal()}
                    className="flex items-center gap-2 px-6 py-3 rounded-xl text-white font-semibold text-sm shadow-md hover:shadow-lg transition-all"
                    style={{ backgroundColor: '#4F46E5' }}
                >
                    <UserPlus size={18} strokeWidth={2.5} /> Add Team Member
                </button>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                <div className="p-6 rounded-2xl shadow-sm border" style={{ backgroundColor: 'white', borderColor: '#E5E7EB' }}>
                    <p className="text-xs font-semibold uppercase tracking-wider mb-2" style={{ color: '#6B7280' }}>
                        Total Members
                    </p>
                    <p className="text-3xl font-bold" style={{ color: '#4F46E5' }}>
                        {stats.total}
                    </p>
                </div>
                <div className="p-6 rounded-2xl shadow-sm border" style={{ backgroundColor: 'white', borderColor: '#E5E7EB' }}>
                    <p className="text-xs font-semibold uppercase tracking-wider mb-2" style={{ color: '#6B7280' }}>
                        Active Members
                    </p>
                    <p className="text-3xl font-bold" style={{ color: '#10B981' }}>
                        {stats.active}
                    </p>
                </div>
                <div className="p-6 rounded-2xl shadow-sm border" style={{ backgroundColor: 'white', borderColor: '#E5E7EB' }}>
                    <p className="text-xs font-semibold uppercase tracking-wider mb-2" style={{ color: '#6B7280' }}>
                        Inactive Members
                    </p>
                    <p className="text-3xl font-bold" style={{ color: '#EF4444' }}>
                        {stats.inactive}
                    </p>
                </div>
            </div>

            {/* Filters */}
            <div className="flex flex-wrap gap-4 mb-6 p-5 rounded-2xl shadow-sm border" style={{ backgroundColor: 'white', borderColor: '#E5E7EB' }}>
                <div className="relative flex-1 min-w-[280px]">
                    <Search
                        size={18}
                        className="absolute left-4 top-1/2 -translate-y-1/2"
                        style={{ color: '#9CA3AF' }}
                    />
                    <input
                        type="text"
                        value={search}
                        placeholder="Search by name, email, designation..."
                        onChange={(e) => {
                            setSearch(e.target.value);
                            setPage(1);
                        }}
                        className="w-full pl-12 pr-4 py-3 rounded-xl border text-sm font-medium transition-all focus:ring-2 focus:ring-indigo-500 focus:border-transparent"
                        style={{ borderColor: '#E5E7EB', backgroundColor: '#F9FAFB' }}
                    />
                </div>
                <select
                    value={statusFilter}
                    onChange={(e) => {
                        setStatusFilter(e.target.value as '' | 'true' | 'false');
                        setPage(1);
                    }}
                    className="px-5 py-3 rounded-xl border text-sm font-medium transition-all focus:ring-2 focus:ring-indigo-500 focus:border-transparent"
                    style={{ borderColor: '#E5E7EB', backgroundColor: '#F9FAFB' }}
                >
                    <option value="">All Status</option>
                    <option value="true">Active Only</option>
                    <option value="false">Inactive Only</option>
                </select>
            </div>

            {/* Table */}
            <div className="rounded-2xl shadow-sm border overflow-hidden" style={{ backgroundColor: 'white', borderColor: '#E5E7EB' }}>
                {isLoading || isFetching ? (
                    <div className="text-center py-20">
                        <div
                            className="inline-block h-10 w-10 animate-spin rounded-full border-4 border-solid border-current border-r-transparent"
                            style={{ color: '#4F46E5' }}
                        ></div>
                        <p className="mt-4 text-base font-medium" style={{ color: '#6B7280' }}>
                            Loading team members...
                        </p>
                    </div>
                ) : employees.length === 0 ? (
                    <div className="text-center py-20">
                        <Users size={64} className="mx-auto mb-4" style={{ color: '#D1D5DB' }} />
                        <p className="text-lg font-semibold" style={{ color: '#6B7280' }}>
                            No team members found
                        </p>
                        <p className="text-sm mt-1" style={{ color: '#9CA3AF' }}>
                            Add your first team member to get started
                        </p>
                    </div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead>
                                <tr className="bg-gray-50 border-b" style={{ borderColor: '#E5E7EB' }}>
                                    {['Name', 'Email', 'Phone', 'Designation', 'Status', 'Actions'].map((header) => (
                                        <th
                                            key={header}
                                            className={`text-xs font-semibold uppercase tracking-wider px-6 py-4 ${header === 'Actions' ? 'text-right' : 'text-left'}`}
                                            style={{ color: '#6B7280' }}
                                        >
                                            {header}
                                        </th>
                                    ))}
                                </tr>
                            </thead>
                            <tbody className="divide-y" style={{ borderColor: '#E5E7EB' }}>
                                {employees.map((employee) => (
                                    <tr key={employee._id} className="hover:bg-gray-50 transition-colors">
                                        <td className="px-6 py-5">
                                            <div className="text-sm font-semibold" style={{ color: '#111827' }}>
                                                {employee.name}
                                            </div>
                                        </td>
                                        <td className="px-6 py-5 text-sm" style={{ color: '#6B7280' }}>
                                            {employee.email}
                                        </td>
                                        <td className="px-6 py-5 text-sm" style={{ color: '#6B7280' }}>
                                            {employee.phone || '-'}
                                        </td>
                                        <td className="px-6 py-5 text-sm" style={{ color: '#6B7280' }}>
                                            {employee.designation || '-'}
                                        </td>
                                        <td className="px-6 py-5">
                                            <span
                                                className="text-xs font-semibold px-3 py-1.5 rounded-full"
                                                style={{
                                                    backgroundColor: employee.isActive ? '#ECFDF5' : '#FEF2F2',
                                                    color: employee.isActive ? '#059669' : '#DC2626',
                                                }}
                                            >
                                                {employee.isActive ? 'Active' : 'Inactive'}
                                            </span>
                                        </td>
                                        <td className="px-6 py-5">
                                            <div className="flex items-center justify-end gap-2">
                                                <button
                                                    onClick={() => handleOpenModal(employee)}
                                                    className="p-2 rounded-lg hover:bg-gray-100 transition-colors"
                                                    title="Edit"
                                                >
                                                    <Pencil size={16} style={{ color: '#6B7280' }} />
                                                </button>
                                                <button
                                                    onClick={() => handleOpenPasswordModal(employee._id)}
                                                    className="p-2 rounded-lg hover:bg-gray-100 transition-colors"
                                                    title="Reset Password"
                                                >
                                                    <Key size={16} style={{ color: '#6B7280' }} />
                                                </button>
                                                <button
                                                    onClick={() => handleToggleStatus(employee._id)}
                                                    disabled={isToggling}
                                                    className="p-2 rounded-lg hover:bg-gray-100 disabled:opacity-50 transition-colors"
                                                    title={employee.isActive ? 'Deactivate' : 'Activate'}
                                                >
                                                    {employee.isActive ? (
                                                        <ToggleRight size={18} style={{ color: '#10B981' }} />
                                                    ) : (
                                                        <ToggleLeft size={18} style={{ color: '#EF4444' }} />
                                                    )}
                                                </button>
                                                <button
                                                    onClick={() => handleDelete(employee._id, employee.name)}
                                                    className="p-2 rounded-lg hover:bg-red-50 transition-colors"
                                                    title="Delete"
                                                >
                                                    <Trash2 size={16} style={{ color: '#EF4444' }} />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}

                {/* Pagination */}
                {totalPages > 1 && (
                    <div className="flex items-center justify-between px-6 py-4 border-t" style={{ borderColor: '#E5E7EB', backgroundColor: '#F9FAFB' }}>
                        <span className="text-sm font-medium" style={{ color: '#6B7280' }}>
                            Page {page} of {totalPages} ({total} total)
                        </span>
                        <div className="flex gap-2">
                            <button
                                onClick={() => setPage((prev) => Math.max(1, prev - 1))}
                                disabled={page === 1}
                                className="px-4 py-2 text-sm font-medium rounded-xl border transition-all disabled:opacity-40 disabled:cursor-not-allowed hover:shadow-md"
                                style={{ borderColor: '#E5E7EB', backgroundColor: 'white' }}
                            >
                                Previous
                            </button>
                            <button
                                onClick={() => setPage((prev) => Math.min(totalPages, prev + 1))}
                                disabled={page >= totalPages}
                                className="px-4 py-2 text-sm font-medium rounded-xl border transition-all disabled:opacity-40 disabled:cursor-not-allowed hover:shadow-md"
                                style={{ borderColor: '#E5E7EB', backgroundColor: 'white' }}
                            >
                                Next
                            </button>
                        </div>
                    </div>
                )}
            </div>

            {/* Create/Edit Modal */}
            {showModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
                    <div className="bg-white rounded-2xl shadow-xl w-full max-w-md p-6 m-4">
                        <div className="flex items-center justify-between mb-6">
                            <h2 className="text-xl font-bold" style={{ color: '#111827' }}>
                                {editingEmployee ? 'Edit Team Member' : 'Add Team Member'}
                            </h2>
                            <button
                                onClick={handleCloseModal}
                                className="p-2 rounded-lg hover:bg-gray-100 transition-colors"
                            >
                                <X size={20} style={{ color: '#6B7280' }} />
                            </button>
                        </div>

                        <form onSubmit={handleSubmit} className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium mb-1.5" style={{ color: '#374151' }}>
                                    Name <span className="text-red-500">*</span>
                                </label>
                                <input
                                    type="text"
                                    required
                                    value={formData.name}
                                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                    className="w-full px-4 py-2.5 rounded-xl border focus:ring-2 focus:ring-indigo-500 focus:border-transparent"
                                    style={{ borderColor: '#E5E7EB' }}
                                    placeholder="John Doe"
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium mb-1.5" style={{ color: '#374151' }}>
                                    Email <span className="text-red-500">*</span>
                                </label>
                                <input
                                    type="email"
                                    required
                                    value={formData.email}
                                    onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                                    className="w-full px-4 py-2.5 rounded-xl border focus:ring-2 focus:ring-indigo-500 focus:border-transparent"
                                    style={{ borderColor: '#E5E7EB' }}
                                    placeholder="john@example.com"
                                />
                            </div>

                            {!editingEmployee && (
                                <div>
                                    <label className="block text-sm font-medium mb-1.5" style={{ color: '#374151' }}>
                                        Password <span className="text-red-500">*</span>
                                    </label>
                                    <div className="relative">
                                        <input
                                            type={showPassword ? 'text' : 'password'}
                                            required
                                            value={formData.password}
                                            onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                                            className="w-full px-4 py-2.5 pr-12 rounded-xl border focus:ring-2 focus:ring-indigo-500 focus:border-transparent"
                                            style={{ borderColor: '#E5E7EB' }}
                                            placeholder="••••••••"
                                            minLength={6}
                                        />
                                        <button
                                            type="button"
                                            onClick={() => setShowPassword(!showPassword)}
                                            className="absolute right-3 top-1/2 -translate-y-1/2 p-1"
                                        >
                                            {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                                        </button>
                                    </div>
                                </div>
                            )}

                            <div>
                                <label className="block text-sm font-medium mb-1.5" style={{ color: '#374151' }}>
                                    Phone
                                </label>
                                <input
                                    type="tel"
                                    value={formData.phone}
                                    onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                                    className="w-full px-4 py-2.5 rounded-xl border focus:ring-2 focus:ring-indigo-500 focus:border-transparent"
                                    style={{ borderColor: '#E5E7EB' }}
                                    placeholder="+1 234 567 8900"
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium mb-1.5" style={{ color: '#374151' }}>
                                    Designation
                                </label>
                                <input
                                    type="text"
                                    value={formData.designation}
                                    onChange={(e) => setFormData({ ...formData, designation: e.target.value })}
                                    className="w-full px-4 py-2.5 rounded-xl border focus:ring-2 focus:ring-indigo-500 focus:border-transparent"
                                    style={{ borderColor: '#E5E7EB' }}
                                    placeholder="Sales Manager"
                                />
                            </div>

                            {/* Module Permissions */}
                            <div className="pt-4 border-t" style={{ borderColor: '#E5E7EB' }}>
                                <label className="block text-sm font-semibold mb-3" style={{ color: '#374151' }}>
                                    Module Access Permissions
                                </label>
                                <div className="space-y-3">
                                    <label className="flex items-center gap-3 p-3 rounded-lg cursor-pointer hover:bg-gray-50 transition-colors">
                                        <input
                                            type="checkbox"
                                            checked={formData.modulePermissions.projectManagement}
                                            onChange={(e) =>
                                                setFormData({
                                                    ...formData,
                                                    modulePermissions: {
                                                        ...formData.modulePermissions,
                                                        projectManagement: e.target.checked,
                                                    },
                                                })
                                            }
                                            className="w-5 h-5 rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
                                        />
                                        <div className="flex-1">
