export default function ProjectDetailPage() {
    const { id } = useParams<{ id: string }>();
    const location = useLocation();
    const navigate = useNavigate();
    const { data, isLoading, error } = useGetProjectByIdQuery(id!, { refetchOnMountOrArgChange: 30 });
    const project = data?.data;
    const [showEditProjectPanel, setShowEditProjectPanel] = useState(false);
    const [isClosingEditProjectPanel, setIsClosingEditProjectPanel] = useState(false);

    const currentUser = useSelector((s: RootState) => s.auth.user);
    const roleName = currentUser?.role
        ? typeof currentUser.role === 'object'
            ? (currentUser.role as any).name?.toLowerCase()
            : String(currentUser.role).toLowerCase()
        : '';
    const isPartner = roleName === 'partner';
    const canManageProjectModule = hasModuleAdminAccess(currentUser, 'projectManagement') || isPartner;

    useEffect(() => {
        if (!showEditProjectPanel) {
            return;
        }

        const previousOverflow = document.body.style.overflow;
        document.body.style.overflow = 'hidden';

        const handleEsc = (event: KeyboardEvent) => {
            if (event.key === 'Escape') {
                setIsClosingEditProjectPanel(true);
            }
        };

        window.addEventListener('keydown', handleEsc);
        return () => {
            window.removeEventListener('keydown', handleEsc);
            document.body.style.overflow = previousOverflow;
        };
    }, [showEditProjectPanel]);

    useEffect(() => {
        if (!isClosingEditProjectPanel) {
            return;
        }

        const closeTimer = window.setTimeout(() => {
            setShowEditProjectPanel(false);
            setIsClosingEditProjectPanel(false);
        }, 280);

        return () => window.clearTimeout(closeTimer);
    }, [isClosingEditProjectPanel]);

    const handleCloseEditProjectPanel = () => {
        setIsClosingEditProjectPanel(true);
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center" style={{ minHeight: 'calc(100vh - 64px)' }}>
                <div className="flex items-center gap-2 text-sm" style={{ color: 'var(--color-text-secondary)' }}>
                    <Loader2 size={18} className="animate-spin" />
                    Loading project...
                </div>
            </div>
        );
    }

    if (error || !project) {
        return (
            <div className="flex items-center justify-center" style={{ minHeight: 'calc(100vh - 64px)' }}>
                <div className="flex items-center gap-2 text-sm" style={{ color: 'var(--color-danger)' }}>
                    <AlertCircle size={18} />
                    Project not found
                </div>
            </div>
        );
    }

    const sColors = statusColors[project.status] || statusColors.planning;
    const pColors = priorityColors[project.priority] || priorityColors.low;
    const projectPartnerId = typeof project.partnerId === 'object' ? (project.partnerId as any)?._id : project.partnerId;
    const projectPartner = typeof project.partnerId === 'object' ? (project.partnerId as any) : undefined;
    const projectPartnerName = projectPartner?.userId?.name || projectPartner?.contactPerson || projectPartner?.companyName;

    const pmPerms = currentUser?.modulePermissions?.projectManagement;
    // Find THIS project's specific permission entry
    const projectEntry = pmPerms?.projectPermissions?.find(p => p.projectId === id);
    const currentUserId = currentUser?._id;
    const currentAssignee = project.assignees?.find((assignee: any) => {
        const assigneeUserId = typeof assignee.userId === 'object' ? assignee.userId?._id : assignee.userId;
        const employeeUserId = typeof assignee.employeeId === 'object'
            ? (typeof assignee.employeeId?.userId === 'object' ? assignee.employeeId?.userId?._id : assignee.employeeId?.userId)
            : undefined;

        return assigneeUserId === currentUserId || employeeUserId === currentUserId;
    });
    const pmSubs = projectEntry?.subModules || currentAssignee?.subModules;

    const allTabs = [
        { name: 'Overview', path: `/projects/${id}`, icon: <LayoutDashboard size={15} />, exact: true, permKey: 'overview' },
        { name: 'Tasks', path: `/projects/${id}/tasks`, icon: <ListTodo size={15} />, exact: false, permKey: 'tasks' },
        { name: 'Time Logs', path: `/projects/${id}/timelogs`, icon: <Clock size={15} />, exact: false, permKey: 'timeLogs' },
        { name: 'Meetings', path: `/projects/${id}/meetings`, icon: <Video size={15} />, exact: false, permKey: 'meetings' },
        { name: 'Credentials', path: `/projects/${id}/credentials`, icon: <KeyRound size={15} />, exact: false, permKey: 'credentials' },
        { name: 'Documents', path: `/projects/${id}/documents`, icon: <FileText size={15} />, exact: false, permKey: 'documents' },
        { name: 'Notes', path: `/projects/${id}/notes`, icon: <StickyNote size={15} />, exact: false, permKey: 'notes' },
    ];
    const tabs = canManageProjectModule
        ? allTabs
        : allTabs.filter(t => pmSubs ? (pmSubs as Record<string, boolean>)[t.permKey] === true : false);

    // Redirect to first allowed tab if no overview access
    const isOnBasePath = location.pathname === `/projects/${id}`;
    if (!canManageProjectModule && isOnBasePath && pmSubs && !pmSubs.overview && tabs.length > 0) {
        return <Navigate to={tabs[0].path} replace />;
    }

    // No tabs at all or project not assigned = access denied
    if (!canManageProjectModule && tabs.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center" style={{ minHeight: 'calc(100vh - 120px)' }}>
                <div className="w-16 h-16 rounded-full flex items-center justify-center mb-4" style={{ backgroundColor: '#FEF2F2' }}>
                    <AlertCircle size={28} style={{ color: '#EF4444' }} />
                </div>
                <p className="text-base font-semibold" style={{ color: 'var(--color-text-primary)' }}>No Access</p>
                <p className="text-sm mt-1" style={{ color: 'var(--color-text-muted)' }}>You don't have permission to view any section of this project.</p>
                <button onClick={() => navigate('/dashboard')} className="mt-4 px-4 py-2 text-sm rounded-lg text-white" style={{ backgroundColor: 'var(--color-primary)' }}>Back to Dashboard</button>
            </div>
        );
    }

    const currentTabAllowed = tabs.some((tab) =>
        tab.exact ? location.pathname === tab.path : location.pathname.startsWith(tab.path)
    );
    if (!canManageProjectModule && !currentTabAllowed && tabs.length > 0) {
        return <Navigate to={tabs[0].path} replace />;
    }

    return (
        <div className="px-8 py-6" style={{ maxWidth: '1280px' }}>
            {/* Header */}
            <div className="flex justify-between items-start mb-6">
                <div>
                    <h1
                        className="text-xl font-semibold mb-1"
                        style={{ color: 'var(--color-text-primary)' }}
                    >
                        {project.name}
                    </h1>
                    {project.description && (
                        <p
                            className="text-sm"
                            style={{ color: 'var(--color-text-secondary)' }}
                        >
                            {project.description}
                        </p>
                    )}
                    {canManageProjectModule && !isPartner && projectPartnerId && projectPartnerName && (
                        <Link
                            to={`/admin/partners/manage/${projectPartnerId}`}
                            className="inline-flex items-center gap-2 mt-2 text-sm hover:underline"
                            style={{ color: 'var(--color-text-secondary)' }}
                        >
                            <Handshake size={14} />
                            Partner: {projectPartnerName}
                        </Link>
                    )}
                </div>

                <div className="flex gap-2 shrink-0 items-center">
                    <span
                        className="text-xs font-medium px-2.5 py-1 rounded-md capitalize"
                        style={{ backgroundColor: sColors.bg, color: sColors.text }}
                    >
                        {project.status}
                    </span>
                    <span
                        className="text-xs font-medium px-2.5 py-1 rounded-md capitalize"
                        style={{ backgroundColor: pColors.bg, color: pColors.text }}
                    >
                        {project.priority}
                    </span>
                    {canManageProjectModule && location.pathname === `/projects/${id}` && (
                        <button
                            type="button"
                            onClick={() => setShowEditProjectPanel(true)}
                            className="flex items-center gap-1.5 px-3.5 py-2 ml-2 text-sm font-semibold rounded-lg transition-colors"
                            style={{
                                backgroundColor: 'var(--color-primary)',
                                color: '#ffffff',
                            }}
                        >
                            <Pencil size={14} />
                            Edit Project
                        </button>
                    )}
                </div>
            </div>

            {/* Tabs */}
            <div
                className="border-b mb-6"
                style={{ borderColor: 'var(--color-border-default)' }}
            >
                <nav className="flex gap-0">
                    {tabs.map((tab) => {
                        const isActive = tab.exact
                            ? location.pathname === tab.path
                            : location.pathname.startsWith(tab.path);
                        return (
                            <Link
                                key={tab.path}
                                to={tab.path}
                                className="flex items-center gap-1.5 px-4 pb-3 text-sm font-medium border-b-2 transition-colors"
                                style={
                                    isActive
                                        ? {
                                            borderColor: 'var(--color-primary)',
                                            color: 'var(--color-primary-dark)',
                                        }
                                        : {
                                            borderColor: 'transparent',
                                            color: 'var(--color-text-secondary)',
                                        }
                                }
                            >
                                {tab.icon}
                                {tab.name}
                            </Link>
                        );
                    })}
                </nav>
            </div>

            {/* Tab Content */}
            <Outlet context={{ project }} />

            {showEditProjectPanel && createPortal(
                <>
                    <div
                        className="fixed inset-0 z-[200]"
                        style={{ backgroundColor: 'rgba(0,0,0,0.22)' }}
                        onClick={handleCloseEditProjectPanel}
                    />
                    <div
                        className="fixed top-0 right-0 h-full z-[201] flex flex-col"
                        style={{
                            width: 'min(860px, 100vw)',
                            backgroundColor: 'var(--color-bg-surface)',
                            borderLeft: '1px solid var(--color-border-default)',
                            boxShadow: '-16px 0 48px rgba(0,0,0,0.13)',
