                                                const mName = assignee.name || 'User';
                                                const mPhoto = (assignee as any).profilePhoto || null;
                                                const sel = subSelectedAssignees.includes(uid);
                                                return (
                                                    <button key={uid} type="button" onClick={() => toggleSubAssignee(uid)}
