                                            </div>

                                            {/* Priority badge */}
                                            <div className="hidden md:block col-span-1">
                                                <span className="text-[10px] font-medium px-1.5 py-0.5 rounded capitalize" style={{ backgroundColor: subP.bg, color: subP.text }}>
