                                    </p>
                                    <p className="mt-2 text-sm font-semibold" style={{ color: '#14532D' }}>
                                        {hasSubmitted ? 'Already submitted' : isTimeExpired ? 'Late window open' : 'Ready to submit'}
                                    </p>
