                            </div>

                            <div className="mt-7 rounded-2xl border p-5 md:p-6" style={{ borderColor: '#E2E8F0', backgroundColor: '#FFFFFF' }}>
                                <div className="flex items-center justify-between gap-3 flex-wrap">
