                    <p className="ml-1 mt-1.5 text-xs" style={{ color: 'var(--color-text-muted)' }}>{overrideMeta.helpText}</p>
                )}
                {error && <p className="ml-1 mt-1.5 text-xs font-semibold" style={{ color: '#B91C1C' }}>{error}</p>}
            </div>
        );
    }

    if (fieldId === 'github') {
        return (
            <div key={fieldId}>
