                                                        }}
                                                    >
                                                        <FileText size={20} />
                                                    </div>
                                                    <div className="min-w-0 flex-1">
                                                        <p className="truncate text-sm font-semibold" style={{ color: 'var(--color-text-primary)' }}>
                                                            {resume ? resume.name : 'Choose Resume File'}
                                                        </p>
                                                        <p className="mt-1 text-xs" style={{ color: 'var(--color-text-muted)' }}>
                                                            {resume
                                                                ? `${(resume.size / (1024 * 1024)).toFixed(2)} MB selected`
                                                                : 'PDF, DOC, or DOCX only. Maximum 5MB.'}
                                                        </p>
                                                    </div>
                                                    <span
                                                        className="rounded-full px-3 py-1 text-xs font-semibold"
                                                        style={{
                                                            backgroundColor: 'var(--color-bg-surface)',
                                                            color: 'var(--color-text-secondary)',
                                                            border: '1px solid var(--color-border-default)',
                                                        }}
                                                    >
                                                        {resume ? 'Change' : 'Browse'}
                                                    </span>
                                                </div>
                                            </label>
                                            {fieldErrors.resume && <p className="ml-1 mt-1.5 text-xs font-semibold" style={{ color: '#B91C1C' }}>{fieldErrors.resume}</p>}
                                            <p className="ml-1 mt-2 text-xs font-medium" style={{ color: 'var(--color-text-muted)' }}>
                                                Supported formats: PDF, DOC, DOCX. Max size: 5MB.
                                            </p>
                                        </div>

                                        <div className="pt-4">
                                            <button type="submit" disabled={isSubmitDisabled} className="inline-flex w-full items-center justify-center gap-2 rounded-full px-10 py-4 text-base font-bold text-white transition-all hover:-translate-y-0.5 sm:w-auto" style={{ backgroundColor: 'var(--color-primary)', opacity: isSubmitDisabled ? 0.6 : 1, boxShadow: isSubmitDisabled ? 'none' : '0 8px 20px -6px rgba(var(--color-primary-rgb), 0.5)' }}>
                                                {isLoading && <Loader2 size={18} className="animate-spin" />}
                                                Submit Application
                                            </button>
                                        </div>
                                    </form>
                                )}
                            </div>

                            <div className="z-20 space-y-6 lg:col-span-4 lg:sticky lg:top-6">
                                <div className="glass-card rounded-[2rem] p-8">
                                    <div className="mb-5 flex h-12 w-12 items-center justify-center rounded-2xl" style={{ backgroundColor: 'var(--color-primary)', color: 'white' }}>
                                        <Briefcase size={24} />
                                    </div>
                                    <p className="mb-2 text-xs font-bold uppercase tracking-widest" style={{ color: 'var(--color-text-muted)' }}>Applying For</p>
                                    <h2 className="mb-4 text-xl font-extrabold leading-tight" style={{ color: 'var(--color-text-primary)' }}>{job?.title}</h2>
                                    <div className="flex flex-col gap-3">
                                        <div className="flex items-center gap-2 text-sm font-semibold" style={{ color: 'var(--color-text-secondary)' }}><Building2 size={16} className="opacity-70" /> {job?.department || 'Department not specified'}</div>
                                        <div className="flex items-center gap-2 text-sm font-semibold" style={{ color: 'var(--color-text-secondary)' }}><MapPin size={16} className="opacity-70" /> {jobLocationLabel}</div>
                                        <div className="flex items-center gap-2 text-sm font-semibold" style={{ color: 'var(--color-text-secondary)' }}><Briefcase size={16} className="opacity-70" /> {employmentTypeLabel}</div>
                                    </div>
                                </div>

                                <div className="glass-card rounded-[2rem] p-8">
                                    <div className="mb-4 flex h-10 w-10 items-center justify-center rounded-xl border" style={{ borderColor: 'var(--color-border-subtle)', backgroundColor: 'var(--color-bg-subtle)' }}>
                                        <CheckCircle2 size={20} style={{ color: 'var(--color-text-primary)' }} />
                                    </div>
                                    <h3 className="mb-4 text-lg font-bold" style={{ color: 'var(--color-text-primary)' }}>Application Tips</h3>
                                    <ul className="space-y-4 text-sm font-medium" style={{ color: 'var(--color-text-secondary)' }}>
                                        <li>Keep your resume aligned with this role.</li>
                                        <li>Add links only where they strengthen your application.</li>
                                        <li>Use the custom questions to show role-specific proof, not generic text.</li>
                                    </ul>
                                </div>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAppSelector, useAppDispatch } from '@/app/hooks';
import { logout } from '@/features/auth/slices/authSlice';
import { useLogoutMutation } from '@/features/auth/authApi';
import { useGetMyProfileQuery } from '@/features/hrms/hrmsApi';
import { api } from '@/services/api';
import {
    FolderKanban, DollarSign, Users, Building2, Shield,
    ArrowRight, Clock, LogOut, Sparkles, Settings, Briefcase, Handshake
} from 'lucide-react';
import NotificationBell from '@/features/notification/components/NotificationBell';
import NotificationPanel from '@/features/notification/components/NotificationPanel';
import { useNotificationSocket } from '@/features/notification/hooks/useNotificationSocket';
import { useCheckJobManagerStatusQuery } from '@/features/hiring/hiringApi';
import { hasModuleViewAccess } from '@/utils/modulePermissions';


/* ── Module definitions ──────────────────────────────────── */
interface Department {
    key: string;
    title: string;
    description: string;
    icon: React.ReactNode;
    path: string;
    accentFrom: string;
    accentTo: string;
    isActive: boolean;
}

const MODULE_ACCENTS: Record<string, { from: string; to: string }> = {
    projectManagement: { from: '#059669', to: '#0EA5E9' },
    finance: { from: '#7C3AED', to: '#EC4899' },
    crm: { from: '#EA580C', to: '#F59E0B' },
    hrms: { from: '#0369A1', to: '#06B6D4' },
    overallAdmin: { from: '#374151', to: '#6B7280' },
    hiring: { from: '#0F766E', to: '#0EA5E9' },
    partners: { from: '#0E7490', to: '#06B6D4' },
    teamManagement: { from: '#6366F1', to: '#8B5CF6' },
};

/* ── Department Card ─────────────────────────────────────── */
function DepartmentCard({ title, description, icon, path, isActive, accentFrom, accentTo }: Department) {
    const navigate = useNavigate();

    return (
        <div
            onClick={() => isActive && navigate(path)}
            className="relative rounded-2xl border overflow-hidden transition-all duration-200 group"
            style={{
                backgroundColor: 'var(--color-bg-surface)',
                borderColor: 'var(--color-border-default)',
                cursor: isActive ? 'pointer' : 'not-allowed',
                opacity: isActive ? 1 : 0.55,
                boxShadow: 'var(--shadow-xs)',
            }}
            onMouseEnter={(e) => {
                if (!isActive) return;
                e.currentTarget.style.transform = 'translateY(-3px)';
                e.currentTarget.style.boxShadow = 'var(--shadow-lg)';
                e.currentTarget.style.borderColor = accentFrom + '50';
            }}
            onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'translateY(0)';
                e.currentTarget.style.boxShadow = 'var(--shadow-xs)';
                e.currentTarget.style.borderColor = 'var(--color-border-default)';
            }}
        >
            {/* Gradient accent strip */}
            <div
                className="absolute top-0 left-0 right-0 h-1"
                style={{ background: `linear-gradient(90deg, ${accentFrom}, ${accentTo})`, opacity: isActive ? 1 : 0.4 }}
            />

            <div className="p-6 pt-7">
                {/* Icon */}
                <div
                    className="w-12 h-12 rounded-xl flex items-center justify-center mb-5"
                    style={{
                        background: `linear-gradient(135deg, ${accentFrom}20, ${accentTo}20)`,
                        border: `1px solid ${accentFrom}30`,
                    }}
                >
                    <div style={{ color: accentFrom }}>{icon}</div>
                </div>

                {/* Text */}
                <h3
                    className="text-base font-bold mb-1.5"
                    style={{ color: 'var(--color-text-primary)', fontFamily: 'Outfit, sans-serif' }}
                >
                    {title}
                </h3>
                <p className="text-sm leading-relaxed" style={{ color: 'var(--color-text-muted)' }}>
                    {description}
                </p>

                {/* Footer row */}
                <div className="flex items-center justify-between mt-5 pt-4" style={{ borderTop: '1px solid var(--color-border-default)' }}>
                    {isActive ? (
                        <span
                            className="text-xs font-semibold px-2.5 py-1 rounded-full"
                            style={{ background: accentFrom + '15', color: accentFrom }}
                        >
                            Active
                        </span>
                    ) : (
                        <span
                            className="flex items-center gap-1 text-xs font-semibold px-2.5 py-1 rounded-full"
                            style={{ backgroundColor: 'var(--color-bg-subtle)', color: 'var(--color-text-muted)' }}
                        >
                            <Clock size={10} />
                            Coming Soon
                        </span>
                    )}

                    {isActive && (
                        <div
                            className="w-7 h-7 rounded-full flex items-center justify-center transition-all duration-200 opacity-0 group-hover:opacity-100"
                            style={{ background: accentFrom + '15', color: accentFrom }}
                        >
                            <ArrowRight size={14} />
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

/* ── Main Dashboard ──────────────────────────────────────── */
export default function SuperAdminDashboard() {
    const dispatch = useAppDispatch();
    const navigate = useNavigate();
    const user = useAppSelector((state) => state.auth.user);

    const [logoutApi] = useLogoutMutation();

    // Initialize notification socket listeners
    useNotificationSocket();

    const { data: jobManagerStatus } = useCheckJobManagerStatusQuery();
    const isJobManager = !!jobManagerStatus?.data?.isJobManager;

    const roleName = user?.role
        ? typeof user.role === 'object'
            ? (user.role as any).name?.toLowerCase()
            : String(user.role).toLowerCase()
        : '';
    const isPartner = roleName === 'partner';
    const displayRole = user?.role
        ? typeof user.role === 'object'
            ? (user.role as any).name
            : String(user.role)
        : 'User';

    const handleLogout = async () => {
        try { await logoutApi().unwrap(); } catch { /* ignore */ }

        // Determine logout redirect based on user role and partner status
        const partnerSlug = (user as any)?.partnerSlug || (
            typeof window !== 'undefined' ? window.sessionStorage.getItem('partnerPortalSlug') : null
        );

        // Redirect to partner's personalized login page if they have a slug
        const logoutPath = isPartner && partnerSlug
            ? `/partner/${partnerSlug}/login`
            : isPartner
                ? '/partner/login'
                : '/login';

        if (typeof window !== 'undefined') {
            window.location.replace(logoutPath);
            return;
        }

        dispatch(logout());
        dispatch(api.util.resetApiState());
        navigate(logoutPath);
    };


    const { data: profileData } = useGetMyProfileQuery(undefined, { skip: isPartner });
    const profilePhotoUrl = (profileData?.data?.employee as any)?.profilePhoto?.url;

    const mp = user?.modulePermissions;

    const [now, setNow] = useState(new Date());

    useEffect(() => {
        const intervalId = setInterval(() => {
            setNow(new Date());
        }, 1000); // Ticks every second

        return () => clearInterval(intervalId); // Cleanup on unmount
    }, []);

    const timeStr = now.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' });
    const dateStr = now.toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });

    const allDepartments = [
        {
            key: 'projectManagement',
            title: 'Project Management',
            description: 'Manage projects, tasks, time logs and team collaboration',
            icon: <FolderKanban size={22} />,
            path: '/projects',
        },
        {
            key: 'finance',
            title: 'Finance',
            description: 'Track expenses, invoices, and financial reports',
            icon: <DollarSign size={22} />,
            path: '/finance',
        },
        {
            key: 'crm',
            title: 'CRM',
            description: 'Customer relationship management and sales tracking',
            icon: <Users size={22} />,
            path: '/crm',
        },
        {
            key: 'hrms',
            title: 'HRMS',
            description: 'Human resource management and employee records',
            icon: <Building2 size={22} />,
            path: '/hrms',
        },
        {
            key: 'overallAdmin',
            title: 'Overall Admin',
            description: 'System administration, user permissions and settings',
            icon: <Shield size={22} />,
            path: '/admin',
        },
        {
            key: 'partners',
            title: 'Partners',
            description: 'Manage partner onboarding, attribution and performance',
            icon: <Handshake size={22} />,
            path: '/admin/partners/dashboard',
        },
        {
            key: 'hiring',
            title: 'Hiring',
            description: 'Manage job postings, candidates, assignments, and interviews',
            icon: <Briefcase size={22} />,
            path: '/hiring',
        },
    ];

    const partnerDepartments = [
        // Team Management is optional for partner employees, always available for main partner account.
        ...(user?.isPartnerEmployee && mp?.teamManagement?.enabled !== true
            ? []
            : [{
                key: 'teamManagement',
                title: 'Team Management',
                description: 'Manage your team members, access and credentials',
                icon: <Users size={22} />,
                path: '/partner-admin/team',
                isActive: true,
                accentFrom: MODULE_ACCENTS.teamManagement.from,
                accentTo: MODULE_ACCENTS.teamManagement.to,
            }]),
        // Project Management and CRM based on permissions
        ...allDepartments
            .filter(d => d.key === 'projectManagement' || d.key === 'crm')
            .filter(d => {
                const perm = mp?.[d.key as keyof typeof mp] as any;
                return !!perm?.enabled;
            })
            .map(d => ({
                ...d,
                isActive: true,
                accentFrom: MODULE_ACCENTS[d.key].from,
                accentTo: MODULE_ACCENTS[d.key].to,
            })),
    ];

    const nonAdminDepartments = allDepartments
        .filter(d => {
            if (!['projectManagement', 'finance', 'crm', 'hrms', 'overallAdmin', 'partners', 'hiring'].includes(d.key)) return false;
            if (!hasModuleViewAccess(user, d.key as any, { isJobManager })) return false;
            return true;
        })
        .map(d => ({
            ...d,
            isActive: true,
            accentFrom: MODULE_ACCENTS[d.key].from,
            accentTo: MODULE_ACCENTS[d.key].to,
        }));

    const departments: Department[] = isPartner
            ? partnerDepartments
            : nonAdminDepartments;

    const firstName = user?.name?.split(' ')[0] || 'there';

