    const brandName = isPartner && partnerCompanyName ? partnerCompanyName : 'CUOS';
    const brandSubtitle = isPartner && partnerCompanyName ? 'Partner Portal' : 'Creative Upaay';
    // const brandInitials = isPartner && partnerCompanyName
    //     ? partnerCompanyName.split(' ').map((w: string) => w[0]).join('').toUpperCase().slice(0, 2)
    //     : 'CU';

    return (
        <div className="min-h-screen flex flex-col" style={{
            background: isPartner
                ? 'linear-gradient(to bottom right, #EEF2FF, #FEFEFE, #F3E8FF)'
                : 'var(--color-bg-app)'
        }}>

            {/* ── Top Navigation Bar ────────────────────────────────── */}
            <header
                className="border-b sticky top-0 z-30"
                style={{
                    background: 'rgba(255,255,255,0.90)',
                    backdropFilter: 'blur(16px)',
                    borderColor: 'var(--color-border-default)',
                    boxShadow: 'var(--shadow-xs)',
                }}
            >
                <div className="flex items-center justify-between px-6 h-14" style={{ maxWidth: '1300px', margin: '0 auto' }}>
                    {/* Brand */}
                    <div className="flex items-center gap-3">
                        {partnerCompanyLogo && isPartner ? (
                            <img
                                src={partnerCompanyLogo}
                                alt={brandName}
                                className="h-8 w-auto object-contain"
                            />
                        ) : (
                            <img
                                src="/company-logo2.png"
                                alt="Company Logo"
                                className="h-8 w-auto object-contain"
                            />
                        )}
                        <div>
                            <div
                                className="font-bold text-sm leading-tight"
                                style={{ fontFamily: 'Outfit, sans-serif', color: 'var(--color-text-primary)' }}
                            >
                                {brandName}
                            </div>
                            <div className="text-[10px]" style={{ color: 'var(--color-text-muted)' }}>
                                {brandSubtitle}
                            </div>
                        </div>
                    </div>

                    {/* User + Logout */}
                    <div className="flex items-center gap-3">
                        <div className="flex items-center gap-2.5 pr-3" style={{ borderRight: '1px solid var(--color-border-default)' }}>
                            <div className="text-right hidden sm:block">
                                <div className="text-sm font-semibold leading-tight" style={{ color: 'var(--color-text-primary)' }}>
                                    {user?.name || 'User'}
                                </div>
                                <div
                                    className="text-[10px] font-medium px-1.5 py-0.5 rounded-full capitalize inline-block mt-0.5"
                                    style={{
                                        background: 'var(--color-primary-soft)',
                                        color: 'var(--color-primary-dark)',
                                    }}
                                >
                                    {displayRole}
                                </div>
                            </div>

                            <div className="shrink-0">
                                {profilePhotoUrl ? (
                                    <img
                                        src={profilePhotoUrl}
                                        alt={user?.name || 'Profile'}
                                        className="w-8 h-8 rounded-full object-cover"
                                        style={{ boxShadow: 'var(--shadow-brand)' }}
                                    />
                                ) : (
                                    <div
                                        className="w-8 h-8 rounded-full flex items-center justify-center text-white text-xs font-bold"
                                        style={{ background: 'linear-gradient(135deg,#059669,#0EA5E9)', boxShadow: 'var(--shadow-brand)' }}
                                    >
                                        {user?.name?.split(' ').map((n: string) => n[0]).join('').toUpperCase().slice(0, 2) || 'U'}
                                    </div>
                                )}
                            </div>

                            <Link
                                to="/my-hrms/profile"
                                title="My Profile & Settings"
                                className="flex items-center justify-center w-7 h-7 rounded-lg shrink-0 transition-colors hover:bg-gray-100 ml-1.5"
                                style={{ color: 'var(--color-text-muted)' }}
                            >
                                <Settings size={15} />
                            </Link>
                        </div>

                        {/* Notification Bell */}
                        <div className="flex items-center pr-1">
                            <NotificationBell />
                        </div>

                        <button
                            onClick={handleLogout}
                            className="btn btn-ghost"
                            style={{ height: '34px', padding: '0 12px', gap: '6px' }}
                        >
                            <LogOut size={14} />
                            <span className="hidden sm:inline">Logout</span>
                        </button>
                    </div>
